schemas.schema-01-systematic.prisma:
/// Category definitions - Implements the business requirement for persistent, configurable categorized discussion areas (Feature 1, Posting/Thread Management, and project objectives). This model enables separation of discussion spaces for workflow and access control, mapping category names to public/posting/finding/review requirements. Maintains 3NF as all values are atomic and not derived. Example: 'Help', 'Announcements', 'General'. Key relationships: Many posts belong to a category; tags assigned via category_tags. Special behaviors: Name must be unique, soft deletion allowed, audit trail via timestamps.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Category name - uniquely identifies the category as required for post/thread assignment and category configuration. Maintains normalization by being atomic and single-purpose. Used in category selectors, post creation, audit logs, moderation workflows. Must be unique.
  name String

  /// Optional description for category - guides admins and users about the category’s purpose. Null allowed for concise categories, maintains 3NF by only referencing this category. Used in UI help/tooltips.
  description String?

  /// Category creation timestamp - implements audit and compliance requirements for traceability. Maintains normalization as atomic event log. Used for sorting/filtering, admin review, audit logs.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last admin modification - maps to admin/audit requirements for configuration changes. Used in admin UIs, audit trails, compliance routines. Maintains 3NF.
  updated_at DateTime @db.Timestamptz

  /// Timestamp for soft deletion (if the category is deleted but should remain for policy/history). Maintains normalization as atomic value and complies with audit/recovery requirements. Used in policy enforcement, safe removes, and potential category restoration. Nullable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category_tags discussion_board_category_tags[]
  discussion_board_post_categories discussion_board_post_categories[]

  @@unique([name])
  @@index([created_at])
}

/// Tag definitions - Implements tagging and flexible content categorization requirements (referenced in project overview, feature spec, usability/accessibility). Enables UIs and admin policies for discoverability, faceted navigation, and access control. Maintains 3NF with atomic, non-derived values. Example: 'urgent', 'release', 'staff'. Relationships: Assigned to categories via category_tags; may be assigned to posts/comments elsewhere. Special behaviors: 'label' must be unique, soft deletion for compliance/audit, optional color for UI display.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Short text label for the tag - enables tagging UI, content filtering, and administrative assignment. Atomic and normalized; uniquely identifies tag for assignment. Used in create/search/sort navigation. Must be unique.
  label String

  /// Optional description for this tag - displayed to admins or users for clarity. Maintains 3NF as atomic, non-derived value. Nullable for lightweight tags.
  description String?

  /// Tag color code (HTML hex or class) for display/UI cues - implements branding/accessibility. Normalized as atomic attribute, not required. Nullable.
  color String?

  /// Creation timestamp, for administrative/audit trail compliance and tag lifecycle management. Non-nullable, atomic, and normalized. Used in filtering/audit.
  created_at DateTime @db.Timestamptz

  /// Timestamp for admin modifications (e.g., label, color) to this tag. Implements audit traceability and admin compliance. Used in change logging and admin review.
  updated_at DateTime @db.Timestamptz

  /// Timestamp marking tag as soft-deleted (if ever removed for compliance/policy). Supports safe deletion/feature-recovery as per requirements. Nullable; maintains normalization.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category_tags discussion_board_category_tags[]
  discussion_board_post_tags discussion_board_post_tags[]

  @@unique([label])
  @@index([created_at])
}

/// Junction: Category/Tag assignment - Implements flexible M:N category x tag linkage required for configurable board structure (allowing each category to have multiple tags and each tag to apply to multiple categories). Fulfills normalized structure by storing only category-tag pairs; no derived or aggregate fields present. Example usage: associating 'urgent' with 'Help', 'release' with 'Announcements'. Key relationships: Many-to-one to discussion_board_categories and discussion_board_tags. Special behaviors: Composite uniqueness of (category, tag), assignment timestamp for audit.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_category_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked category's id - foreign key to {@link discussion_board_categories.id}. Implements requirement for linking categories to tags via junction. Not unique, required.
  discussion_board_category_id String @db.Uuid

  /// Linked tag's id - foreign key to {@link discussion_board_tags.id}. Allows assignment of tags to categories. Not unique, required.
  discussion_board_tag_id String @db.Uuid

  /// Assignment timestamp for when this tag was linked to this category. Atomic event for audit/compliance; maintains 3NF.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  category discussion_board_categories @relation(fields: [discussion_board_category_id], references: [id], onDelete: Cascade, map: "discussion_board_category_tags_discussion_board_catego_04333f08")
  tag discussion_board_tags @relation(fields: [discussion_board_tag_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_category_id, discussion_board_tag_id], map: "discussion_board_category_tags_discussion_board_catego_2da3c6c9")
  @@index([discussion_board_tag_id, discussion_board_category_id], map: "discussion_board_category_tags_discussion_board_tag_id_fa09fd02")
}

/// Board/global configuration - Implements requirement for systematic, single-source, board-level settings and branding (project overview, admin permissions, setup, and configuration features). All fields are atomic and not derived, supporting complete normalization for configuration data. Example: board title/configuration for branding or policy. Relationships: not referenced by other domains as FK. Special behaviors: Typically single-row; optional logo/support for branding; enabled/disabled toggling for maintenance. All configuration edits recorded via updated_at.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_board_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key (expected single-row only).
  id String @id @db.Uuid

  /// Board title for branding and user-facing display. Implements requirement for customizable system header/branding. Maintains normalization as atomic attribute. Used in UI, welcome screens.
  title String

  /// Optional board description shown on landing pages and board information modals. Implements requirement for user guidance and compliance context. Nullable, atomic.
  description String?

  /// Whether this board is active/enabled (vs. offline/maintenance). Implements admin control requirement for access/mode. Used to survive maintenance/disable in a single config place. Atomic, mapped 1:1 to admin toggle.
  enabled Boolean

  /// Optional logo image (display URI). Implements branding/config requirement for admins; nullable for minimalist boards; maintains 3NF as atomic value.
  logo_uri String?

  /// When this board setup/config record was created. Implements system audit and admin requirements for setup history. Used during operations/audit.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last configuration update/change. Maintains full normalization as atomic value and supports requirement for admin audit/rollback.
  updated_at DateTime @db.Timestamptz
}

schemas.schema-02-actors.prisma:
/// Explicit administrator account model - This implements the requirement for explicit admin role (see Roles and Permissions doc). Enables granular access control, permission enforcement, and auditability for administrator actions. 3NF normalization: business fields atomic (username, password_hash, email), no calculated values. Used for authentication, role assignment, and audit tracking. Key relationships: referenced by moderator promotions, moderation records. Special behaviors: username/email uniqueness and active flag enforcement.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Admin's unique username used for authentication and audit tracking. Implements explicit admin identity, mapped to the Roles and Permissions requirement. Each admin must have an immutable, account-unique name.
  username String

  /// Secure password hash (not plaintext) for authentication. Implements security and data integrity requirement. No business logic outside authentication.
  password_hash String

  /// Admin's business email. Implements requirement for notification and account recovery. Uniqueness ensures clear identity reference.
  email String

  /// Whether this admin account is currently authorized. Requirement: immediate permission enforcement upon promotion/suspension.
  is_active Boolean

  /// Timestamp marking admin account creation. Requirement: audit trail/auditability; supports analytics.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for admin account. Implements audit trail and policy updates requirement for traceability.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_moderators discussion_board_moderators[]
  discussion_board_content_reports discussion_board_content_reports[]
  discussion_board_moderation_actions discussion_board_moderation_actions[]
  discussion_board_appeals discussion_board_appeals[]
  discussion_board_suspensions_of_suspended_admin_id discussion_board_suspensions[] @relation("discussion_board_suspensions_of_suspended_admin_id")
  discussion_board_suspensions_of_admin_id discussion_board_suspensions[] @relation("discussion_board_suspensions_of_admin_id")
  discussion_board_audit_logs discussion_board_audit_logs[]
  discussion_board_notifications discussion_board_notifications[]
  discussion_board_notification_settings discussion_board_notification_settings?
  discussion_board_auth_tokens discussion_board_auth_tokens[]
  discussion_board_access_logs discussion_board_access_logs[]

  @@unique([username])
  @@unique([email])
  @@index([created_at])
}

/// Moderator account with explicit separation from admin and member roles - Implements moderator-specific requirements (see Roles and Permissions, Moderation Policy). Maintains normalized role boundaries; supports permission enforcement and audit-log promotion tracking. Used for authentication, access, and audit logs. Key relationships: references discussion_board_admins by promoted_by_admin_id. 3NF enforced. Special behaviors: account activation and promotion traceability.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Admin's {@link discussion_board_admins.id} who last promoted this moderator. Enables audit-trail and RBAC traceability.
  promoted_by_admin_id String? @db.Uuid

  /// Moderator's username used for login and unique session. Implements moderator identity, not shared with admins.
  username String

  /// Moderator's secure password hash for authentication. Implements security and data integrity requirement.
  password_hash String

  /// Moderator's email for communication and notification purposes.
  email String

  /// Current active status for this moderator (permission enforcement).
  is_active Boolean

  /// Account creation timestamp for auditability/tracking.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp for moderator account.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  promoter discussion_board_admins? @relation(fields: [promoted_by_admin_id], references: [id], onDelete: Cascade)

  discussion_board_content_reports discussion_board_content_reports[]
  discussion_board_moderation_actions discussion_board_moderation_actions[]
  discussion_board_appeals discussion_board_appeals[]
  discussion_board_suspensions_of_suspended_moderator_id discussion_board_suspensions[] @relation("discussion_board_suspensions_of_suspended_moderator_id")
  discussion_board_suspensions_of_moderator_id discussion_board_suspensions[] @relation("discussion_board_suspensions_of_moderator_id")
  discussion_board_audit_logs discussion_board_audit_logs[]
  discussion_board_notifications discussion_board_notifications[]
  discussion_board_notification_settings discussion_board_notification_settings?
  discussion_board_auth_tokens discussion_board_auth_tokens[]
  discussion_board_access_logs discussion_board_access_logs[]

  @@unique([username])
  @@unique([email])
  @@index([promoted_by_admin_id])
}

/// Member account table for authenticated content contributors - Implements member role separation and audit requirements from Feature Spec and Roles doc. Supports atomic member-only fields: display_name, email, password, is_verified, status, last_login_at. Used for board participation, access control, and behavioral analytics. 3NF normalization ensures all fields atomic, no calculated aggregates. Key relationships: referenced by content, moderation, and notification tables. Special behavior: verification and permission status.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Display name for UI and participant identification. Implements member identity requirement. Must be unique per member for display purposes, not system-unique.
  display_name String

  /// Member's email for notifications and authentication. Implements communication and uniqueness constraint requirement.
  email String

  /// Password hash (not plaintext); authentication only.
  password_hash String

  /// Whether member is verified (e.g. email confirmed); permission escalation requirement.
  is_verified Boolean

  /// Member registration timestamp for audit trail and analytics.
  registered_at DateTime @db.Timestamptz

  /// Current permission status of member (active, suspended, banned). Implements immediate enforcement requirement.
  status String

  /// Timestamp of last login (nullable). For analytics and re-engagement. Null if never logged in.
  last_login_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_posts discussion_board_posts[]
  discussion_board_comments discussion_board_comments[]
  discussion_board_post_votes discussion_board_post_votes[]
  discussion_board_comment_votes discussion_board_comment_votes[]
  discussion_board_comment_edits discussion_board_comment_edits[]
  discussion_board_post_edits discussion_board_post_edits[]
  discussion_board_content_reports discussion_board_content_reports[]
  discussion_board_appeals discussion_board_appeals[]
  discussion_board_suspensions discussion_board_suspensions[]
  discussion_board_audit_logs discussion_board_audit_logs[]
  discussion_board_notifications discussion_board_notifications[]
  discussion_board_notification_settings discussion_board_notification_settings?
  discussion_board_auth_tokens discussion_board_auth_tokens[]
  discussion_board_access_logs discussion_board_access_logs[]

  @@unique([email])
  @@index([display_name])
}

/// Guest session/account representation - Implements requirements for guests to have visible, minimally tracked presence (for access, audit, and deduplication only). Contains only atomic data: id (session UUID), guest_ip (for minimal audit), session_token (for deduplication not authentication), entered_at. Used by content and access domains for logging and abuse detection. 3NF ensured, no account-linkage or calculated fields.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// IP address for guest identification. Requirement: minimal audit-trail for legal/compliance.
  guest_ip String

  /// Session-specific identifier or browser fingerprint. For deduplication only.
  session_token String

  /// Timestamp when guest first entered (session start time). Analytics and tracking.
  entered_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_content_reports discussion_board_content_reports[]
  discussion_board_appeals discussion_board_appeals[]
  discussion_board_suspensions discussion_board_suspensions[]
  discussion_board_audit_logs discussion_board_audit_logs[]
  discussion_board_notifications discussion_board_notifications[]
  discussion_board_notification_settings discussion_board_notification_settings?
  discussion_board_auth_tokens discussion_board_auth_tokens[]
  discussion_board_access_logs discussion_board_access_logs[]

  @@index([guest_ip])
}

schemas.schema-03-content.prisma:
/// Discussion board posts entity - This implements the core posting and thread management requirements from the requirements document. Business purpose: to store user-created posts, support nesting for threaded discussions, maintain ownership attribution via member links, and provide edit/delete auditability via history relationships. Maintains strict 3NF normalization by making all data atomic and referencing other entities via foreign keys only. For example, posts can be filtered by category/tag, searched by content, or linked to moderation workflows. Key relationships: belongs to a member (author), may have parent (for threading), linked to tags/categories (junctions), has comments, votes, and full edit audit trail. Special behaviors: soft deletion, GIN index for full-text search, multi-level hierarchy via parent_id.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Implements the requirement for uniquely identifiable posts while supporting audit, edit/delete traceability, and hierarchical structuring for discussions.
  id String @id @db.Uuid

  /// Author of the post - references existing discussion_board_members table. Implements user attribution for all posting activity. Normalization: 3NF enforced.
  discussion_board_member_id String @db.Uuid

  /// Self-referencing field to enable nested/threaded posts. Nullable for top-level posts. 3NF normalization: only atomic reference; rest of parent data never duplicated.
  parent_id String? @db.Uuid

  /// Title of the post - Implements requirement for user-generated summaries and search. Atomic, supports full-text search GIN. No calculation, pure data.
  title String

  /// Main content/body of the post. Implements requirement for persistent, rich-text discussions. Normalized single value, no calculation.
  body String

  /// Timestamp for post creation. Implements audit, moderation, and chronology requirements. Atomic, not calculated.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp to enable audit trails and moderation transparency. 3NF normalized.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for moderation, audit, and reporting. Null means active; non-null means deleted (soft). Enforces requirement for reversible deletions/audits.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  author discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)
  parent discussion_board_posts? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive discussion_board_posts[] @relation("recursive")
  discussion_board_comments discussion_board_comments[]
  discussion_board_post_votes discussion_board_post_votes[]
  discussion_board_post_tags discussion_board_post_tags[]
  discussion_board_post_categories discussion_board_post_categories[]
  discussion_board_post_edits discussion_board_post_edits[]
  discussion_board_content_reports discussion_board_content_reports[]
  discussion_board_notifications discussion_board_notifications[]

  @@index([parent_id])

  @@index([discussion_board_member_id, created_at], map: "discussion_board_posts_discussion_board_member_id_crea_df884d20")
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion comments entity - Implements threaded/hierarchical comment requirement, auditable histories, post association, and edit/deletion tracking. Business purpose: to attach persistent, atomic user comments to posts or to other comments (threaded). Strict 3NF normalization maintained throughout. For example, member creates comment, which can be replied to, edited, deleted, and voted on. Relationships: belongs to member (author), links to post, may have parent comment (threading), and edit/vote audit histories. Special: GIN index on content for search, soft deletion for moderation traceability.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each comment, supporting full audit, reporting, and threading. 3NF.
  id String @id @db.Uuid

  /// Author of the comment - references existing discussion_board_members table. Needed for audit, reporting, moderation. 3NF enforced.
  discussion_board_member_id String @db.Uuid

  /// Attached post. References existing discussion_board_posts. Requirement: all comments tied to a post. Normalized, atomic reference.
  discussion_board_post_id String @db.Uuid

  /// Self-referencing optional parent comment to allow threaded replies. Null for top-level comments. 3NF: atomic reference, zero duplication.
  parent_id String? @db.Uuid

  /// Comment text for discussions. Implements core requirement for comments, normalized, atomic value.
  body String

  /// Creation timestamp for audit, moderation, and reporting; complies with audit/auditability requirements. Not a calculation.
  created_at DateTime @db.Timestamptz

  /// Audit requirement for edit history; supports transparency and accountability. Normalized date field.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null if active, else denotes deletion for moderation reporting/audit. Normalized atomic value.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  author discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)
  post discussion_board_posts @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  parent discussion_board_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive discussion_board_comments[] @relation("recursive")
  discussion_board_comment_votes discussion_board_comment_votes[]
  discussion_board_comment_edits discussion_board_comment_edits[]
  discussion_board_content_reports discussion_board_content_reports[]
  discussion_board_notifications discussion_board_notifications[]

  @@index([discussion_board_post_id])
  @@index([parent_id])

  @@index([discussion_board_member_id, discussion_board_post_id, created_at], map: "discussion_board_comments_discussion_board_member_id_d_cff14bc7")
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post voting entity - Implements requirement for voting (up/down) on posts. 3NF enforcement (atomic, no calculations in post table). All individual votes are traceable to both post and member per requirements. Business: supports engagement metrics, moderation, and audit. Usage: ensures only one vote per member per post (unique index).
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_votes {
  //----
  // COLUMNS
  //----
  /// Primary Key. One record per vote event, ensuring full normalization, auditable voting histories with no redundancy. 3NF.
  id String @id @db.Uuid

  /// Post being voted on, references discussion_board_posts. Atomic, normalized reference.
  discussion_board_post_id String @db.Uuid

  /// Voting member - references discussion_board_members. 3NF enforced; enables full audit, traceability, unique vote enforcement.
  discussion_board_member_id String @db.Uuid

  /// Vote type (up=true, down=false). Supports engagement/reputation, normalized, atomic.
  upvote Boolean

  /// Timestamp for vote event for audit and analytics; atomic field.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussion_board_posts @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  voter discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)

  @@index([discussion_board_member_id])

  @@unique([discussion_board_post_id, discussion_board_member_id], map: "discussion_board_post_votes_discussion_board_post_id_d_b7f62771")
  @@index([discussion_board_post_id, upvote])
}

/// Comment voting entity - Fulfills requirement for upvotes/downvotes (atomic) on comments with auditability. Each record links to both comment and voting member; unique index enforces one vote per user per comment. Audit-friendly, strictly 3NF (no aggregate/calculated fields).
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comment_votes {
  //----
  // COLUMNS
  //----
  /// Primary Key. One record per vote on a comment. Supports analytic requirements and audit trails. 3NF.
  id String @id @db.Uuid

  /// Voted comment. References discussion_board_comments; supports moderation and audit.
  discussion_board_comment_id String @db.Uuid

  /// Voting member - references discussion_board_members. 1:N member-to-votes. Unique constraint for 1 vote per comment per user.
  discussion_board_member_id String @db.Uuid

  /// Vote polarity. Upvote=true, downvote=false. Atomic, normalized, directly mapped to requirements.
  upvote Boolean

  /// Vote timestamp for audit, reporting, compliance. Normalized atomic value.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  comment discussion_board_comments @relation(fields: [discussion_board_comment_id], references: [id], onDelete: Cascade)
  voter discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)

  @@index([discussion_board_member_id])

  @@unique([discussion_board_comment_id, discussion_board_member_id], map: "discussion_board_comment_votes_discussion_board_commen_1576db93")
  @@index([discussion_board_comment_id, upvote], map: "discussion_board_comment_votes_discussion_board_commen_978f6add")
}

/// Junction table for post-tag connections - Implements requirement for flexible post tagging with normalized, atomic entity representing each post-tag relationship. Supports filtering, analytics, and reporting with zero redundancy (enforces 3NF). For example, find all posts for a tag or all tags for a post by querying this table. Key: Each post-tag pair appears at most once (unique constraint).
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key. Each post-tag pair as a separate record enforces 3NF and supports analytics, filtering. Implements junction requirement for flexible tagging.
  id String @id @db.Uuid

  /// FK to post in relationship. Atomic field, enforces single post per junction.
  discussion_board_post_id String @db.Uuid

  /// FK to tag (Systematic). Normalized atomic field, supports tag lists and filter/search features across posts.
  discussion_board_tag_id String @db.Uuid

  //----
  // RELATIONS
  //----
  post discussion_board_posts @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  tag discussion_board_tags @relation(fields: [discussion_board_tag_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_post_id, discussion_board_tag_id], map: "discussion_board_post_tags_discussion_board_post_id_di_31228204")
  @@index([discussion_board_tag_id])
}

/// Junction table for post-category relationships - Implements the flexible post categorization required in the requirements document. Each record maps a post to a category (from Systematic) in 3NF. No denormalization, pure linking. Example: supports filtering, analytics, reporting, and browsing by category. Unique constraint ensures no duplicates for the same post-category pair.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Each post-category pair as atomic record (junction table). 3NF; future-proofs reporting, filtering requirements.
  id String @id @db.Uuid

  /// FK to post entity. Maintains atomic reference for N:M relationship.
  discussion_board_post_id String @db.Uuid

  /// FK to category (from Systematic tables). Assignment supports flexible browsing, analytics, and reporting. Strict normalization: category information never duplicated.
  discussion_board_category_id String @db.Uuid

  //----
  // RELATIONS
  //----
