/// Key relationships: Optionally references actors (including guests) for mapped event context. Four optional foreign keys for different actor types. Special behaviors: Nullability for anonymous accesses; index for high-volume endpoint queries.
///
/// @namespace Access
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_access_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each access event log entry.
  id String @id @db.Uuid

  /// Admin's {@link discussion_board_admins.id} if acting user is an admin.
  admin_id String? @db.Uuid

  /// Moderator's {@link discussion_board_moderators.id} if acting user is a moderator.
  moderator_id String? @db.Uuid

  /// Member's {@link discussion_board_members.id} if acting user is a member.
  member_id String? @db.Uuid

  /// Guest's {@link discussion_board_guests.id} if acting user is a guest.
  guest_id String? @db.Uuid

  /// Role type of the actor (admin, moderator, member, guest, null if anonymous).
  actor_type String?

  /// Time of access event occurrence. Implements audit/compliance tracking.
  accessed_at DateTime @db.Timestamptz

  /// HTTP method of the request (GET, POST, etc.).
  http_method String

  /// API endpoint or path accessed. Supports reporting, investigation, and endpoint performance analytics.
  endpoint String

  /// Result of the API call (e.g., success, failure, unauthorized).
  result String

  /// IP address of client (nullable if not recorded due to privacy/technical reasons).
  ip_address String?

  /// User agent string of the client (nullable if not present).
  user_agent String?

  //----
  // RELATIONS
  //----
  actor_admin discussion_board_admins? @relation(fields: [admin_id], references: [id], onDelete: Cascade)
  actor_moderator discussion_board_moderators? @relation(fields: [moderator_id], references: [id], onDelete: Cascade)
  actor_member discussion_board_members? @relation(fields: [member_id], references: [id], onDelete: Cascade)
  actor_guest discussion_board_guests? @relation(fields: [guest_id], references: [id], onDelete: Cascade)

  @@index([guest_id])

  @@index([admin_id, accessed_at])
  @@index([moderator_id, accessed_at])
  @@index([member_id, accessed_at])
  @@index([endpoint])
}

