schemas.schema-01-systematic.prisma:
/// Category definitions - Implements the business requirement for persistent, configurable categorized discussion areas (Feature 1, Posting/Thread Management, and project objectives). This model enables separation of discussion spaces for workflow and access control, mapping category names to public/posting/finding/review requirements. Maintains 3NF as all values are atomic and not derived. Example: 'Help', 'Announcements', 'General'. Key relationships: Many posts belong to a category; tags assigned via category_tags. Special behaviors: Name must be unique, soft deletion allowed, audit trail via timestamps.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Category name - uniquely identifies the category as required for post/thread assignment and category configuration. Maintains normalization by being atomic and single-purpose. Used in category selectors, post creation, audit logs, moderation workflows. Must be unique.
  name String

  /// Optional description for category - guides admins and users about the category’s purpose. Null allowed for concise categories, maintains 3NF by only referencing this category. Used in UI help/tooltips.
  description String?

  /// Category creation timestamp - implements audit and compliance requirements for traceability. Maintains normalization as atomic event log. Used for sorting/filtering, admin review, audit logs.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last admin modification - maps to admin/audit requirements for configuration changes. Used in admin UIs, audit trails, compliance routines. Maintains 3NF.
  updated_at DateTime @db.Timestamptz

  /// Timestamp for soft deletion (if the category is deleted but should remain for policy/history). Maintains normalization as atomic value and complies with audit/recovery requirements. Used in policy enforcement, safe removes, and potential category restoration. Nullable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category_tags   discussion_board_category_tags[]
  discussion_board_post_categories discussion_board_post_categories[]

  @@unique([name])
  @@index([created_at])
}

/// Tag definitions - Implements tagging and flexible content categorization requirements (referenced in project overview, feature spec, usability/accessibility). Enables UIs and admin policies for discoverability, faceted navigation, and access control. Maintains 3NF with atomic, non-derived values. Example: 'urgent', 'release', 'staff'. Relationships: Assigned to categories via category_tags; may be assigned to posts/comments elsewhere. Special behaviors: 'label' must be unique, soft deletion for compliance/audit, optional color for UI display.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Short text label for the tag - enables tagging UI, content filtering, and administrative assignment. Atomic and normalized; uniquely identifies tag for assignment. Used in create/search/sort navigation. Must be unique.
  label String

  /// Optional description for this tag - displayed to admins or users for clarity. Maintains 3NF as atomic, non-derived value. Nullable for lightweight tags.
  description String?

  /// Tag color code (HTML hex or class) for display/UI cues - implements branding/accessibility. Normalized as atomic attribute, not required. Nullable.
  color String?

  /// Creation timestamp, for administrative/audit trail compliance and tag lifecycle management. Non-nullable, atomic, and normalized. Used in filtering/audit.
  created_at DateTime @db.Timestamptz

  /// Timestamp for admin modifications (e.g., label, color) to this tag. Implements audit traceability and admin compliance. Used in change logging and admin review.
  updated_at DateTime @db.Timestamptz

  /// Timestamp marking tag as soft-deleted (if ever removed for compliance/policy). Supports safe deletion/feature-recovery as per requirements. Nullable; maintains normalization.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category_tags discussion_board_category_tags[]
  discussion_board_post_tags     discussion_board_post_tags[]

  @@unique([label])
  @@index([created_at])
}

/// Junction: Category/Tag assignment - Implements flexible M:N category x tag linkage required for configurable board structure (allowing each category to have multiple tags and each tag to apply to multiple categories). Fulfills normalized structure by storing only category-tag pairs; no derived or aggregate fields present. Example usage: associating 'urgent' with 'Help', 'release' with 'Announcements'. Key relationships: Many-to-one to discussion_board_categories and discussion_board_tags. Special behaviors: Composite uniqueness of (category, tag), assignment timestamp for audit.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_category_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked category's id - foreign key to {@link discussion_board_categories.id}. Implements requirement for linking categories to tags via junction. Not unique, required.
  discussion_board_category_id String @db.Uuid

  /// Linked tag's id - foreign key to {@link discussion_board_tags.id}. Allows assignment of tags to categories. Not unique, required.
  discussion_board_tag_id String @db.Uuid

  /// Assignment timestamp for when this tag was linked to this category. Atomic event for audit/compliance; maintains 3NF.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  category discussion_board_categories @relation(fields: [discussion_board_category_id], references: [id], onDelete: Cascade, map: "discussion_board_category_tags_discussion_board_catego_04333f08")
  tag      discussion_board_tags       @relation(fields: [discussion_board_tag_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_category_id, discussion_board_tag_id], map: "discussion_board_category_tags_discussion_board_catego_2da3c6c9")
  @@index([discussion_board_tag_id, discussion_board_category_id], map: "discussion_board_category_tags_discussion_board_tag_id_fa09fd02")
}

/// Board/global configuration - Implements requirement for systematic, single-source, board-level settings and branding (project overview, admin permissions, setup, and configuration features). All fields are atomic and not derived, supporting complete normalization for configuration data. Example: board title/configuration for branding or policy. Relationships: not referenced by other domains as FK. Special behaviors: Typically single-row; optional logo/support for branding; enabled/disabled toggling for maintenance. All configuration edits recorded via updated_at.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_board_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key (expected single-row only).
  id String @id @db.Uuid

  /// Board title for branding and user-facing display. Implements requirement for customizable system header/branding. Maintains normalization as atomic attribute. Used in UI, welcome screens.
  title String

  /// Optional board description shown on landing pages and board information modals. Implements requirement for user guidance and compliance context. Nullable, atomic.
  description String?

  /// Whether this board is active/enabled (vs. offline/maintenance). Implements admin control requirement for access/mode. Used to survive maintenance/disable in a single config place. Atomic, mapped 1:1 to admin toggle.
  enabled Boolean

  /// Optional logo image (display URI). Implements branding/config requirement for admins; nullable for minimalist boards; maintains 3NF as atomic value.
  logo_uri String?

  /// When this board setup/config record was created. Implements system audit and admin requirements for setup history. Used during operations/audit.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last configuration update/change. Maintains full normalization as atomic value and supports requirement for admin audit/rollback.
  updated_at DateTime @db.Timestamptz
}

schemas.schema-02-actors.prisma:
/// Explicit administrator account model - This implements the requirement for explicit admin role (see Roles and Permissions doc). Enables granular access control, permission enforcement, and auditability for administrator actions. 3NF normalization: business fields atomic (username, password_hash, email), no calculated values. Used for authentication, role assignment, and audit tracking. Key relationships: referenced by moderator promotions, moderation records. Special behaviors: username/email uniqueness and active flag enforcement.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Admin's unique username used for authentication and audit tracking. Implements explicit admin identity, mapped to the Roles and Permissions requirement. Each admin must have an immutable, account-unique name.
  username String

  /// Secure password hash (not plaintext) for authentication. Implements security and data integrity requirement. No business logic outside authentication.
  password_hash String

  /// Admin's business email. Implements requirement for notification and account recovery. Uniqueness ensures clear identity reference.
  email String

  /// Whether this admin account is currently authorized. Requirement: immediate permission enforcement upon promotion/suspension.
  is_active Boolean

  /// Timestamp marking admin account creation. Requirement: audit trail/auditability; supports analytics.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for admin account. Implements audit trail and policy updates requirement for traceability.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_moderators                        discussion_board_moderators[]
  discussion_board_content_reports                   discussion_board_content_reports[]
  discussion_board_moderation_actions                discussion_board_moderation_actions[]
  discussion_board_appeals                           discussion_board_appeals[]
  discussion_board_suspensions_of_suspended_admin_id discussion_board_suspensions[]          @relation("discussion_board_suspensions_of_suspended_admin_id")
  discussion_board_suspensions_of_admin_id           discussion_board_suspensions[]          @relation("discussion_board_suspensions_of_admin_id")
  discussion_board_audit_logs                        discussion_board_audit_logs[]
  discussion_board_notifications                     discussion_board_notifications[]
  discussion_board_notification_settings             discussion_board_notification_settings?
  discussion_board_auth_tokens                       discussion_board_auth_tokens[]
  discussion_board_access_logs                       discussion_board_access_logs[]

  @@unique([username])
  @@unique([email])
  @@index([created_at])
}

/// Moderator account with explicit separation from admin and member roles - Implements moderator-specific requirements (see Roles and Permissions, Moderation Policy). Maintains normalized role boundaries; supports permission enforcement and audit-log promotion tracking. Used for authentication, access, and audit logs. Key relationships: references discussion_board_admins by promoted_by_admin_id. 3NF enforced. Special behaviors: account activation and promotion traceability.
///
/// @namespace Actors
