  discussion_board_content_reports                       discussion_board_content_reports[]
  discussion_board_moderation_actions                    discussion_board_moderation_actions[]
  discussion_board_appeals                               discussion_board_appeals[]
  discussion_board_suspensions_of_suspended_moderator_id discussion_board_suspensions[]          @relation("discussion_board_suspensions_of_suspended_moderator_id")
  discussion_board_suspensions_of_moderator_id           discussion_board_suspensions[]          @relation("discussion_board_suspensions_of_moderator_id")
  discussion_board_audit_logs                            discussion_board_audit_logs[]
