schemas.schema-03-content.prisma:
/// Discussion board posts entity - This implements the core posting and thread management requirements from the requirements document. Business purpose: to store user-created posts, support nesting for threaded discussions, maintain ownership attribution via member links, and provide edit/delete auditability via history relationships. Maintains strict 3NF normalization by making all data atomic and referencing other entities via foreign keys only. For example, posts can be filtered by category/tag, searched by content, or linked to moderation workflows. Key relationships: belongs to a member (author), may have parent (for threading), linked to tags/categories (junctions), has comments, votes, and full edit audit trail. Special behaviors: soft deletion, GIN index for full-text search, multi-level hierarchy via parent_id.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Implements the requirement for uniquely identifiable posts while supporting audit, edit/delete traceability, and hierarchical structuring for discussions.
  id String @id @db.Uuid

  /// Author of the post - references existing discussion_board_members table. Implements user attribution for all posting activity. Normalization: 3NF enforced.
  discussion_board_member_id String @db.Uuid

  /// Self-referencing field to enable nested/threaded posts. Nullable for top-level posts. 3NF normalization: only atomic reference; rest of parent data never duplicated.
  parent_id String? @db.Uuid

  /// Title of the post - Implements requirement for user-generated summaries and search. Atomic, supports full-text search GIN. No calculation, pure data.
  title String

  /// Main content/body of the post. Implements requirement for persistent, rich-text discussions. Normalized single value, no calculation.
  body String

  /// Timestamp for post creation. Implements audit, moderation, and chronology requirements. Atomic, not calculated.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp to enable audit trails and moderation transparency. 3NF normalized.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for moderation, audit, and reporting. Null means active; non-null means deleted (soft). Enforces requirement for reversible deletions/audits.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  author discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)
  parent discussion_board_posts?  @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive                        discussion_board_posts[]           @relation("recursive")
  discussion_board_comments        discussion_board_comments[]
  discussion_board_post_votes      discussion_board_post_votes[]
  discussion_board_post_tags       discussion_board_post_tags[]
  discussion_board_post_categories discussion_board_post_categories[]
  discussion_board_post_edits      discussion_board_post_edits[]
  discussion_board_content_reports discussion_board_content_reports[]
  discussion_board_notifications   discussion_board_notifications[]

  @@index([parent_id])
  @@index([discussion_board_member_id, created_at], map: "discussion_board_posts_discussion_board_member_id_crea_df884d20")
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion comments entity - Implements threaded/hierarchical comment requirement, auditable histories, post association, and edit/deletion tracking. Business purpose: to attach persistent, atomic user comments to posts or to other comments (threaded). Strict 3NF normalization maintained throughout. For example, member creates comment, which can be replied to, edited, deleted, and voted on. Relationships: belongs to member (author), links to post, may have parent comment (threading), and edit/vote audit histories. Special: GIN index on content for search, soft deletion for moderation traceability.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each comment, supporting full audit, reporting, and threading. 3NF.
  id String @id @db.Uuid

  /// Author of the comment - references existing discussion_board_members table. Needed for audit, reporting, moderation. 3NF enforced.
  discussion_board_member_id String @db.Uuid

  /// Attached post. References existing discussion_board_posts. Requirement: all comments tied to a post. Normalized, atomic reference.
  discussion_board_post_id String @db.Uuid

  /// Self-referencing optional parent comment to allow threaded replies. Null for top-level comments. 3NF: atomic reference, zero duplication.
  parent_id String? @db.Uuid

  /// Comment text for discussions. Implements core requirement for comments, normalized, atomic value.
  body String

  /// Creation timestamp for audit, moderation, and reporting; complies with audit/auditability requirements. Not a calculation.
  created_at DateTime @db.Timestamptz

  /// Audit requirement for edit history; supports transparency and accountability. Normalized date field.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null if active, else denotes deletion for moderation reporting/audit. Normalized atomic value.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  author discussion_board_members   @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)
  post   discussion_board_posts     @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  parent discussion_board_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive                        discussion_board_comments[]        @relation("recursive")
  discussion_board_comment_votes   discussion_board_comment_votes[]
  discussion_board_comment_edits   discussion_board_comment_edits[]
  discussion_board_content_reports discussion_board_content_reports[]
  discussion_board_notifications   discussion_board_notifications[]

  @@index([discussion_board_post_id])
  @@index([parent_id])
  @@index([discussion_board_member_id, discussion_board_post_id, created_at], map: "discussion_board_comments_discussion_board_member_id_d_cff14bc7")
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post voting entity - Implements requirement for voting (up/down) on posts. 3NF enforcement (atomic, no calculations in post table). All individual votes are traceable to both post and member per requirements. Business: supports engagement metrics, moderation, and audit. Usage: ensures only one vote per member per post (unique index).
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_votes {
  //----
  // COLUMNS
  //----
  /// Primary Key. One record per vote event, ensuring full normalization, auditable voting histories with no redundancy. 3NF.
  id String @id @db.Uuid

  /// Post being voted on, references discussion_board_posts. Atomic, normalized reference.
  discussion_board_post_id String @db.Uuid

  /// Voting member - references discussion_board_members. 3NF enforced; enables full audit, traceability, unique vote enforcement.
  discussion_board_member_id String @db.Uuid

  /// Vote type (up=true, down=false). Supports engagement/reputation, normalized, atomic.
  upvote Boolean

  /// Timestamp for vote event for audit and analytics; atomic field.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post  discussion_board_posts   @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  voter discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_post_id, discussion_board_member_id], map: "discussion_board_post_votes_discussion_board_post_id_d_b7f62771")
  @@index([discussion_board_member_id])
  @@index([discussion_board_post_id, upvote])
}

/// Comment voting entity - Fulfills requirement for upvotes/downvotes (atomic) on comments with auditability. Each record links to both comment and voting member; unique index enforces one vote per user per comment. Audit-friendly, strictly 3NF (no aggregate/calculated fields).
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comment_votes {
  //----
  // COLUMNS
  //----
  /// Primary Key. One record per vote on a comment. Supports analytic requirements and audit trails. 3NF.
  id String @id @db.Uuid

  /// Voted comment. References discussion_board_comments; supports moderation and audit.
  discussion_board_comment_id String @db.Uuid

  /// Voting member - references discussion_board_members. 1:N member-to-votes. Unique constraint for 1 vote per comment per user.
  discussion_board_member_id String @db.Uuid

  /// Vote polarity. Upvote=true, downvote=false. Atomic, normalized, directly mapped to requirements.
  upvote Boolean

  /// Vote timestamp for audit, reporting, compliance. Normalized atomic value.
  created_at DateTime @db.Timestamptz

