/**
 * Test moderator search and filtering of content moderation reports with all
 * supported filters.
 *
 * Scenario:
 *
 * 1. Ensure a content moderation report exists (create via member endpoint if
 *    necessary) for testing search.
 * 2. As a moderator, perform a search with no filters to get all reports, and
 *    validate pagination fields and accessible report presence.
 * 3. Perform filtered searches by:
 *
 *    - Reporter_member_id
 *    - Content_type ("post")
 *    - Status (should match the status of report)
 *    - Category (should match the category of report)
 *    - Discussion_board_post_id or discussion_board_comment_id (must match existing
 *         ID)
 *    - Date_from and date_to (confirm correct date range filtering)
 * 4. For each filtering test, ensure returned reports are correct for the applied
 *    filter, and pagination fields are accurate.
 * 5. Attempt filtering by impossible field value (e.g. random member_id) and
 *    verify 0 results are returned.
 * 6. Optionally, verify role-based access control by simulating a non-moderator
 *    access and confirming denial (if technical means available).
 *
 * Assumes moderator is already authenticated for this function.
 */
export async function test_api_discussionBoard_test_search_content_reports_with_various_filters_and_roles(
  connection: api.IConnection,
) {
  // 1. Ensure at least one report exists
  const createdReport =
    await api.functional.discussionBoard.member.contentReports.create(
      connection,
      {
        body: {
          content_type: "post",
          category: "spam",
          reason: "Obvious spam post",
          discussion_board_post_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          discussion_board_comment_id: null,
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(createdReport);

  // 2. Unfiltered moderator search
  const allReports =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      {
        body: {}, // No filters - get all
      },
    );
  typia.assert(allReports);
  TestValidator.predicate("pagination and data")(allReports.data.length >= 1);

  // 3. Filter by reporter_member_id (should return the created report)
  if (createdReport.reporter_member_id) {
    const byReporter =
      await api.functional.discussionBoard.moderator.contentReports.search(
        connection,
        {
          body: { reporter_member_id: createdReport.reporter_member_id },
        },
      );
    typia.assert(byReporter);
    TestValidator.predicate("by reporter_member_id contains")(
      byReporter.data.some((r) => r.id === createdReport.id),
    );
  }

  // 4. Filter by content_type
  const byType =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      {
        body: { content_type: createdReport.content_type },
      },
    );
  typia.assert(byType);
  TestValidator.predicate("by content_type contains")(
    byType.data.some((r) => r.id === createdReport.id),
  );

  // 5. Filter by status
  const byStatus =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { status: createdReport.status } },
    );
  typia.assert(byStatus);
  TestValidator.predicate("by status contains")(
    byStatus.data.some((r) => r.id === createdReport.id),
  );

  // 6. Filter by category
  const byCategory =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { category: createdReport.category } },
    );
  typia.assert(byCategory);
  TestValidator.predicate("by category contains")(
    byCategory.data.some((r) => r.id === createdReport.id),
  );

  // 7. Filter by discussion_board_post_id
  if (createdReport.discussion_board_post_id) {
    const byPostId =
      await api.functional.discussionBoard.moderator.contentReports.search(
        connection,
        {
          body: {
            discussion_board_post_id: createdReport.discussion_board_post_id,
          },
        },
      );
    typia.assert(byPostId);
    TestValidator.predicate("by post id contains")(
      byPostId.data.some((r) => r.id === createdReport.id),
    );
  }

  // 8. Filter by discussion_board_comment_id (should be null, so skip if not set)
  if (createdReport.discussion_board_comment_id) {
    const byCommentId =
      await api.functional.discussionBoard.moderator.contentReports.search(
        connection,
        {
          body: {
            discussion_board_comment_id:
              createdReport.discussion_board_comment_id,
          },
        },
      );
    typia.assert(byCommentId);
    TestValidator.predicate("by comment id contains")(
      byCommentId.data.some((r) => r.id === createdReport.id),
    );
  }

  // 9. Filter by date_from and date_to (should include report in a wide window)
  const wideFrom = new Date(
    new Date(createdReport.reported_at).getTime() - 1000 * 60 * 60 * 24,
  ).toISOString();
  const wideTo = new Date(
    new Date(createdReport.reported_at).getTime() + 1000 * 60 * 60 * 24,
  ).toISOString();
  const byDateRange =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { date_from: wideFrom, date_to: wideTo } },
    );
  typia.assert(byDateRange);
  TestValidator.predicate("by date range contains")(
    byDateRange.data.some((r) => r.id === createdReport.id),
  );

  // 10. Pagination: use limit=1 and page=1, data length should be <= 1, pagination matches
  const paged =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      { body: { pagination: { page: 1, limit: 1 } } },
    );
  typia.assert(paged);
  TestValidator.predicate("pagination respect")(
    paged.data.length <= 1 && paged.pagination.limit === 1,
  );

  // 11. Impossible filter: random UUID for reporter_member_id
  const impossible =
    await api.functional.discussionBoard.moderator.contentReports.search(
      connection,
      {
        body: {
          reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(impossible);
  TestValidator.equals("no data for unknown member id")(impossible.data.length)(
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
