 * fields such as reporter identity, target content linkages, reason, category,
 * status, and relevant timestamps.
 *
 * The process includes:
 *
 * 1. Setting up a known content report by POSTing a new content report as a member
 *    (dependency).
 * 2. Fetching the full content report details via the moderator GET endpoint using
 *    the created ID.
 * 3. Verifying that the detailed fields (reason, category, content_type, reporter
 *    linkage, referenced post/comment, status, timestamps) are present and
 *    match what was submitted or expected by business rules.
 * 4. Negative case: Attempting to fetch an invalid (random) content report ID as
 *    moderator yields 404 not found.
 * 5. Member RBAC cannot be checked (no such endpoint in given SDK), so is skipped
 *    here.
 *
 * Steps:
 *
 * - Use the member endpoint to file a new report and receive its ID.
 * - Use the moderator endpoint to fetch by ID and assert correctness of response
 *   fields and values.
 * - Use a random UUID to fetch a non-existent report and validate 404 behavior.
 */
export async function test_api_discussionBoard_moderator_contentReports_at(
  connection: api.IConnection,
) {
  // 1. Member files a new content report to set up valid data
  const reportInput: IDiscussionBoardContentReport.ICreate = {
    discussion_board_post_id: null,
    discussion_board_comment_id: null,
    content_type: "post",
    category: "policy",
    reason: "Test: offensive policy violation for moderation detail review.",
  };
  const created: IDiscussionBoardContentReport =
    await api.functional.discussionBoard.member.contentReports.create(
      connection,
      { body: reportInput },
    );
