  TestValidator.equals("id matches")(fetched.id)(created.id);
  TestValidator.equals("category matches")(fetched.category)(
    reportInput.category,
  );
  TestValidator.equals("reason matches")(fetched.reason)(reportInput.reason);
  TestValidator.equals("content_type matches")(fetched.content_type)(
    reportInput.content_type,
  );
  // Business workflow may require "pending" but can be adjusted
  TestValidator.equals("status initial value")(fetched.status)("pending");

  // At least a reporter id must be present
  TestValidator.predicate("reporter linkage present")(
    !!fetched.reporter_member_id ||
      !!fetched.reporter_guest_id ||
      !!fetched.reporter_admin_id ||
      !!fetched.reporter_moderator_id,
  );
  // Target content link
  TestValidator.equals("post id matches")(fetched.discussion_board_post_id)(
    reportInput.discussion_board_post_id,
  );
  TestValidator.equals("comment id matches")(
    fetched.discussion_board_comment_id,
  )(reportInput.discussion_board_comment_id);
  // Timestamps present
  TestValidator.predicate("reported_at present")(!!fetched.reported_at);

  // 3. 404 error for unknown report
  await TestValidator.error("unknown content report yields 404")(() =>
    api.functional.discussionBoard.moderator.contentReports.at(connection, {
      contentReportId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // (RBAC check by a non-moderator is not possible with given SDK - skip)
}

