import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for searching and filtering guest notifications with advanced
 * criteria.
 *
 * This test covers the full workflow for a guest user's notification inbox:
 *
 * 1. Registers a guest session and obtains guestId.
 * 2. Creates a variety of notifications for that guest with:
 *
 *    - Different categories (e.g., "reply", "vote")
 *    - Types (e.g., "in-app", "email")
 *    - Is_read (true/false)
 *    - Status (e.g., "pending", "sent")
 *    - Diverse created_at timestamps for date range filters.
 * 3. Sets up negative case notifications for other users (admin/member).
 * 4. Performs search/filter operations using /discussionBoard/guest/notifications
 *    (PATCH): a. No filters: all guest notifications (paginated). b. Filter by
 *    is_read=false (only unread). c. Filter by category (e.g., "reply"). d.
 *    Filter by type (e.g., "in-app"). e. Filter by created_at range (a known
 *    subset). f. Combination filters (category+type+is_read). g. Verifies that
 *    guest cannot query notifications of other users. h. Attempts
 *    malformed/invalid queries for error handling.
 * 5. Asserts:
 *
 *    - All returned notifications are only for the guest and match the filters
 *         strictly.
 *    - Pagination works with correct splitting/limits.
 *    - No non-guest notifications can be accessed.
 *    - Error/validation handling for illegal filter parameters.
 */
export async function test_api_discussionBoard_guest_notifications_test_search_guest_notifications_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Register a new guest session
  const guestSession = await api.functional.discussionBoard.guests.create(
    connection,
    {
      body: {
        guest_ip: "192.168.1.95",
        session_token: RandomGenerator.alphaNumeric(16),
        entered_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(guestSession);
  const guestId = guestSession.id;

  // 2. Create notifications for this guest session
  const categories = ["reply", "vote"];
  const types = ["in-app", "email"];
  const statuses = ["pending", "sent"];

  // Make timestamps for past, now, and future to exercise date filtering
  const now = new Date();
  const earlier = new Date(now.getTime() - 1000 * 60 * 60 * 24); // 1 day before
  const later = new Date(now.getTime() + 1000 * 60 * 60 * 24); // 1 day after

  // Create multiple notifications (diverse attributes for filtering)
  const notifications: IDiscussionBoardNotification[] = [];
  for (const category of categories) {
    for (const type of types) {
      for (const status of statuses) {
        for (const is_read of [false, true]) {
          const created_at =
            status === "pending"
              ? earlier.toISOString() // set "pending" to before window
              : now.toISOString(); // "sent" to now
          const n =
            await api.functional.discussionBoard.admin.notifications.create(
              connection,
              {
                body: {
                  guest_id: guestId,
                  type,
                  category,
                  message: `Notification: ${category}, ${type}, ${status}, ${is_read}`,
                  is_read,
                  status,
                  created_at,
                  delivered_at: status === "sent" ? now.toISOString() : null,
                  read_at: is_read ? now.toISOString() : null,
                },
              },
            );
          typia.assert(n);
          notifications.push(n);
        }
      }
    }
  }

  // 3. Also create notifications for non-guest users (to check guest cannot access)
  const adminNotification =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      {
        body: {
          admin_id: typia.random<string & tags.Format<"uuid">>(),
          type: "email",
          category: "moderation_event",
          message: "For admin only",
          is_read: false,
          status: "pending",
          created_at: now.toISOString(),
        },
      },
    );
  typia.assert(adminNotification);

  const memberNotification =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      {
        body: {
          member_id: typia.random<string & tags.Format<"uuid">>(),
          type: "in-app",
          category: "vote",
          message: "For member only",
          is_read: false,
          status: "sent",
          created_at: now.toISOString(),
          delivered_at: now.toISOString(),
        },
      },
    );
  typia.assert(memberNotification);

  // 4a. No filters: should return all guest notifications (paginated, try limit < total)
  const outputAll =
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: { limit: 2 },
      },
    );
  typia.assert(outputAll);
  TestValidator.predicate("all notifications belong to guest")(
    outputAll.data.every((n) => n.guest_id === guestId),
  );
  TestValidator.equals("page size")(outputAll.data.length)(2);
  TestValidator.equals("total records")(outputAll.pagination.records)(
    notifications.length,
  );

  // 4b. Filter: only unread
  const outputUnread =
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: { is_read: false },
      },
    );
  typia.assert(outputUnread);
  TestValidator.predicate("all are unread for guest")(
    outputUnread.data.every(
      (n) => n.guest_id === guestId && n.is_read === false,
    ),
  );

  // 4c. Filter by category (reply)
  const outputReply =
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: { category: "reply" },
      },
    );
  typia.assert(outputReply);
  TestValidator.predicate("all are category=reply")(
    outputReply.data.every(
      (n) => n.guest_id === guestId && n.category === "reply",
    ),
  );

  // 4d. Filter by type (in-app)
  const outputInApp =
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: { type: "in-app" },
      },
    );
  typia.assert(outputInApp);
  TestValidator.predicate("all are type=in-app")(
    outputInApp.data.every(
      (n) => n.guest_id === guestId && n.type === "in-app",
    ),
  );

  // 4e. Date range filter (only notifications in [now, future]), should exclude "pending"
  const outputDateRange =
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: {
          created_at_from: now.toISOString(),
          created_at_to: later.toISOString(),
        },
      },
    );
  typia.assert(outputDateRange);
  TestValidator.predicate("all in date range")(
    outputDateRange.data.every(
      (n) =>
        n.guest_id === guestId &&
        n.created_at >= now.toISOString() &&
        n.created_at <= later.toISOString(),
    ),
  );

  // 4f. Combination filter: reply+in-app+unread
  const outputCombo =
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: { category: "reply", type: "in-app", is_read: false },
      },
    );
  typia.assert(outputCombo);
  TestValidator.predicate("combo filter")(
    outputCombo.data.every(
      (n) =>
        n.guest_id === guestId &&
        n.category === "reply" &&
        n.type === "in-app" &&
        n.is_read === false,
    ),
  );

  // 4g. Try to filter with a category not used for guest (should return empty)
  const outputModEvent =
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: { category: "moderation_event" },
      },
    );
  typia.assert(outputModEvent);
  TestValidator.equals("should be empty")(outputModEvent.data.length)(0);

  // 4h. Validation error: use invalid page (-1)
  await TestValidator.error("invalid negative page yields error")(async () => {
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: { page: -1 },
      },
    );
  });

  // 4h. Validation error: invalid status (not in allowed set)
  await TestValidator.error("invalid status value yields error")(async () => {
    await api.functional.discussionBoard.guest.notifications.search(
      connection,
      {
        body: { status: "not-a-status" },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate admin notification retrieval and access control
 *
 * This test verifies both the successful and failed retrieval of a notification
 * using the admin notifications detail API.
 *
 * Business context:
 *
 * - Only the intended admin recipient (by admin_id) can access the detail of the
 *   notification.
 * - System must enforce role and ownership boundaries. Other users, even admins,
 *   are not permitted access to notifications not addressed to them.
 *
 * Test Steps:
 *
 * 1. Create an admin account (AdminA).
 * 2. As AdminA, create a notification addressed to AdminA (admin_id).
 * 3. Retrieve the notification via API as AdminA; validate all fields and schema.
 * 4. Create a second admin account (AdminB).
 * 5. As AdminB, attempt to access the notification for AdminA; verify forbidden or
 *    not found error.
 * 6. (Edge) Attempt to retrieve a notification targeted at a non-admin (e.g.,
 *    member_id specified) as AdminA; verify forbidden/not found.
 * 7. Ensure all business rules and permission checks are strictly enforced.
 */
export async function test_api_discussionBoard_test_retrieve_admin_notification_by_id_with_permission_check(
  connection: api.IConnection,
) {
  // 1. Create AdminA
  const adminAEmail = typia.random<string & tags.Format<"email">>();
  const adminAUsername = RandomGenerator.alphabets(10);
  const adminA = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: adminAUsername,
        email: adminAEmail,
        password_hash: RandomGenerator.alphaNumeric(12),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(adminA);

  // 2. Create a notification for AdminA (other recipient fields set to null explicitly)
  const notification =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      {
        body: {
          admin_id: adminA.id,
          moderator_id: null,
          member_id: null,
          guest_id: null,
          post_id: null,
          comment_id: null,
          moderation_action_id: null,
          type: "in-app",
          category: "test",
          message: "Admin-only test message",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
          delivered_at: null,
          read_at: null,
          error_message: null,
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(notification);
  TestValidator.equals("notification.admin_id matches AdminA")(
    notification.admin_id,
  )(adminA.id);

  // 3. Retrieve notification as AdminA
  const fetched = await api.functional.discussionBoard.admin.notifications.at(
    connection,
    {
      notificationId: notification.id,
    },
  );
  typia.assert(fetched);
  TestValidator.equals("notification content matches")(fetched.id)(
    notification.id,
  );
  TestValidator.equals("recipient matches")(fetched.admin_id)(adminA.id);
  TestValidator.equals("category")(fetched.category)("test");
  TestValidator.equals("type")(fetched.type)("in-app");
  TestValidator.equals("message")(fetched.message)("Admin-only test message");

