/**
 * E2E test for moderator updating an existing category-tag assignment.
 *
 * This test validates that after an admin creates a new discussion board
 * category and two tags, and assigns one tag to the category, a moderator can
 * update this category-tag assignment to point to the second tag instead of the
 * first. The test ensures that the update call is allowed for a moderator, and
 * the response matches the new assignment with updated tag information. It also
 * checks audit trail fields (timestamps and ID reflect update).
 *
 * Steps:
 *
 * 1. Admin creates a discussion category
 * 2. Admin creates two tags
 * 3. Admin assigns the first tag to the category (creates
 *    IDiscussionBoardCategoryTag)
 * 4. Moderator updates the assignment to point to the second tag
 * 5. Validate the response: assignment's category is unchanged, tag is now the
 *    second, 'id' matches, audit fields are correct
 */
export async function test_api_discussionBoard_test_moderator_update_category_tag_assignment(
  connection: api.IConnection,
) {
  // 1. Admin creates a new discussion category
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(12),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 2. Admin creates two tags to be used in assignment and update
  const tag1 = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
        color: null,
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tag1);

  const tag2 = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
        color: null,
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tag2);

  // 3. Admin assigns the first tag to the created category
  const assignment =
    await api.functional.discussionBoard.admin.categoryTags.create(connection, {
      body: {
        discussion_board_category_id: category.id,
        discussion_board_tag_id: tag1.id,
      } satisfies IDiscussionBoardCategoryTag.ICreate,
    });
