  TestValidator.equals("initial assignment's tag")(
    assignment.discussion_board_tag_id,
  )(tag1.id);
  TestValidator.equals("initial assignment's category")(
    assignment.discussion_board_category_id,
  )(category.id);

  // 4. Moderator updates the assignment to point to tag2
  const updated =
    await api.functional.discussionBoard.moderator.categoryTags.update(
      connection,
      {
        categoryTagId: assignment.id,
        body: {
          discussion_board_tag_id: tag2.id,
