  TestValidator.equals("id unchanged")(updated.id)(assignment.id);
  TestValidator.equals("category unchanged")(
    updated.discussion_board_category_id,
  )(category.id);
  TestValidator.equals("tag changed in assignment")(
    updated.discussion_board_tag_id,
  )(tag2.id);
  TestValidator.predicate("created_at should be valid ISO 8601 string")(
    !!Date.parse(updated.created_at),
  );
