import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuthToken";

/**
 * Validate update of an authentication token with invalid field values.
 *
 * This test ensures that the authentication token update API enforces business
 * rules regarding field validity:
 *
 * - Setting `expires_at` to a past date is forbidden and should be rejected as a
 *   validation error.
 * - Sending a `revoked` value of `null` is acceptable (nullable) and should
 *   succeed.
 * - Attempts to send incorrect types for `revoked` (e.g., string or number) are
 *   blocked by the SDK/type system and are not tested here.
 *
 * Test steps:
 *
 * 1. Create a valid admin token with a future expiration date
 * 2. Attempt to update the token with `expires_at` set to a past date (expect
 *    error)
 * 3. Attempt to update the token with `revoked: null` (expect success)
 */
export async function test_api_discussionBoard_admin_authTokens_test_update_auth_token_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid authentication token as a precondition
  const now = new Date();
  const in1Hour = new Date(now.getTime() + 60 * 60 * 1000).toISOString();
  const createInput: IDiscussionBoardAuthToken.ICreate = {
    actor_type: "admin",
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    token: RandomGenerator.alphaNumeric(24),
    issued_at: now.toISOString(),
    expires_at: in1Hour,
  };
  const token = await api.functional.discussionBoard.admin.authTokens.create(
    connection,
    { body: createInput },
  );
  typia.assert(token);

  // 2. Attempt to set expires_at in the past (should fail)
  const pastDate = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
  await TestValidator.error(
    "updating token to past expires_at should be rejected",
  )(() =>
    api.functional.discussionBoard.admin.authTokens.update(connection, {
      authTokenId: token.id,
      body: { expires_at: pastDate },
    }),
  );

  // 3. Update with revoked: null (acceptable, should succeed)
  const updated = await api.functional.discussionBoard.admin.authTokens.update(
    connection,
    {
      authTokenId: token.id,
      body: { revoked: null },
    },
  );
  typia.assert(updated);
}

