/**
 * E2E test: Delete authentication token by valid ID.
 *
 * This test validates the permanent deletion of an authentication token record
 * via the admin endpoint. It ensures that after a successful deletion using
 * DELETE /discussionBoard/admin/authTokens/{authTokenId}, the token cannot be
 * retrieved, and the operation is irreversible.
 *
 * Steps:
 *
 * 1. Create a new authentication token (as precondition, via POST
 *    /discussionBoard/admin/authTokens).
 * 2. Delete the created token by its ID using DELETE
 *    /discussionBoard/admin/authTokens/{authTokenId}.
 * 3. Attempt to delete the token again using the same ID and expect an error
 *    (irrevocability check).
 *
 * All responses and side effects are asserted for correct business logic and
 * type compliance.
 */
export async function test_api_discussionBoard_admin_authTokens_test_delete_auth_token_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create the authentication token to be deleted
  const createInput: IDiscussionBoardAuthToken.ICreate = {
    actor_type: "admin",
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    token: RandomGenerator.alphaNumeric(30),
    issued_at: new Date().toISOString(),
    expires_at: null,
  };
  const token = await api.functional.discussionBoard.admin.authTokens.create(
    connection,
    { body: createInput },
  );
  typia.assert(token);

  // 2. Delete the token by its ID
  await api.functional.discussionBoard.admin.authTokens.erase(connection, {
    authTokenId: token.id,
  });

  // 3. Attempt to delete again and expect an error (irrevocability)
  await TestValidator.error("deleting already deleted token fails")(
    async () => {
      await api.functional.discussionBoard.admin.authTokens.erase(connection, {
        authTokenId: token.id,
      });
    },
  );
}

