import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * Test retrieval of current member's notification settings and pagination.
 *
 * This test ensures that a newly registered member can successfully retrieve
 * their notification settings from the discussion board system. It verifies:
 *
 * - After member registration, retrieves notification settings as the newly
 *   created member.
 * - Ensures only settings belonging to the current member are returned.
 * - Checks that all notification delivery and category preference fields conform
 *   to schema.
 * - Validates that the pagination block is present and correctly describes the
 *   returned record count (and that metadata makes sense if only 1 record).
 * - Makes a redundant call to verify idempotency/stability of the endpoint.
 *
 * Step-by-step:
 *
 * 1. Register a new member via the discussion board registration endpoint (with
 *    randomly generated credentials for isolation).
 * 2. Immediately attempt to retrieve notification settings for the authenticated
 *    session.
 * 3. Assert that all returned records have their `member_id` set to the newly
 *    created member.
 * 4. For each notification setting, validate all required schema fields are
 *    present and of correct type.
 * 5. Validate that the `pagination` block is present and correctly reflects the
 *    record count and page logic.
 * 6. Make a second call to verify stability and idempotency of the endpoint.
 *
 * Note: As the API likely binds authentication from registration for simplicity
 * in testing, it is assumed that the session is for the newly created member
 * throughout this test function.
 */
export async function test_api_discussionBoard_test_list_notification_settings_member_success(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const email: string = typia.random<string & tags.Format<"email">>();
  const displayName: string = RandomGenerator.name();
  const passwordHash: string = RandomGenerator.alphaNumeric(30);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: displayName,
        email,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Retrieve notification settings for the authenticated member
  const page =
    await api.functional.discussionBoard.member.notificationSettings.index(
      connection,
    );
  typia.assert(page);

  // 3. Assert each returned setting belongs to the created member and all required fields are valid
  for (const setting of page.data) {
    TestValidator.equals("Returned member_id matches the new member")(
      setting.member_id,
    )(member.id);

    // Validate presence and types of all required fields
    TestValidator.predicate("Valid setting ID")(
      typeof setting.id === "string" && setting.id.length > 0,
    );
    TestValidator.predicate("Valid created_at")(
      typeof setting.created_at === "string",
    );
    TestValidator.predicate("Valid updated_at")(
      typeof setting.updated_at === "string",
    );
    TestValidator.predicate("in_app_enabled is boolean")(
      typeof setting.in_app_enabled === "boolean",
    );
    TestValidator.predicate("email_enabled is boolean")(
      typeof setting.email_enabled === "boolean",
    );
    TestValidator.predicate("moderation_notification_enabled is boolean")(
      typeof setting.moderation_notification_enabled === "boolean",
    );
    TestValidator.predicate("reply_notification_enabled is boolean")(
      typeof setting.reply_notification_enabled === "boolean",
    );
    TestValidator.predicate("vote_notification_enabled is boolean")(
      typeof setting.vote_notification_enabled === "boolean",
    );
  }

  // 4. Pagination metadata is present and correct
  TestValidator.predicate("Pagination block is present")(
    typeof page.pagination === "object",
  );
  TestValidator.predicate("pagination.current is valid int")(
    typeof page.pagination.current === "number" &&
      Number.isInteger(page.pagination.current) &&
      page.pagination.current > 0,
  );
  TestValidator.predicate("pagination.limit is valid")(
    typeof page.pagination.limit === "number" && page.pagination.limit > 0,
  );
  TestValidator.predicate("pagination.records is valid")(
    typeof page.pagination.records === "number" && page.pagination.records >= 0,
  );
  TestValidator.predicate("pagination.pages is valid")(
    typeof page.pagination.pages === "number" && page.pagination.pages >= 1,
  );
  TestValidator.predicate("pagination.records matches data length")(
    page.pagination.records === page.data.length,
  );

  // 5. Redundant: repeat call to check stability/idempotency
  const page2 =
    await api.functional.discussionBoard.member.notificationSettings.index(
      connection,
    );
  typia.assert(page2);
  TestValidator.equals("Pagination should match for subsequent identical call")(
    page2.pagination,
  )(page.pagination);
  TestValidator.equals("Data array should match for subsequent identical call")(
    page2.data,
  )(page.data);
}

