/**
 * Test advanced search and filtering of notification settings as a member.
 *
 * This test ensures that a logged-in member can search and filter their own
 * notification settings using advanced parameters such as delivery channels
 * (in-app/email), category toggles for enablement (moderation/reply/vote), and
 * creation date/time ranges. The results must only include notification setting
 * records belonging to this member, and responses must be properly paginated
 * and sorted. The test pre-creates multiple notification settings (with a
 * variety of filterable values) for the logged-in member to provide realistic
 * coverage of search/filter behaviors.
 *
 * Steps:
 *
 * 1. Create multiple notification setting records for the same member with
 *    different combinations of enablement toggles and timestamps (using the
 *    notificationSettings.create endpoint).
 * 2. Use several combinations of filter/search queries (by delivery type,
 *    category, creation time) to validate that only the correct subset of
 *    settings for this member is returned.
 * 3. Confirm pagination/sorting metadata is accurate.
 * 4. Validate that searching with another member's context does not return the
 *    original member's records. (Negative test, if implementation supports
 *    multi-user context.)
 */
export async function test_api_discussionBoard_test_search_notification_settings_with_filters_as_member(
  connection: api.IConnection,
) {
  // Step 1: Pre-create multiple notification settings with different combinations for this member.
  const now = new Date();
  const settings: IDiscussionBoardNotificationSetting[] = [];
  const offsets = [0, 1, 2, 3, 4].map((i) => i * 60 * 60 * 1000); // Hourly offsets
  for (let idx = 0; idx < 5; ++idx) {
    const dt = new Date(now.getTime() - offsets[idx]).toISOString();
    const setting =
      await api.functional.discussionBoard.member.notificationSettings.create(
        connection,
        {
          body: {
            in_app_enabled: idx % 2 === 0,
            email_enabled: idx % 2 === 1,
            moderation_notification_enabled: idx % 3 === 0,
            reply_notification_enabled: idx % 2 === 0,
            vote_notification_enabled: idx % 2 === 0,
            created_at: dt,
            updated_at: dt,
          } satisfies IDiscussionBoardNotificationSetting.ICreate,
        },
      );
    typia.assert(setting);
    settings.push(setting);
  }

  // Step 2: Query settings with in_app_enabled = true
  const outputInApp =
    await api.functional.discussionBoard.member.notificationSettings.search(
      connection,
      {
        body: {
          in_app_enabled: true,
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardNotificationSetting.IRequest,
      },
    );
  typia.assert(outputInApp);
  for (const record of outputInApp.data) {
    TestValidator.predicate("in_app_enabled = true")(
      record.in_app_enabled === true,
    );
  }
  TestValidator.predicate("pagination page 1")(
    outputInApp.pagination.current === 1,
  );

  // Step 3: Query settings created within the last 3 hours
  const afterTime = new Date(now.getTime() - 3 * 60 * 60 * 1000).toISOString();
  const outputRecent =
    await api.functional.discussionBoard.member.notificationSettings.search(
      connection,
      {
        body: {
          created_at_from: afterTime,
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardNotificationSetting.IRequest,
      },
    );
  typia.assert(outputRecent);
  for (const record of outputRecent.data) {
    TestValidator.predicate("created_at within last 3 hours")(
      new Date(record.created_at) >= new Date(afterTime),
    );
  }

  // Step 4: Query settings with both email_enabled = true and reply_notification_enabled = false
  const outputEmailReply =
    await api.functional.discussionBoard.member.notificationSettings.search(
      connection,
      {
        body: {
          email_enabled: true,
          reply_notification_enabled: false,
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardNotificationSetting.IRequest,
      },
    );
  typia.assert(outputEmailReply);
  for (const record of outputEmailReply.data) {
    TestValidator.predicate("email_enabled = true")(
      record.email_enabled === true,
    );
    TestValidator.predicate("reply_notification_enabled = false")(
      record.reply_notification_enabled === false,
    );
  }

  // Step 5: Negative test (not implemented as there is no multi-user context switch in the provided SDK/materials)
}

