 *    another member, but user switching is not available in current context)
 * 4. Validate that the API returns a forbidden or not found error (no data leak)
 * 5. Create a second post and comment as the current member
 * 6. Soft-delete the comment
 * 7. Attempt to fetch the soft-deleted comment (should also return forbidden or
 *    not found error)
 */
export async function test_api_discussionBoard_test_member_get_comment_forbidden_if_private_or_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create a post as a member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
