    connection,
    {
      body: {
        discussion_board_post_id: post2.id,
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment2);

  // 5. Soft-delete the comment
  await api.functional.discussionBoard.member.comments.erase(connection, {
    commentId: comment2.id,
  });

  // 6. Attempt to fetch the soft-deleted comment
  await TestValidator.error("forbidden/not found for soft-deleted comment")(
    () =>
      api.functional.discussionBoard.member.comments.at(connection, {
        commentId: comment2.id,
      }),
  );
}

