 * Why: This is crucial for privacy, anti-abuse, and regulatory
 * compliance—preventing users from interfering with others' notifications.
 *
 * **Workflow:**
 *
 * 1. Register Guest A (captures guestAId for notification recipient)
 * 2. Register Guest B (captures guestBId to simulate actor)
 * 3. Admin issues notification for Guest A
 * 4. Admin issues notification for Guest B (control)
 * 5. Simulate Guest B's context and attempt to update Guest A's notification
 *    (should be forbidden)
 *
 * The negative result (forbidden/unauthorized) confirms correct access policy
 * is enforced.
 */
export async function test_api_discussionBoard_guest_notifications_test_update_guest_notification_without_permission(
  connection: api.IConnection,
) {
  // 1. Register Guest A with separate session
  const guestA = await api.functional.discussionBoard.guests.create(
    connection,
