        session_token: RandomGenerator.alphaNumeric(16),
        entered_at: new Date().toISOString(),
      } satisfies IDiscussionBoardGuest.ICreate,
    },
  );
  typia.assert(guestA);
  const guestAId = guestA.id;

  // 2. Register Guest B (different session)
  const guestB = await api.functional.discussionBoard.guests.create(
    connection,
    {
      body: {
        guest_ip: "127.0.0.2",
        session_token: RandomGenerator.alphaNumeric(16),
        entered_at: new Date().toISOString(),
      } satisfies IDiscussionBoardGuest.ICreate,
    },
  );
  typia.assert(guestB);
  const guestBId = guestB.id;

  // 3. Admin delivers a notification to Guest A
  const notificationA =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      {
        body: {
          guest_id: guestAId,
          type: "in-app",
          category: "test-cat",
          message: "You have a new notification as Guest A.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(notificationA);

  // 4. Admin delivers a notification to Guest B (for parity/control)
  const notificationB =
    await api.functional.discussionBoard.admin.notifications.create(
      connection,
      {
        body: {
          guest_id: guestBId,
          type: "in-app",
          category: "test-cat",
          message: "You have a notification as Guest B.",
          is_read: false,
          status: "pending",
          created_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotification.ICreate,
      },
    );
  typia.assert(notificationB);

  // 5. Attempt to update Guest A's notification using Guest B (should fail with forbidden/unauthorized)
  // Assumption: The backend uses session context or token in the connection to identify guest
  await TestValidator.error("cross-session update forbidden")(() =>
    api.functional.discussionBoard.guest.notifications.update(connection, {
      notificationId: notificationA.id,
      body: {
        is_read: true,
      } satisfies IDiscussionBoardNotification.IUpdate,
    }),
  );
}

