/**
 * Validate that an authenticated member can retrieve all votes for a comment
 * with correct pagination and structure.
 *
 * Business context: Members can upvote or downvote comments on posts in the
 * discussion board. Each vote is an auditable record. This test ensures an
 * authenticated member can list all votes for a comment and that vote data,
 * up/down polarity, and member references are correct. Due to lack of
 * multi-auth API, all actions are done by the same member in this test.
 *
 * Steps:
 *
 * 1. Create a post
 * 2. Create a comment on the post
 * 3. Cast an upvote on the comment
 * 4. Cast a downvote (will fail or override previous vote)
 * 5. Fetch votes for the comment
 * 6. Check result: list contains the vote record(s) for current member, with
 *    correct fields
 */
export async function test_api_discussionBoard_test_list_all_votes_for_comment_by_member(
  connection: api.IConnection,
) {
  // 1. Create a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(3),
        body: RandomGenerator.content()()(8),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Create a comment on the post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(2),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 3. Cast an upvote on the comment
  const voteUp =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        } satisfies IDiscussionBoardCommentVote.ICreate,
      },
    );
  typia.assert(voteUp);
  TestValidator.equals("upvote is true")(voteUp.upvote)(true);

  // 4. Attempt a downvote (should fail due to one vote per member policy or override, test what happens)
  let voteDown: IDiscussionBoardCommentVote | undefined = undefined;
  try {
    voteDown =
      await api.functional.discussionBoard.member.comments.commentVotes.create(
        connection,
        {
          commentId: comment.id,
          body: {
            discussion_board_comment_id: comment.id,
            upvote: false,
          } satisfies IDiscussionBoardCommentVote.ICreate,
        },
      );
    typia.assert(voteDown);
    TestValidator.equals("downvote is false")(voteDown.upvote)(false);
  } catch {
    // Downvote likely fails due to business rule: one vote per member per comment.
    // This is valid behavior; at minimum, previous upvote should still exist.
  }

  // 5. Fetch votes for the comment
  const page =
    await api.functional.discussionBoard.member.comments.commentVotes.index(
      connection,
      {
        commentId: comment.id,
      },
    );
  typia.assert(page);

  // 6. Validate result: at least one vote, correct comment id, upvote/downvote logic
  TestValidator.equals("pagination present")(
    typeof page.pagination === "object",
  )(true);
  TestValidator.predicate("vote records exist")(
    Array.isArray(page.data) && page.data.length >= 1,
  );
  page.data.forEach((v) => {
    TestValidator.equals("correct comment id")(v.discussion_board_comment_id)(
      comment.id,
    );
    TestValidator.equals("upvote or downvote")(typeof v.upvote === "boolean")(
      true,
    );
  });
}

