import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IPageIDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced search for comment votes by vote type and date range.
 *
 * This test validates the search functionality for retrieving votes on a
 * discussion board comment; particularly filtering by vote type (upvote or
 * downvote) and by a specific time window. It ensures that the endpoint
 * correctly filters votes and only returns matching results according to the
 * provided criteria.
 *
 * Test workflow:
 *
 * 1. Create a main post as the base resource
 * 2. Create a comment under that post
 * 3. Register three different member accounts sequentially (simulate by switching
 *    the API connection for each)
 * 4. Each member votes on the comment, with at least one voting up, at least one
 *    down, and at distinct timestamps
 * 5. Use the comment votes search API to:
 *
 *    - Retrieve only upvotes (filter upvote=true) and assert only upvote votes are
 *         returned
 *    - Retrieve only downvotes (filter upvote=false) and assert only downvote votes
 *         are returned
 *    - Retrieve votes by a created_at date window (set created_from to after first
 *         vote's time, created_to to before last vote's time)
 *    - Check that filtering results match expected votes according to criteria
 */
export async function test_api_discussionBoard_test_search_comment_votes_by_vote_type_and_date_range(
  connection: api.IConnection,
) {
  // 1. Create main post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        parent_id: null,
      },
    },
  );
  typia.assert(post);

  // 2. Create a comment on the post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(),
          parent_id: null,
        },
      },
    );
  typia.assert(comment);

  // 3. Register three "members" (simulate three users by 'switching' member IDs; realistic test systems would require auth, but here each API call will simulate different members if possible)
  // For this E2E, actual member switching isn't possible due to missing join/login APIs, so all votes technically come from the same member.

  // 4. Each member votes on the comment, with delays to ensure unique timestamps
  const votes = [];

  // 4-1: upvote
  const vote1 =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        },
      },
    );
  typia.assert(vote1);
  votes.push(vote1);
  await new Promise((res) => setTimeout(res, 1200)); // ensure unique timestamp

  // 4-2: downvote
  const vote2 =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: false,
        },
      },
    );
  typia.assert(vote2);
  votes.push(vote2);
  await new Promise((res) => setTimeout(res, 1200));

  // 4-3: upvote
  const vote3 =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        },
      },
    );
  typia.assert(vote3);
  votes.push(vote3);

  // 5. Search only upvotes
  const upvoteResult =
    await api.functional.discussionBoard.member.comments.commentVotes.search(
      connection,
      {
        commentId: comment.id,
        body: {
          upvote: true,
          discussion_board_comment_id: comment.id,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(upvoteResult);
  TestValidator.predicate("only upvotes are returned")(
    upvoteResult.data.every((v) => v.upvote === true),
  );
  TestValidator.predicate("all votes are on the target comment")(
    upvoteResult.data.every(
      (v) => v.discussion_board_comment_id === comment.id,
    ),
  );

  // 6. Search only downvotes
  const downvoteResult =
    await api.functional.discussionBoard.member.comments.commentVotes.search(
      connection,
      {
        commentId: comment.id,
        body: {
          upvote: false,
          discussion_board_comment_id: comment.id,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(downvoteResult);
  TestValidator.predicate("only downvotes are returned")(
    downvoteResult.data.every((v) => v.upvote === false),
  );
  TestValidator.predicate("all votes are on the target comment")(
    downvoteResult.data.every(
      (v) => v.discussion_board_comment_id === comment.id,
    ),
  );

  // 7. Search by created_at time window: between first and last vote
  const createdFrom = new Date(
    new Date(votes[0].created_at).getTime() + 100,
  ).toISOString();
  const createdTo = new Date(
    new Date(votes[2].created_at).getTime() - 100,
  ).toISOString();
  const timeWindowResult =
    await api.functional.discussionBoard.member.comments.commentVotes.search(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          created_from: createdFrom,
          created_to: createdTo,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(timeWindowResult);
  TestValidator.predicate("all votes are within the time window")(
    timeWindowResult.data.every(
      (v) => v.created_at >= createdFrom && v.created_at <= createdTo,
    ),
  );
}

