/**
 * Validates that both guests and authenticated members can retrieve a paginated
 * list of discussion board posts.
 *
 * Ensures:
 *
 * - For both guests (not logged in) and registered members:
 *
 *   - Only non-deleted posts are included
 *   - Pagination metadata and summary post array returned
 *   - Each post contains all summary fields (id, title, discussion_board_member_id,
 *       etc.)
 * - RBAC/visibility:
 *
 *   - Guest sees only posts allowed by public visibility rules
 *   - Member sees at least all posts visible to guest (may include private posts if
 *       permissions allow)
 *   - Posts visible to guest form a subset of member-visible posts
 *
 * Limitations:
 *
 * - Cannot seed/create posts (API lacks create); test only covers retrieval with
 *   existing data
 * - No login/authentication step (API lacks member login); all calls use same
 *   connection (would be improved in E2E with login context)
 *
 * Steps:
 *
 * 1. As guest, request post list and verify list structure and types.
 * 2. Register a new member (simulates a user, to distinguish member vs. guest
 *    privilege).
 * 3. As (simulated) member, request post list again and verify structure.
 * 4. Validate that all posts visible to guest are also visible to member.
 * 5. Check that post summary fields are present in all posts returned.
 */
export async function test_api_discussionBoard_test_list_posts_for_guests_and_members(
  connection: api.IConnection,
) {
  // 1. As guest, retrieve paginated list of posts
  const guestPosts =
    await api.functional.discussionBoard.posts.index(connection);
  typia.assert(guestPosts);
  TestValidator.predicate("guest list is valid page")(
    guestPosts.pagination && Array.isArray(guestPosts.data),
  );

  // 2. Create a member to simulate member-specific access
  const memberInput = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.create(
    connection,
    { body: memberInput },
  );
  typia.assert(member);

  // 3. As the new member, request paginated list of posts again (API does not provide login, so token is same)
  const memberPosts =
    await api.functional.discussionBoard.posts.index(connection);
  typia.assert(memberPosts);
  TestValidator.predicate("member list is valid page")(
    memberPosts.pagination && Array.isArray(memberPosts.data),
  );

  // 4. Verify RBAC: every post visible to guest must also be included for the member
  const guestIds = new Set(guestPosts.data.map((p) => p.id));
  const memberIds = new Set(memberPosts.data.map((p) => p.id));
  for (const id of guestIds) {
    TestValidator.predicate(`RBAC: post ${id} is visible to member as well`)(
      memberIds.has(id),
    );
  }

  // 5. Validate each post has all summary fields (id, title, discussion_board_member_id)
  for (const post of [...guestPosts.data, ...memberPosts.data]) {
    TestValidator.predicate("post has summary fields")(
      typeof post.id === "string" &&
        typeof post.title === "string" &&
        typeof post.discussion_board_member_id === "string",
    );
  }
}

