/**
 * Validate that soft-deleted discussion board posts are excluded from search.
 *
 * This test ensures business rules and audit-compliance for soft-deleted posts:
 * when a post is soft-deleted (by setting deleted_at), it must not appear in
 * normal/advanced search results. This is important for compliance,
 * user-expectation, and prevents accidental display of removed content.
 *
 * Steps:
 *
 * 1. Create a new discussion board post as a member (using the normal API).
 * 2. Soft-delete the post via the dedicated deletion endpoint.
 * 3. Search for posts using a filter that SHOULD match the post (by title
 *    substring), and confirm the soft-deleted post is NOT present in returned
 *    results.
 * 4. Validate not only by empty result, but by scanning returned post summaries to
 *    ensure (by id) the deleted post is not present regardless of paging or
 *    search semantics.
 */
export async function test_api_discussionBoard_test_search_posts_excludes_soft_deleted_items(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board post as a member.
  const postTitle = RandomGenerator.paragraph()(2);
  const postBody = RandomGenerator.content()(1)();
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: postTitle,
        body: postBody,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Soft-delete the post.
  await api.functional.discussionBoard.member.posts.erase(connection, {
    postId: post.id,
  });

  // 3. Search for posts with the same title substring (should NOT include deleted post).
  const searchResult = await api.functional.discussionBoard.posts.search(
    connection,
    {
      body: {
        title: postTitle,
      } satisfies IDiscussionBoardPost.IRequest,
    },
  );
  typia.assert(searchResult);

  // 4. Validate that the soft-deleted post does not appear in search results
  TestValidator.predicate("Soft-deleted post must not appear in search result")(
    searchResult.data.every((item) => item.id !== post.id),
  );
  TestValidator.equals("No matching soft-deleted post in result")(false)(
    searchResult.data.some((item) => item.id === post.id),
  );
}

