import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Test updating a tag with a non-existent tagId, expecting a 404 not found
 * error.
 *
 * This test attempts to update a tag in the discussion board admin system using
 * a tagId that does not correspond to any existing tag record. The intent is to
 * verify that the API correctly returns a 404 not found error for logically
 * invalid resource identifiers, even when the request body is otherwise valid.
 *
 * Steps:
 *
 * 1. Generate a random UUID to serve as a tagId which does not exist in the
 *    system.
 * 2. Construct a valid update body with at least one modifiable field filled out.
 * 3. Attempt to update the tag using the update API and the generated non-existent
 *    tagId.
 * 4. Use TestValidator.error to assert that a not found (404) error is thrown by
 *    the API.
 *
 * No setup or dependencies are required for this test, as it targets an error
 * condition for a non-existent resource.
 */
export async function test_api_discussionBoard_test_update_nonexistent_tag_should_return_not_found_error(
  connection: api.IConnection,
) {
  // 1. Generate a non-existent tag UUID
  const nonExistentTagId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a valid update body
  const updateBody: IDiscussionBoardTag.IUpdate = {
    label: "NonExistentTagUpdate",
    description: "Attempting update on a non-existent tag.",
    color: "#D0021B",
  };

  // 3. Attempt the update and assert a 404 not found error is thrown
  await TestValidator.error(
    "should return 404 not found when updating non-existent tag",
  )(() =>
    api.functional.discussionBoard.admin.tags.update(connection, {
      tagId: nonExistentTagId,
      body: updateBody,
    }),
  );
}

