 *
 * This test ensures that, when an admin soft-deletes a tag via the admin DELETE
 * endpoint, the operation succeeds and does not throw errors. Since the API
 * does not expose tag-listing or tag-detail GET endpoints, the test cannot
 * directly verify the presence of a `deleted_at` timestamp or the absence of
 * the tag for regular users. The workflow implements only supported API steps
 * and does not introduce any fictional API usage.
 *
 * Steps:
 *
 * 1. Create a new tag as an admin via the admin tag-creation API
 * 2. Soft-delete the tag using the admin tag erase (DELETE) function
 */
export async function test_api_discussionBoard_test_soft_delete_existing_tag_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a tag as admin
  const tag: IDiscussionBoardTag =
    await api.functional.discussionBoard.admin.tags.create(connection, {
      body: {
        label: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
