/**
 * Validate admin can retrieve all category-tag assignment records as expected.
 *
 * This test covers the administrative capability to audit and manage all
 * assignments linking discussion board categories to tags. To verify the admin
 * list endpoint, it will:
 *
 * 1. Create a tag (unique label, optional description/color).
 * 2. Create a category (unique name, optional description).
 * 3. Assign the created tag to the created category (creates a category-tag
 *    junction).
 * 4. Retrieve the full list of assignments via GET
 *    /discussionBoard/admin/categoryTags.
 * 5. Assert that the created assignment (matching category+tag IDs) is present in
 *    the returned data set
 * 6. Validate the schema of at least one returned assignment object
 */
export async function test_api_discussionBoard_admin_categoryTags_index(
  connection: api.IConnection,
) {
  // 1. Create a test tag
  const tag = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph()(),
        color: "#FF6600",
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tag);

  // 2. Create a test category
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 3. Assign tag to category
  const assignment =
    await api.functional.discussionBoard.admin.categoryTags.create(connection, {
      body: {
        discussion_board_category_id: category.id,
        discussion_board_tag_id: tag.id,
      } satisfies IDiscussionBoardCategoryTag.ICreate,
    });
  typia.assert(assignment);

  // 4. Retrieve all assignments as admin
  const page =
    await api.functional.discussionBoard.admin.categoryTags.index(connection);
  typia.assert(page);

  // 5. Assert the created assignment is present in the results
  const found = page.data.find(
    (item) =>
      item.id === assignment.id &&
      item.discussion_board_category_id === category.id &&
      item.discussion_board_tag_id === tag.id,
  );
  TestValidator.predicate("assignment present")(!!found);

  // 6. Validate assignment object schema (done via typia.assert above)
}

