import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";

/**
 * Validate that an authenticated member can successfully file a content/abuse
 * report on a post using the moderator dashboard endpoint.
 *
 * This scenario covers the following business logic:
 *
 * - Registration of a new member (to act as reporter)
 * - Creation of a new post by the registered member
 * - Submission of a content report referencing that post, with all proper reasons
 *   and category
 * - The API must correctly link the report to the reporter, validate content
 *   references, and initialize with a valid status
 * - Assert that report status is 'pending' or 'under_review' and correctly
 *   references both reporter and post
 *
 * Step-by-step process:
 *
 * 1. Register a new member
 * 2. Authenticate/obtain session as this member if required (assume connection is
 *    persisted)
 * 3. Create a valid post as this member, retrieving the resulting post id
 * 4. Submit a content report, referencing the post id and valid reason/category
 * 5. Assert the returned report's status, reporter_member_id, and report linkage
 */
export async function test_api_discussionBoard_test_create_content_report_with_valid_member_data(
  connection: api.IConnection,
) {
  // 1. Register a new member to use as the reporting user
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const displayName: string = RandomGenerator.name();
  const passwordHash: string = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: displayName,
        email: memberEmail,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a sample post to be reported by the member
  // (Assume connection uses the just-registered member session)
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(),
        parent_id: null,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Submit a valid content abuse report through moderator endpoint
  const reportCategory = "policy"; // Example: business logic may have enums
  const reportReason =
    "Reported for moderator review: suspected policy violation.";
  const contentReport =
    await api.functional.discussionBoard.moderator.contentReports.create(
      connection,
      {
        body: {
          discussion_board_post_id: post.id,
          discussion_board_comment_id: null,
          content_type: "post",
          category: reportCategory,
          reason: reportReason,
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(contentReport);

  // 4. Assert the report is linked and initialized properly
  TestValidator.equals("reporter_member_id matches")(
    contentReport.reporter_member_id,
  )(member.id);
  TestValidator.equals("reported post linkage")(
    contentReport.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("content type is 'post'")(contentReport.content_type)(
    "post",
  );
  TestValidator.equals("category correct")(contentReport.category)(
    reportCategory,
  );
  TestValidator.equals("reason correct")(contentReport.reason)(reportReason);
  TestValidator.predicate("status must be pending or under_review")(
    ["pending", "under_review"].includes(contentReport.status),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
