/**
 * Validate that the moderator content reporting endpoint returns an error when
 * reporting with an invalid/nonexistent post or comment ID.
 *
 * Business context: This scenario ensures the moderation/reporting API rejects
 * attempts to file abuse/moderation reports against content that does not
 * exist, using proper business validation (not type or server error). This
 * protects moderation/audit records from referencing invalid targets and
 * enforces content existence requirements as described in API/DTOs. The flow is
 * negative (failure expected).
 *
 * Steps:
 *
 * 1. Register a new member (using required fields: display_name, email,
 *    password_hash)
 * 2. As this member, attempt to create a report referencing a fake/nonexistent
 *    post ID (content_type: "post"). Expect failure.
 * 3. As this member, attempt to create a report referencing a fake/nonexistent
 *    comment ID (content_type: "comment"). Expect failure.
 * 4. Verify both operations fail by checking that TestValidator.error catches
 *    errors.
 * 5. No additional report lookups/cleanup due to API limitations.
 */
export async function test_api_discussionBoard_moderator_contentReports_test_create_content_report_failure_on_invalid_content_id(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const memberPassword = RandomGenerator.alphabets(14);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPassword,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Attempt to report a non-existent post (invalid post id)
  const invalidPostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("report creation should fail for invalid post id")(
    () =>
      api.functional.discussionBoard.moderator.contentReports.create(
        connection,
        {
          body: {
            discussion_board_post_id: invalidPostId,
            discussion_board_comment_id: null,
            content_type: "post",
            category: "policy",
            reason: "Testing invalid post reporting",
          } satisfies IDiscussionBoardContentReport.ICreate,
        },
      ),
  );

  // 3. Attempt to report a non-existent comment (invalid comment id)
  const invalidCommentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "report creation should fail for invalid comment id",
  )(() =>
    api.functional.discussionBoard.moderator.contentReports.create(connection, {
      body: {
        discussion_board_post_id: null,
        discussion_board_comment_id: invalidCommentId,
        content_type: "comment",
        category: "spam",
        reason: "Testing invalid comment reporting",
      } satisfies IDiscussionBoardContentReport.ICreate,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
