import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";

/**
 * Validate duplicate prevention when creating a content report for the same
 * content and reason.
 *
 * This test ensures the API enforces deduplication/idempotence logic so that
 * the same member cannot submit more than one abuse report with the identical
 * target and details (e.g., post, category, and rationale). It verifies that
 * subsequent identical submissions are rejected.
 *
 * Workflow:
 *
 * 1. Register a new member for the discussion board.
 * 2. Make this member create a new post.
 * 3. File a moderation report for the new post with specific category/reason (as a
 *    member, using moderator/contentReports endpoint).
 * 4. Attempt to file another report for the same post, with the same
 *    category/reason by the same member. The API should reject this as a
 *    duplicate.
 * 5. Assert that the first report is accepted and the second is rejected with an
 *    appropriate error.
 */
export async function test_api_discussionBoard_test_create_content_report_duplicate_prevention_for_same_content_and_reason(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const password_hash = typia.random<string>();
  const display_name = RandomGenerator.name();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name,
        email,
        password_hash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Member creates a new post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(3),
        body: RandomGenerator.content()()(2),
        parent_id: null,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Submit first content report for the post
  const reportCategory = "spam";
  const reportReason = "Repeated advertising of the same link.";
  const report1 =
    await api.functional.discussionBoard.moderator.contentReports.create(
      connection,
      {
        body: {
          discussion_board_post_id: post.id,
          discussion_board_comment_id: null,
          content_type: "post",
          category: reportCategory,
          reason: reportReason,
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(report1);

  // 4. Attempt duplicate report for the same post, category, and reason
  await TestValidator.error("Should prevent duplicate content report")(
    async () => {
      await api.functional.discussionBoard.moderator.contentReports.create(
        connection,
        {
          body: {
            discussion_board_post_id: post.id,
            discussion_board_comment_id: null,
            content_type: "post",
            category: reportCategory,
            reason: reportReason,
          } satisfies IDiscussionBoardContentReport.ICreate,
        },
      );
    },
  );
}

