 *
 * Business context and necessity: Moderators may challenge completed moderation
 * actions (such as suspensions, removals). Appeals must link to a real
 * moderation action, reference the correct moderator as appellant, and have an
 * audit trail. This test ensures only valid appeals are created and
 * workflow/audit rules are respected.
 *
 * Steps:
 *
 * 1. Create a new moderation action as a moderator (dependency setup, e.g.,
 *    'suspend' or 'delete')
 * 2. Submit a new appeal referencing that action, with rationale and moderator ID
 *    in appellant_moderator_id (all other role fields null)
 * 3. Verify response: appeal is created, status is 'pending', action_id links
 *    correctly, and audit fields (timestamps, IDs) are present
 * 4. Confirm business rules: only one role ID set, valid status, correct audit
 *    linkage
 */
export async function test_api_discussionBoard_moderator_appeals_test_create_appeal_on_moderation_action_by_moderator_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a moderation action as a moderator
  const reportId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const moderationAction =
    await api.functional.discussionBoard.moderator.moderationActions.create(
      connection,
      {
        body: {
          report_id: reportId,
          admin_id: null,
          moderator_id: moderatorId,
          action_type: "suspend",
          description: "Moderator test action for appeal eligibility.",
        } satisfies IDiscussionBoardModerationAction.ICreate,
      },
    );
  typia.assert(moderationAction);

  // 2. Submit appeal with valid action_id, moderator as appellant, and rationale
  const rationale = "Moderator believes the suspension was not justified.";
  const appeal = await api.functional.discussionBoard.moderator.appeals.create(
    connection,
    {
      body: {
        action_id: moderationAction.id,
        reason: rationale,
        status: "pending",
        appellant_admin_id: null,
        appellant_moderator_id: moderatorId,
        appellant_member_id: null,
        appellant_guest_id: null,
      } satisfies IDiscussionBoardAppeal.ICreate,
    },
  );
  typia.assert(appeal);

  // 3. Verify creation & audit fields
  TestValidator.equals("appeal status should be pending")(appeal.status)(
    "pending",
  );
  TestValidator.equals("action ID links")(appeal.action_id)(
    moderationAction.id,
  );
  TestValidator.equals("moderator ID as appellant")(
    appeal.appellant_moderator_id,
  )(moderatorId);
  TestValidator.equals("admin appellant null")(appeal.appellant_admin_id)(null);
  TestValidator.equals("member appellant null")(appeal.appellant_member_id)(
    null,
  );
  TestValidator.equals("guest appellant null")(appeal.appellant_guest_id)(null);
  TestValidator.predicate("submitted_at present and ISO8601")(
    typeof appeal.submitted_at === "string" && appeal.submitted_at.length > 0,
  );

  // 4. Only one role present (moderator)
  const roleFields = [
    appeal.appellant_admin_id,
    appeal.appellant_moderator_id,
    appeal.appellant_member_id,
    appeal.appellant_guest_id,
  ];
  TestValidator.equals("only one non-null role field")(
    roleFields.filter((v) => v !== null).length,
  )(1);
}

