/**
 * Verify that an admin can successfully update a moderation appeal's status
 * from pending to approved, including rationale update.
 *
 * Business context: Appeals go through state transitions by authorized actors.
 * This test ensures admin workflow functions as expected, proper field updates
 * occur, and compliance/audit records reflect the change.
 *
 * Steps:
 *
 * 1. Create a new pending appeal using the moderator-level API (dependency setup).
 * 2. As admin, call the update API using the unique appealId, change status to
 *    'approved', and provide a new rationale.
 * 3. Confirm the response reflects updated status, rationale, and resolved_at
 *    timestamp present.
 * 4. (If possible with system hooks) Optionally, audit/compliance hooks trigger as
 *    intended.
 */
export async function test_api_discussionBoard_test_admin_update_appeal_status_to_approved_and_rationale(
  connection: api.IConnection,
) {
  // 1. Create a pending appeal (setup step)
  const actionId = typia.random<string & tags.Format<"uuid">>();
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const initialAppeal =
    await api.functional.discussionBoard.moderator.appeals.create(connection, {
      body: {
        action_id: actionId,
        reason:
          "Moderator contests the decision to remove a post on basis of insufficient evidence.",
        status: "pending",
        appellant_moderator_id: moderatorId,
        appellant_admin_id: null,
        appellant_member_id: null,
        appellant_guest_id: null,
      } satisfies IDiscussionBoardAppeal.ICreate,
    });
  typia.assert(initialAppeal);

  // 2. Admin updates the appeal: approve + rationale
  const adminDecisionRationale =
    "Reviewed the moderation appeal and found enough justification to revert the action.";
  const beforeUpdateResolvedAt = initialAppeal.resolved_at;
  const updatedAppeal =
    await api.functional.discussionBoard.admin.appeals.update(connection, {
      appealId: initialAppeal.id,
      body: {
        status: "approved",
        reason: adminDecisionRationale,
        resolved_at: new Date().toISOString(),
      } satisfies IDiscussionBoardAppeal.IUpdate,
    });
  typia.assert(updatedAppeal);

  // 3. Validate update reflected in output
  TestValidator.equals("Appeal ID unchanged")(updatedAppeal.id)(
    initialAppeal.id,
  );
  TestValidator.equals("Appeal status updated to approved")(
    updatedAppeal.status,
  )("approved");
  TestValidator.equals("Rationale updated")(updatedAppeal.reason)(
    adminDecisionRationale,
  );
  TestValidator.predicate(
    "resolved_at should now be present and valid ISO timestamp",
  )(
    !!updatedAppeal.resolved_at &&
      !isNaN(Date.parse(updatedAppeal.resolved_at)),
  );
  TestValidator.notEquals("resolved_at changed from pre-update")(
    updatedAppeal.resolved_at,
  )(beforeUpdateResolvedAt);

  // 4. (Optionally) Audit/compliance hooks would be checked here if accessible via separate audit log APIs or system hooks
}

