 * moderation actions and change their status to 'denied' or 'approved' with an
 * audit rationale. The audit trail (including rationale, timestamps, and
 * status) must be preserved and visible after the update to meet compliance
 * standards.
 *
 * Steps:
 *
 * 1. Create an appeal with status 'pending' using the appropriate API
 *    (dependency).
 * 2. As a moderator, update the status of the created appeal to 'denied' and set a
 *    rationale.
 * 3. Verify: (a) the updated appeal has status 'denied', (b) rationale matches
 *    what was set, (c) the ID and audit fields (such as timestamps) are
 *    present, (d) all previous audit/history fields are still valid after the
 *    update.
 */
export async function test_api_discussionBoard_test_moderator_update_appeal_status_to_denied_with_rationale(
  connection: api.IConnection,
) {
  // 1. Create a pending appeal as Precondition
  const createInput: IDiscussionBoardAppeal.ICreate = {
    action_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Appellant request for review of moderation action.",
    status: "pending",
    appellant_admin_id: null,
    appellant_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    appellant_member_id: null,
    appellant_guest_id: null,
  };
