 * This test simulates realistic forum comment searching, ensuring advanced
 * filters (by member, by parent_id, by creation date) work. Steps:
 *
 * 1. Register two members (authors)
 * 2. Create a post by member1
 * 3. Add comments by both members, including top-level and replies
 * 4. Search/filter by:
 *
 *    - Member (should only return comments authored by that member)
 *    - Parent_id (should only return replies to specific comment)
 *    - Time window (should only return comments created in range) Assertions check
 *         that only the correct subset of comments are returned in each case,
 *         per business requirements for moderation/search UI.
 */
export async function test_api_discussionBoard_test_advanced_comment_search_returns_only_filtered_results(
  connection: api.IConnection,
) {
  // 1. Register two members (distinct authors)
  const member1 = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(12),
