    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(12),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member2);

  // 2. Create a post as member1
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(5),
        body: RandomGenerator.content()(3)(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Add comments with various authors/threads
  const comment1 =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: "Parent Comment 1 by Member1",
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment1);

  const comment2 =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          parent_id: comment1.id,
          body: "Reply to Comment 1 by Member2",
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment2);

  const comment3 =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: "Independent Comment 2 by Member2",
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment3);

  // 4. Advanced searches/assertions
  // (a) Filter by member1
  const byMember1 = await api.functional.discussionBoard.posts.comments.search(
    connection,
    {
      postId: post.id,
      body: {
