    byMember1.data.every((c) => c.discussion_board_member_id === member1.id),
  );

  // (b) Filter by member2
  const byMember2 = await api.functional.discussionBoard.posts.comments.search(
    connection,
    {
      postId: post.id,
      body: {
        discussion_board_member_id: member2.id,
      } satisfies IDiscussionBoardComment.IRequest,
