    byParent.data.every((c) => c.parent_id === comment1.id),
  );

  // (d) Filter by creation time window
  const createdFrom = comment1.created_at;
  const createdTo = comment3.created_at;
  const byTimeRange =
    await api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        created_from: createdFrom,
        created_to: createdTo,
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(byTimeRange);
  TestValidator.predicate("all comments in time range")(
    byTimeRange.data.every(
      (c) => c.created_at >= createdFrom && c.created_at <= createdTo,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that soft-deleted comments are not visible to guest
 * (unauthenticated) users in advanced comment search.
 *
 * Context:
 *
 * - Guests and ordinary users should not see comments that have been
 *   soft-deleted.
 * - Moderators/admins may see soft-deleted comments (not tested here).
 *
 * Steps:
 *
 * 1. Register a new discussion board member.
 * 2. As that member, create a new post.
 * 3. As that member, add multiple comments to the post.
 * 4. Soft-delete some comments.
 * 5. As a guest, perform a comment search for all comments on the post.
 * 6. Confirm that soft-deleted comments are excluded from the result data.
 * 7. Confirm non-deleted comments are included.
 * 8. Edge case: Soft-delete all comments and confirm search yields none.
 */
export async function test_api_discussionBoard_test_advanced_comment_search_excludes_soft_deleted_for_guest(
  connection: api.IConnection,
) {
  // 1. Register a member for comment creation
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(16),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a post as that member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.paragraph()(2),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Add multiple comments as that member
  const comments: IDiscussionBoardComment[] = [];
  for (const body of ["First comment", "Second comment", "Third comment"]) {
    const created =
      await api.functional.discussionBoard.member.posts.comments.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            body,
          } satisfies IDiscussionBoardComment.ICreate,
        },
      );
    typia.assert(created);
    comments.push(created);
  }

  // 4. Soft-delete one (middle) comment
  const erased = comments[1];
  await api.functional.discussionBoard.member.posts.comments.erase(connection, {
    postId: post.id,
    commentId: erased.id,
  });

  // 5. As unauthenticated guest, search all comments for post
  const searchResult =
    await api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        discussion_board_post_id: post.id,
        limit: 10,
        page: 1,
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(searchResult);

  // 6. Confirm erased comment is absent
  const searchIds = searchResult.data.map((c) => c.id);
  TestValidator.predicate("soft-deleted not present")(
    !searchIds.includes(erased.id),
  );

  // 7. Confirm remaining comments are present
  for (let i = 0; i < comments.length; ++i) {
    if (i === 1) continue;
    TestValidator.predicate(`comment ${i} returned`)(
      searchIds.includes(comments[i].id),
    );
  }

  // 8. Edge case: soft-delete all, check search yields zero
  for (let i = 0; i < comments.length; ++i) {
    if (i !== 1)
      await api.functional.discussionBoard.member.posts.comments.erase(
        connection,
        {
          postId: post.id,
          commentId: comments[i].id,
        },
      );
  }
  const afterAllErased =
    await api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        discussion_board_post_id: post.id,
        limit: 10,
        page: 1,
      } satisfies IDiscussionBoardComment.IRequest,
    });
  typia.assert(afterAllErased);
  TestValidator.equals("none remain")(afterAllErased.data.length)(0);
}

