/**
 * E2E test: Moderator invalid date range search for post edit history.
 *
 * This test verifies that the moderator receives a validation error when
 * executing a PATCH search for post edit histories with an invalid date range
 * (for example, when end date is before start date, or obviously out-of-bounds
 * date values are used).
 *
 * Business Workflow:
 *
 * 1. Create a moderator (admin privilege assumed for API call).
 * 2. Create a member post (to later target edit history of a real post).
 * 3. Attempt to perform a search using PATCH
 *    /discussionBoard/moderator/posts/{postId}/postEdits, specifying an invalid
 *    date range (such as an end date precedes start date, or use impossible
 *    date values).
 * 4. Check that the API call fails and returns an error as expected, specifically
 *    due to the invalid date parameters.
 *
 * Validation:
 *
 * - Use TestValidator.error() to ensure error is thrown when dates are invalid.
 * - Validate that a correctly structured error occurs, but don't match error
 *   message exactly per guidelines.
 * - Use realistic dates in ISO 8601 format, deliberately making end < start or
 *   using impossible values.
 */
export async function test_api_discussionBoard_test_moderator_search_post_edits_with_invalid_date_range(
  connection: api.IConnection,
) {
  // 1. Create a moderator (admin context assumed).
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorUsername: string = RandomGenerator.alphaNumeric(10);
  const moderator: IDiscussionBoardModerator =
