/**
 * Validates successful creation of a comment upvote (vote) by a newly
 * registered, authenticated member.
 *
 * Business Context: Only active, authenticated discussion board members can
 * upvote comments. Upvotes are tracked for audit and analytics. This test
 * simulates a full journey: member registration, post creation, adding a
 * comment, and voting—validating correct linkage, authorization, and data
 * integrity.
 *
 * Process:
 *
 * 1. Register a new member account with unique email and display name.
 * 2. As the member, create a discussion board post.
 * 3. Add a comment to the created post as the same member.
 * 4. As the logged-in member, submit an upvote for the comment.
 * 5. Verify a successful upvote response, correct linkage of member and comment,
 *    and valid vote audit metadata.
 */
export async function test_api_discussionBoard_test_create_comment_vote_success_as_member(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. As the member, create a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);
  TestValidator.equals("author is the member")(post.discussion_board_member_id)(
    member.id,
  );

  // 3. Add a comment as the member
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.content()(1)(),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);
  TestValidator.equals("comment is for the post")(
    comment.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("comment author is the member")(
    comment.discussion_board_member_id,
  )(member.id);

  // 4. Vote (upvote) on the comment
  const vote =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
