  TestValidator.equals("vote links to comment")(
    vote.discussion_board_comment_id,
  )(comment.id);
  TestValidator.equals("vote author is member")(
    vote.discussion_board_member_id,
  )(member.id);
  TestValidator.equals("vote is upvote")(vote.upvote)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";

/**
 * Validates that creating a duplicate vote on the same comment by the same
 * member fails due to unique vote constraint enforcement.
 *
 * Business workflow covered:
 *
 * 1. Register a new member (which serves as implicit authentication)
 * 2. Member creates a discussion post
 * 3. Member adds a comment to the post
 * 4. Member submits an upvote for that comment
 * 5. Member attempts to submit another vote (upvote or downvote) on the same
 *    comment
 * 6. The API should reject the duplicate vote attempt and return a
 *    validation/business error, enforcing the business rule that a member can
 *    only vote once per comment.
 *
 * Steps:
 *
 * 1. Register a new discussion board member
 * 2. Create a post as that member
 * 3. Create a comment on the post
 * 4. Submit an upvote for the comment
 * 5. Confirm the first vote is saved
 * 6. Attempt a duplicate vote (can be upvote or downvote), expect an error
 */
export async function test_api_discussionBoard_test_create_comment_vote_duplicate_vote_fails(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const memberPasswordHash = RandomGenerator.alphaNumeric(24); // Simulate password hash
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new post as this member (authentication context assumed via connection)
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(3),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Member creates a comment on the post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(2),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 4. Submit an upvote for the comment
  const firstVote =
    await api.functional.discussionBoard.member.comments.commentVotes.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          upvote: true,
        } satisfies IDiscussionBoardCommentVote.ICreate,
      },
    );
  typia.assert(firstVote);
  // 5. Confirm that the saved vote matches input details
  TestValidator.equals("vote upvote flag")(firstVote.upvote)(true);
  TestValidator.equals("vote member ID")(firstVote.discussion_board_member_id)(
    member.id,
  );
  TestValidator.equals("vote comment ID")(
    firstVote.discussion_board_comment_id,
  )(comment.id);

  // 6. Attempt to add a duplicate vote on the same comment, expect business validation error
  await TestValidator.error("duplicate comment vote by same member fails")(
    async () => {
      await api.functional.discussionBoard.member.comments.commentVotes.create(
        connection,
        {
          commentId: comment.id,
          body: {
            discussion_board_comment_id: comment.id,
            upvote: false, // Downvote also violates unique constraint
          } satisfies IDiscussionBoardCommentVote.ICreate,
        },
      );
    },
  );
}

