  for (const tagInput of tagInputs) {
    const tag = await api.functional.discussionBoard.admin.tags.create(
      connection,
      { body: tagInput },
    );
    typia.assert(tag);
    tags.push(tag);
  }

  // 4. Assign several tags to the post as the member
  const postTagAssignments = [] as IDiscussionBoardPostTag[];
  for (const tag of tags) {
    const assignInput: IDiscussionBoardPostTag.ICreate = {
      discussion_board_post_id: post.id,
      discussion_board_tag_id: tag.id,
    };
    const assigned =
      await api.functional.discussionBoard.member.posts.postTags.create(
        connection,
        {
          postId: post.id,
          body: assignInput,
        },
      );
    typia.assert(assigned);
    postTagAssignments.push(assigned);
  }

  // 5. Fetch tags for the post, verify that all assignments are present
  const result =
    await api.functional.discussionBoard.member.posts.postTags.index(
      connection,
      { postId: post.id },
    );
  typia.assert(result);
  TestValidator.equals("postTags list length")(result.data.length)(
    postTagAssignments.length,
  );
  const assignmentIdsSorted = [...postTagAssignments].map((x) => x.id).sort();
  const resultIdsSorted = [...result.data].map((x) => x.id).sort();
  TestValidator.equals("postTag IDs match")(assignmentIdsSorted)(
    resultIdsSorted,
  );
  for (const tagAssignment of postTagAssignments) {
    const found = result.data.find((x) => x.id === tagAssignment.id);
    TestValidator.predicate(
      `assignment for tag ${tagAssignment.discussion_board_tag_id} found`,
    )(!!found);
    if (found) {
      TestValidator.equals("post id")(found.discussion_board_post_id)(
        tagAssignment.discussion_board_post_id,
      );
      TestValidator.equals("tag id")(found.discussion_board_tag_id)(
        tagAssignment.discussion_board_tag_id,
      );
    }
  }

  // 6. Edge case: Create another post, do not assign any tags
  const postNoTagInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
  };
  const postNoTags = await api.functional.discussionBoard.member.posts.create(
    connection,
    { body: postNoTagInput },
  );
  typia.assert(postNoTags);
  const emptyTagResult =
    await api.functional.discussionBoard.member.posts.postTags.index(
      connection,
      { postId: postNoTags.id },
    );
  typia.assert(emptyTagResult);
  TestValidator.equals("postTags should be empty")(emptyTagResult.data.length)(
    0,
  );
}

