/**
 * E2E test for searching and paginating post-tag associations for a given post
 * as a member.
 *
 * This function validates the ability to search and paginate tag assignments
 * for a discussion board post as an authenticated member. It sets up the
 * necessary context including creating a member, a post, several tags, and
 * associating these tags with the post. It then exercises the search endpoint
 * with a variety of filters and pagination parameters, and ensures correct
 * output and error handling.
 *
 * Test Workflow:
 *
 * 1. Create a member (to perform authenticated actions).
 * 2. Create a post as that member.
 * 3. Create several tags as admin (since only admin can create tags).
 * 4. Associate multiple tags with the post as the member.
 * 5. Search for post-tag associations (no filters): should return all associations
 *    paginated, and all assigned tags' IDs should be returned.
 * 6. Search using a specific tag id filter: should return only the matching
 *    association.
 * 7. Paginate: use limit and page parameters to check correct slicing of results
 *    and metadata.
 * 8. Try invalid filters (e.g., invalid tag id): expect zero results.
 */
export async function test_api_discussionBoard_test_search_post_tags_with_filters_member(
  connection: api.IConnection,
) {
  // 1. Create test member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(20),
      },
    },
  );
  typia.assert(member);

  // 2. Create post as this member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 3. Create tags as admin (simulate elevated permissions if necessary)
  const tagCount = 4;
  const tagsArr: IDiscussionBoardTag[] = [];
  for (let i = 0; i < tagCount; ++i) {
    const tag = await api.functional.discussionBoard.admin.tags.create(
      connection,
      {
        body: {
          label: RandomGenerator.alphabets(10),
          description: RandomGenerator.paragraph()(),
          color: "#" + Math.floor(Math.random() * 16777215).toString(16),
        },
      },
    );
    typia.assert(tag);
    tagsArr.push(tag);
  }

  // 4. Assign each tag to the post
  const postTags: IDiscussionBoardPostTag[] = [];
  for (const tag of tagsArr) {
    const pt =
      await api.functional.discussionBoard.member.posts.postTags.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            discussion_board_tag_id: tag.id,
          },
        },
      );
    typia.assert(pt);
    postTags.push(pt);
  }

  // 5. Search with no filters (fetch all, default page/limit)
  const searchAll =
    await api.functional.discussionBoard.member.posts.postTags.search(
      connection,
      {
        postId: post.id,
        body: {},
      },
    );
  typia.assert(searchAll);
  // All post-tag IDs assigned above must be present in result. Compare as sets.
  const resultTagIds = new Set(
    searchAll.data.map((x) => x.discussion_board_tag_id),
  );
  for (const tag of tagsArr) {
    TestValidator.predicate("assigned tag is present")(
      resultTagIds.has(tag.id),
    );
  }

  // 6. Search with a specific tag_id filter
  const targetTag = tagsArr[1];
  const searchByTag =
    await api.functional.discussionBoard.member.posts.postTags.search(
      connection,
      {
        postId: post.id,
        body: { discussion_board_tag_id: targetTag.id },
      },
    );
  typia.assert(searchByTag);
  TestValidator.equals("filter by tag")(searchByTag.data.length)(1);
  TestValidator.equals("filter by tag id")(
    searchByTag.data[0]?.discussion_board_tag_id,
  )(targetTag.id);
  TestValidator.equals("filter post matches")(
    searchByTag.data[0]?.discussion_board_post_id,
  )(post.id);

  // 7. Pagination: test limit/page
  const pageLimit = 2;
  // First page
  const paginatedPage1 =
    await api.functional.discussionBoard.member.posts.postTags.search(
      connection,
      {
        postId: post.id,
        body: { limit: pageLimit, page: 1 },
      },
    );
  typia.assert(paginatedPage1);
  TestValidator.equals("paginated limit, page1")(
    paginatedPage1.pagination.limit,
  )(pageLimit);
  TestValidator.predicate("page1 data <= limit")(
    paginatedPage1.data.length <= pageLimit,
  );
  TestValidator.equals("pagination page1 current")(
    paginatedPage1.pagination.current,
  )(1);
  // Second page if more tags exist
  if (tagCount > pageLimit) {
    const paginatedPage2 =
      await api.functional.discussionBoard.member.posts.postTags.search(
        connection,
        {
          postId: post.id,
          body: { limit: pageLimit, page: 2 },
        },
      );
    typia.assert(paginatedPage2);
    TestValidator.equals("paginated limit, page2")(
      paginatedPage2.pagination.limit,
    )(pageLimit);
    TestValidator.equals("pagination page2 current")(
      paginatedPage2.pagination.current,
    )(2);
    // The sum of results over both pages is at least tagCount
    TestValidator.predicate("paginated combined >= tagCount")(
      paginatedPage1.data.length + paginatedPage2.data.length >= tagCount,
    );
  }

  // 8. Invalid filter: use an unknown tag id
  const invalidTagId = typia.random<string & tags.Format<"uuid">>();
  const searchInvalidTag =
    await api.functional.discussionBoard.member.posts.postTags.search(
      connection,
      {
        postId: post.id,
        body: { discussion_board_tag_id: invalidTagId },
      },
    );
  typia.assert(searchInvalidTag);
  TestValidator.equals("no matches for invalid tag id")(
    searchInvalidTag.data.length,
  )(0);
}

