/**
 * Validate updating a post-tag association by a member user.
 *
 * This test covers the scenario where a member creates a post, assigns a tag,
 * and then updates the tag assignment to a different, valid tag. It verifies
 * that the system properly updates the tag linkage in the post-tag association,
 * returns the updated association, and keeps the link to the original post
 * unchanged. Only valid schema-defined updatable fields are modified.
 *
 * Step-by-step process:
 *
 * 1. Register a new member account to use as the author.
 * 2. As the member, create a discussion board post.
 * 3. As admin, create two tags (needed to effect the tag update).
 * 4. Assign the first tag to the post.
 * 5. Update that post-tag association to set the second tag as the new assignment.
 * 6. Assert via response that the association now references the new tag but
 *    retains the post id.
 */
export async function test_api_discussionBoard_test_update_post_tag_assignment_success(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. As the member, create a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);
  TestValidator.equals("author member id")(post.discussion_board_member_id)(
    member.id,
  );

  // 3. As admin, create two distinct tags
  const tagA = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(1),
        color: "#FF0000",
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tagA);
  const tagB = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(1),
        color: "#00FF00",
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tagB);
  TestValidator.notEquals("tags are different")(tagA.id)(tagB.id);

  // 4. Assign the first tag to the post
  const postTag =
    await api.functional.discussionBoard.member.posts.postTags.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
