import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";
import type { IPageIDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching post votes with multiple filters and pagination.
 *
 * This test ensures that post votes for a particular post can be correctly
 * filtered by vote type, member, and paginated. It simulates multiple members
 * registering and voting on a post with both upvotes and downvotes, then
 * validates the search endpoint returns only the matching filtered results,
 * along with accurate pagination.
 *
 * Steps:
 *
 * 1. Register multiple members (at least three distinct members).
 * 2. One member creates a new post.
 * 3. Each member votes on the created post (some upvotes, some downvotes).
 * 4. Use the PATCH /discussionBoard/member/posts/{postId}/postVotes endpoint to:
 *    a. Filter only upvotes b. Filter only downvotes c. Filter by a specific
 *    member (e.g., member2) d. Use pagination: page 1 with limited results
 * 5. Verify that for each search:
 *
 *    - Only votes with matching filters are present in .data
 *    - Each vote's upvote/member/post_id fields match the search criteria
 *    - .pagination metadata is correct (e.g., total count, page, limit)
 */
export async function test_api_discussionBoard_test_search_post_votes_with_multiple_filters_success(
  connection: api.IConnection,
) {
  // 1. Register three distinct members
  const memberDatas = ArrayUtil.repeat(3)(
    () =>
      ({
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(16),
      }) satisfies IDiscussionBoardMember.ICreate,
  );

  const members = [] as IDiscussionBoardMember[];
  for (const data of memberDatas)
    members.push(
      await api.functional.discussionBoard.members.create(connection, {
        body: data,
      }),
    );

  // 2. First member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Each member votes: member1 upvotes, member2 upvotes, member3 downvotes
  const votes = [] as IDiscussionBoardPostVote[];
  for (let i = 0; i < members.length; ++i) {
    // Test framework must guarantee API calls are made in correct member context.
    const upvote = i < 2; // first two upvote, last one downvotes
    votes.push(
      await api.functional.discussionBoard.member.posts.postVotes.create(
        connection,
        {
          postId: post.id,
          body: { upvote } satisfies IDiscussionBoardPostVote.ICreate,
        },
      ),
    );
  }

  // 4a. Search: filter upvotes only
  const upvoteResult =
    await api.functional.discussionBoard.member.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: { upvote: true } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(upvoteResult);
  TestValidator.predicate("all votes are upvotes")(
    upvoteResult.data.every((v) => v.upvote === true),
  );

  // 4b. Search: filter downvotes only
  const downvoteResult =
    await api.functional.discussionBoard.member.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: { upvote: false } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(downvoteResult);
  TestValidator.predicate("all votes are downvotes")(
    downvoteResult.data.every((v) => v.upvote === false),
  );

  // 4c. Search: filter by specific member (member2)
  const member2Result =
    await api.functional.discussionBoard.member.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_member_id: members[1].id,
        } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(member2Result);
  TestValidator.predicate("all votes are from member2")(
    member2Result.data.every(
      (v) => v.discussion_board_member_id === members[1].id,
    ),
  );

  // 4d. Search: Pagination (limit 2, page 1)
  const pagedResult =
    await api.functional.discussionBoard.member.posts.postVotes.search(
      connection,
      {
        postId: post.id,
        body: { limit: 2, page: 1 } satisfies IDiscussionBoardPostVote.IRequest,
      },
    );
  typia.assert(pagedResult);
  TestValidator.equals("limit matches requested")(pagedResult.pagination.limit)(
    2,
  );
  TestValidator.equals("page matches requested")(
    pagedResult.pagination.current,
  )(1);
  TestValidator.predicate("no more than limit votes returned")(
    pagedResult.data.length <= 2,
  );
}

