 * endpoint, access date range, and result code. It is intended to support
 * compliance and event-traceability needs, ensuring that the search system can
 * help investigators track the precise sequence of events and actor
 * involvement.
 *
 * Steps:
 *
 * 1. Define complex search filters (e.g., admin_id, endpoint path,
 *    accessed_at_from/to, result code, pagination limit/page).
 * 2. Invoke the access log search endpoint with these criteria.
 * 3. Check that each log entry in the result list matches all filters provided (if
 *    filter is not null).
 * 4. Validate that pagination metadata (page, limit, records, pages) is correctly
 *    structured.
 * 5. Ensure at least one filter type (e.g., endpoint or date range) yields a
 *    non-empty, filtered result (if possible in system state).
 * 6. Verify field-level matching for compliance-ready querying (not just type
 *    safety but also correct business logic handling).
 */
export async function test_api_discussionBoard_admin_accessLogs_search_by_criteria(
  connection: api.IConnection,
) {
  // Step 1: Compose complex search criteria
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const endpointPath = "/discussionBoard/api/posts/123";
  const fromDate = new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString(); // 48 hours ago
  const toDate = new Date().toISOString();
  const resultCode = "success"; // or "failure", etc.
  const page = 1;
  const limit = 5;

  // Step 2: Call the API with the search parameters
  const response = await api.functional.discussionBoard.admin.accessLogs.search(
    connection,
    {
      body: {
        admin_id: adminId,
        endpoint: endpointPath,
        accessed_at_from: fromDate,
        accessed_at_to: toDate,
        result: resultCode,
        page,
        limit,
