 * Test workflow:
 *
 * 1. Create a new comment as a member, capturing the resulting comment's UUID.
 * 2. Create an initial comment edit event for that comment (simulate a real edit
 *    action).
 * 3. Generate a random bogus edit ID that is guaranteed not to match the real one.
 * 4. Attempt to update the comment edit using the correct comment ID but the bogus
 *    (non-existent) edit ID. The body may contain any valid update (e.g.,
 *    rationale), but the bogus ID must trigger a not found/error.
 * 5. Validate that the API throws an error (TestValidator.error). No further
 *    verification of unchanged state is performed, as there is no API to read
 *    edits by ID.
 */
export async function test_api_discussionBoard_test_update_comment_edit_with_invalid_edit_id_returns_error(
  connection: api.IConnection,
) {
  // 1. Create a comment for a discussion board post
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
