  // 3. Generate a new bogus (non-existent) edit ID, ensure it's different from the real one
  const bogusEditId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.notEquals("Edit ID is unique and bogus")(bogusEditId)(edit.id);

