/**
 * Validates that an admin can retrieve the complete edit history for any post
 * in the discussion board system, regardless of post authorship or edit count.
 *
 * Business context:
 *
 * - System administrators require full audit access to post edit histories for
 *   moderation, compliance, and dispute scenarios.
 * - Members may create posts and execute several edit events; each such event
 *   must be audit logged and accessible to admins.
 * - The admin endpoint exposes a complete, unfiltered audit trail for a given
 *   post, supporting transparency and investigation.
 *
 * Notes:
 *
 * - This test runs all steps in a single privileged simulation context (the e2e
 *   SDK does not support role-specific login sessions).
 * - Member/admin distinction is enforced by SDK invocation and random test data;
 *   password hashes are randomized as real authentication isn't tested.
 *
 * Test workflow:
 *
 * 1. Register a member.
 * 2. As that member, create a new post.
 * 3. Perform several edits to the post as the same member, each with a unique
 *    rationale and timestamp.
 * 4. Register an admin account (simulated separate actor).
 * 5. As admin, retrieve the full post edit history/audit log.
 * 6. Validate the returned data includes all expected edits and matches
 *    structure/ordering.
 */
export async function test_api_discussionBoard_test_admin_can_retrieve_edits_for_any_post(
  connection: api.IConnection,
) {
  // 1. Register a member for post authorship
  const memberInput: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(16),
  };
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: memberInput,
    },
  );
  typia.assert(member);

  // 2. Member creates a post
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: postInput,
    },
  );
  typia.assert(post);

  // 3. Member performs multiple edits
  const edits: IDiscussionBoardPostEdit[] = [];
  for (let i = 0; i < 3; ++i) {
    const editBody: IDiscussionBoardPostEdit.ICreate = {
      discussion_board_post_id: post.id,
      discussion_board_member_id: member.id,
      new_title: `Edit title #${i + 1}`,
      new_body: `Edit body content #${i + 1}`,
      edited_at: new Date(Date.now() + i * 1000).toISOString(),
      rationale: `Test rationale #${i + 1}`,
    };
    const edit =
      await api.functional.discussionBoard.member.posts.postEdits.create(
        connection,
        {
          postId: post.id,
          body: editBody,
        },
      );
    typia.assert(edit);
    edits.push(edit);
  }

  // 4. Register a new admin account
  const adminInput: IDiscussionBoardAdmin.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(20),
    is_active: true,
  };
  const admin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: adminInput,
    },
  );
  typia.assert(admin);

  // 5. (As admin) Retrieve the post's edit audit log
  const auditPage =
    await api.functional.discussionBoard.admin.posts.postEdits.index(
      connection,
      {
        postId: post.id,
      },
    );
  typia.assert(auditPage);

  // 6. Assert the response includes ALL created edits and structure/ordering is correct
  TestValidator.equals("edit count matches edits performed")(
    auditPage.data.length,
  )(edits.length);
  for (let i = 0; i < edits.length; ++i) {
    TestValidator.equals(`edit id at [${i}]`)(auditPage.data[i].id)(
      edits[i].id,
    );
    TestValidator.equals(`post id at [${i}]`)(
      auditPage.data[i].discussion_board_post_id,
    )(post.id);
    TestValidator.equals(`editor member id at [${i}]`)(
      auditPage.data[i].discussion_board_member_id,
    )(member.id);
  }
}

