import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSuspension";

/**
 * Tests that a banned or suspended member is unable to create a comment.
 *
 * Business context: Ensures that members with restricted status ('banned' or
 * 'suspended') cannot write comments on the discussion board. This verifies the
 * enforcement of moderation and compliance policies regarding account
 * restrictions and content creation.
 *
 * Steps:
 *
 * 1. Register a new member account.
 * 2. Create a post as this member.
 * 3. Impose a ban/suspension on the member using the admin suspension endpoint.
 * 4. Attempt to create a comment as this banned/suspended member. The API must
 *    reject this action.
 *
 * The function asserts that comment creation is denied for a banned/suspended
 * account by expecting an error on the API call.
 */
export async function test_api_discussionBoard_test_create_comment_for_banned_member(
  connection: api.IConnection,
) {
  // 1. Register a new member.
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphabets(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a post as that member.
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Impose a suspension (ban) on the member.
  const now = new Date().toISOString();
  const suspension =
    await api.functional.discussionBoard.admin.suspensions.create(connection, {
      body: {
        suspended_member_id: member.id,
        reason: "Automated test ban for restricted comments",
        suspended_at: now,
        status: "active",
      } satisfies IDiscussionBoardSuspension.ICreate,
    });
  typia.assert(suspension);

  // 4. Attempt to create a comment as banned/suspended member; should fail.
  await TestValidator.error("Banned/suspended member cannot create comment")(
    () =>
      api.functional.discussionBoard.member.comments.create(connection, {
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardComment.ICreate,
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Test successful update of a comment's body by its author.
 *
 * This scenario validates the workflow where a new member registers, creates a
 * post, adds a comment to their post, and then successfully updates the
 * comment's body as its author. The test ensures the updated content is
 * persisted and retrievable by loading the updated comment and comparing its
 * body to the new value.
 *
 * Steps:
 *
 * 1. Register a new member with valid display_name, email, and password_hash.
 * 2. Create a board post as that member.
 * 3. Add a top-level comment to the post as the same member.
 * 4. Update the comment's body to a new string as the author.
 * 5. Verify the returned updated comment has the new body.
 */
export async function test_api_discussionBoard_test_update_comment_as_author_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(64),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: memberInput,
    },
  );
  typia.assert(member);

  // 2. Create a post as that member
  const postInput = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: postInput,
    },
  );
  typia.assert(post);

  // 3. Add a comment to the post as the same member
  const commentInput = {
    discussion_board_post_id: post.id,
    body: RandomGenerator.paragraph()(1),
  } satisfies IDiscussionBoardComment.ICreate;
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: commentInput,
    },
  );
  typia.assert(comment);

  // 4. Update the comment's body as the author
  const updatedBody = RandomGenerator.paragraph()(2);
  const updated = await api.functional.discussionBoard.member.comments.update(
    connection,
    {
      commentId: comment.id,
      body: { body: updatedBody } satisfies IDiscussionBoardComment.IUpdate,
    },
  );
  typia.assert(updated);

  // 5. Check that the update is reflected in the returned object
  TestValidator.equals("comment body is updated")(updated.body)(updatedBody);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
