/**
 * This test verifies that only the original author of a comment can update it
 * and that a non-author receives an authorization error when attempting to do
 * so.
 *
 * Business context: It is a security and integrity requirement that only
 * comment authors (or privileged roles, not tested here) are permitted to edit
 * their discussion comments. This test covers the negative scenario: a
 * non-author member must not be able to update someone else's comment.
 *
 * Test workflow steps:
 *
 * 1. Register two members: one as the future comment author, one as non-author.
 * 2. (Using author) create a discussion post.
 * 3. (Using author) create a comment on that post.
 * 4. Attempt to update the comment as the non-author member.
 * 5. Assert that the API responds with an authorization error.
 */
export async function test_api_discussionBoard_test_update_comment_as_non_author(
  connection: api.IConnection,
) {
  // 1. Register the comment author
  const authorEmail = typia.random<string & tags.Format<"email">>();
  const authorDisplay = RandomGenerator.name();
  const author = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: authorDisplay,
        email: authorEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
      },
    },
  );
  typia.assert(author);

  // 2. Register the non-author member
  const nonAuthorEmail = typia.random<string & tags.Format<"email">>();
  const nonAuthorDisplay = RandomGenerator.name();
  const nonAuthor = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: nonAuthorDisplay,
        email: nonAuthorEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
      },
    },
  );
  typia.assert(nonAuthor);

  // 3. As the author, create a discussion post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 4. As the author, create a comment on the post
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        body: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(comment);

  // 5. Attempt to update the comment as the non-author member (API should reject this)
  await TestValidator.error("Non-author cannot update the comment")(
    async () => {
      await api.functional.discussionBoard.member.comments.update(connection, {
        commentId: comment.id,
        body: {
          body: RandomGenerator.paragraph()(),
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
