/**
 * Validate updating a non-existent discussion board comment.
 *
 * This test verifies the system correctly handles attempts to update a comment
 * using a UUID that does not correspond to any existing comment. It mimics the
 * behavior of a legitimate member attempting to update a bogus comment (e.g.,
 * mistyped or maliciously altered ID), and expects a clear error (not found)
 * response.
 *
 * Steps:
 *
 * 1. Register a new member (with unique display name and email)
 * 2. Attempt to update a comment using a random, non-existent UUID and a valid
 *    update body
 * 3. Confirm that the system responds with an error to signify the target comment
 *    does not exist (expected: not found).
 */
export async function test_api_discussionBoard_member_comments_test_update_nonexistent_comment(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(24),
      },
    },
  );
  typia.assert(member);

  // 2. Attempt to update a non-existent comment (random UUID)
  await TestValidator.error("should return not found error")(() =>
    api.functional.discussionBoard.member.comments.update(connection, {
      commentId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        body: RandomGenerator.paragraph()(),
        parent_id: null,
      },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Validate that updating a comment with an invalid body fails as expected.
 *
 * This test ensures that the discussion board comments API enforces required
 * business rules for editing comments. Specifically, it covers failure
 * scenarios where the comment body is set to `null`, an empty string, or
 * whitespace-only string. For each invalid value, the system must return a
 * validation error indicating the body is required and must not be empty.
 *
 * Steps:
 *
 * 1. Register a new member to serve as the comment author.
 * 2. Create a discussion post as this member.
 * 3. Create an initial valid comment on the post as this member.
 * 4. Attempt to update the comment body to each invalid value:
 *
 *    - Body: null
 *    - Body: ""
 *    - Body: " " In each case, assert that the operation fails with a validation
 *         error (using TestValidator.error) and that no update occurs.
 *
 * Business context: Only valid, non-empty bodies should be allowed for
 * comments. Validation is critical for content moderation and data integrity.
 */
export async function test_api_discussionBoard_member_comments_test_update_comment_with_invalid_body(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(32);
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a post as this member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(4),
        body: RandomGenerator.content()(8)(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Create a valid comment on the post
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        body: RandomGenerator.content()(4)(),
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 4. Attempt to update the comment body to each invalid value
  const invalidBodies: (string | null)[] = [null, "", "   "];
  for (const invalidBody of invalidBodies) {
    await TestValidator.error(
      `updating comment with invalid body (${JSON.stringify(invalidBody)})`,
    )(async () => {
      await api.functional.discussionBoard.member.comments.update(connection, {
        commentId: comment.id,
        body: { body: invalidBody } satisfies IDiscussionBoardComment.IUpdate,
      });
    });
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Validate that a moderator can update a comment's body or parent, regardless
 * of original author.
 *
 * This test ensures a moderator's permissions allow them to edit any comment.
 * The scenario verifies:
 *
 * 1. Moderator can update a comment even if not its author.
 * 2. After update, the new body and/or parent_id are persisted and retrievable.
 *
 * Step-by-step process:
 *
 * 1. Register a normal discussion board member (to be comment author).
 * 2. Register a moderator account (independent user/role).
 * 3. As member, create a new post.
 * 4. As member, create a comment on the post.
 * 5. As moderator, update the comment's body (and optionally parent_id).
 * 6. Validate: updated fields match input, author ID remains unchanged, ids/thread
 *    linkage are intact, and audit timestamps make sense.
 */
export async function test_api_discussionBoard_test_update_comment_as_moderator(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member (comment author):
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(32);
  const memberDisplayName = RandomGenerator.alphaNumeric(12);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      },
    },
  );
  typia.assert(member);

  // 2. Register a moderator account:
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPasswordHash = RandomGenerator.alphaNumeric(32);
  const moderatorUsername = RandomGenerator.alphaNumeric(10);
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: moderatorUsername,
        password_hash: moderatorPasswordHash,
        email: moderatorEmail,
        is_active: true,
      },
    });
  typia.assert(moderator);

  // 3. As member, create a new post:
  const postTitle = RandomGenerator.paragraph()(1, 2);
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: postTitle,
        body: postBody,
      },
    },
  );
  typia.assert(post);

  // 4. As member, create a comment on that post:
  const commentBody = RandomGenerator.content()()();
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        body: commentBody,
      },
    },
  );
  typia.assert(comment);

  // 5. As moderator, update the comment's body (and optionally parent_id):
  const updatedBody = RandomGenerator.content()()();
  const updateInput = {
    body: updatedBody,
  } satisfies IDiscussionBoardComment.IUpdate;
  const updated =
    await api.functional.discussionBoard.moderator.comments.update(connection, {
      commentId: comment.id,
      body: updateInput,
    });
  typia.assert(updated);

  // 6. Validate critical invariants:
  TestValidator.equals("comment id unchanged")(updated.id)(comment.id);
  TestValidator.equals("post id unchanged")(updated.discussion_board_post_id)(
    comment.discussion_board_post_id,
  );
  TestValidator.equals("author id unchanged")(
    updated.discussion_board_member_id,
  )(comment.discussion_board_member_id);
  TestValidator.equals("updated body")(updated.body)(updatedBody);
  TestValidator.equals("parent_id unchanged or correct")(updated.parent_id)(
    comment.parent_id,
  );
  TestValidator.predicate("updated_at >= created_at")(
    new Date(updated.updated_at) >= new Date(updated.created_at),
  );
}

