import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Validate that an administrator can update any comment on the board.
 *
 * This test ensures that admin privileges allow updating a comment's body
 * and/or parent, regardless of original author. The flow requires both member
 * (comment author) and admin users.
 *
 * Steps:
 *
 * 1. Register a member account (the comment author)
 * 2. Register an admin account (the updater)
 * 3. Create a post as the member
 * 4. Create a comment on the post as the member
 * 5. Switch identity to the admin
 * 6. As admin, update the comment's body and (optionally) parent_id
 * 7. Fetch the updated comment and assert the fields were changed as intended
 */
export async function test_api_discussionBoard_test_update_comment_as_admin(
  connection: api.IConnection,
) {
  // 1. Register a member (author of the comment)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(10),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);

  // 2. Register an admin (who will update the comment)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        username: RandomGenerator.name(),
        email: adminEmail,
        password_hash: RandomGenerator.alphaNumeric(12),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(admin);

  // 3. Member creates a post
  const postTitle = RandomGenerator.paragraph()();
  const postBody = RandomGenerator.content()()();
  const post: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: postTitle,
        body: postBody,
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post);

  // 4. Member creates a comment on the post
  const commentBody = RandomGenerator.paragraph()();
  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.comments.create(connection, {
      body: {
        discussion_board_post_id: post.id,
        body: commentBody,
      } satisfies IDiscussionBoardComment.ICreate,
    });
  typia.assert(comment);

  // 5. (Role switch/assume admin context if needed)
  // (Assumed handled by session or token mechanism.)

  // 6. As admin, update the comment (body and set parent_id to null)
  const updatedBody = RandomGenerator.paragraph()();
  const updatePayload: IDiscussionBoardComment.IUpdate = {
    body: updatedBody,
    parent_id: null,
  };
  const updated: IDiscussionBoardComment =
    await api.functional.discussionBoard.admin.comments.update(connection, {
      commentId: comment.id,
      body: updatePayload,
    });
  typia.assert(updated);

  // 7. Assert the fields were updated
