 * Business rationale:
 *
 * - Ensures the search endpoint does not error and returns a valid empty
 *   structure when nothing matches filters (a common admin scenario).
 * - Prevents regression where searching with random or unknown filters mistakenly
 *   causes partial results or errors.
 *
 * Steps:
 *
 * 1. Create a unique category via the admin endpoint
 * 2. Create a unique tag via the admin endpoint
 * 3. Assign the tag to the category to ensure at least one assignment exists
 * 4. Search by non-existent (random) category and tag IDs, guaranteeing no match
 * 5. Validate the response's data array is empty, total record count is zero, and
 *    pagination structure is valid (current=1, pages=0 or 1)
 */
export async function test_api_discussionBoard_admin_categoryTags_test_search_category_tag_assignments_with_no_results(
  connection: api.IConnection,
) {
  // 1. Create a unique category
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: `Category-${RandomGenerator.alphabets(8)}`,
        description: RandomGenerator.paragraph()(),
