import type { IPageIDiscussionBoardCategoryTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategoryTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate an authenticated member's ability to search and paginate
 * category-tag assignments for a given valid category.
 *
 * This test covers end-to-end workflow from data preparation to validation of
 * expected business logic:
 *
 * 1. Register a member account that will act as the authenticated user.
 * 2. Create a category for assignments.
 * 3. Create multiple tags to assign.
 * 4. Assign multiple tags to the created category via category-tag assignments
 *    (admin action).
 * 5. As the member, search for category-tag assignments for this category using
 *    the member endpoint.
 * 6. Validate that all assignments for the given category are returned and no
 *    unrelated assignments are present.
 * 7. Paginate the results by limiting the number per page and validating
 *    pagination correctness.
 * 8. Also test that searching for an unassigned category ID returns an empty
 *    result set.
 */
export async function test_api_discussionBoard_test_search_category_tag_assignments_as_member_with_valid_category(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a category (admin privilege required)
  const category = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 3. Create several tags
  const tagsArr = await ArrayUtil.asyncRepeat(5)(async () => {
    const tag = await api.functional.discussionBoard.admin.tags.create(
      connection,
      {
        body: {
          label: RandomGenerator.alphabets(10),
          description: RandomGenerator.paragraph()(),
          color: "#" + RandomGenerator.alphaNumeric(6).toLowerCase(),
        } satisfies IDiscussionBoardTag.ICreate,
      },
    );
    typia.assert(tag);
    return tag;
  });

  // 4. Assign each tag to the created category
  const assignments = await ArrayUtil.asyncMap(tagsArr)(async (tag) => {
    const assignment =
      await api.functional.discussionBoard.admin.categoryTags.create(
        connection,
        {
          body: {
            discussion_board_category_id: category.id,
            discussion_board_tag_id: tag.id,
          } satisfies IDiscussionBoardCategoryTag.ICreate,
        },
      );
    typia.assert(assignment);
    return assignment;
  });

  // 5. Search as the member for tag assignments for the category - get all assignments
  const allAssignmentsResult =
    await api.functional.discussionBoard.member.categoryTags.search(
      connection,
      {
        body: {
          discussion_board_category_id: category.id,
        } satisfies IDiscussionBoardCategoryTag.IRequest,
      },
    );
  typia.assert(allAssignmentsResult);
  TestValidator.equals("all assignments count")(
    allAssignmentsResult.data.length,
  )(assignments.length);
  // All returned belong to the right category
  allAssignmentsResult.data.forEach((a) =>
    TestValidator.equals("correct category")(a.discussion_board_category_id)(
      category.id,
    ),
  );
  // Only the created assignments are present
  const assignmentIds = assignments.map((a) => a.id);
  allAssignmentsResult.data.forEach((a) =>
    TestValidator.predicate("response contains expected assignment id")(
      assignmentIds.includes(a.id),
    ),
  );

  // 6. Paginate: request with limit 2, validate total records, pages, correct page splitting
  const page1 = await api.functional.discussionBoard.member.categoryTags.search(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        page: 1,
        limit: 2,
      } satisfies IDiscussionBoardCategoryTag.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals("page 1 current")(page1.pagination.current)(1);
  TestValidator.equals("page 1 limit")(page1.pagination.limit)(2);
  TestValidator.equals("total records")(page1.pagination.records)(
    assignments.length,
  );
  TestValidator.equals("total pages")(page1.pagination.pages)(
    Math.ceil(assignments.length / 2),
  );
  TestValidator.equals("first page size")(page1.data.length)(
    Math.min(2, assignments.length),
  );

  if (assignments.length > 2) {
    const page2 =
      await api.functional.discussionBoard.member.categoryTags.search(
        connection,
        {
          body: {
            discussion_board_category_id: category.id,
            page: 2,
            limit: 2,
          } satisfies IDiscussionBoardCategoryTag.IRequest,
        },
      );
    typia.assert(page2);
    TestValidator.equals("page 2 current")(page2.pagination.current)(2);
    TestValidator.equals("page 2 limit")(page2.pagination.limit)(2);
    TestValidator.equals("total records")(page2.pagination.records)(
      assignments.length,
    );
    // Total pages asserted earlier
    // Validate non-overlapping ids between page 1 and page 2
    const ids1 = page1.data.map((a) => a.id);
    const ids2 = page2.data.map((a) => a.id);
    ids2.forEach((id) =>
      TestValidator.predicate("no overlap between page 1 and 2")(
        !ids1.includes(id),
      ),
    );
  }

  // 7. Searching with a random unassigned category returns an empty list
  const randomUnassignedCategoryId = typia.random<
    string & tags.Format<"uuid">
  >();
  const emptyResult =
    await api.functional.discussionBoard.member.categoryTags.search(
      connection,
      {
        body: {
          discussion_board_category_id: randomUnassignedCategoryId,
        } satisfies IDiscussionBoardCategoryTag.IRequest,
      },
    );
  typia.assert(emptyResult);
  TestValidator.equals("empty result for unassigned category")(
    emptyResult.data.length,
  )(0);
}

