 * 3. Check the API response to confirm the changes are reflected in the updated
 *    object (specifically the new status and end time).
 */
export async function test_api_discussionBoard_admin_suspensions_test_update_suspension_status_and_end_time_as_admin(
  connection: api.IConnection,
) {
