import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSuspension";

/**
 * Test updating a suspension with invalid or forbidden fields and values.
 *
 * This test ensures that only the fields allowed by the schema (ends_at,
 * reason, status) are mutable for discussion board suspension records. It also
 * validates that attempts to update these fields with invalid values are
 * properly rejected, and that immutable fields (such as actor or subject
 * references) cannot be updated due to SDK/type safety constraints.
 *
 * Steps performed:
 *
 * 1. Create a valid suspension record using required fields.
 * 2. Update with allowed fields using valid values (should succeed and update
 *    values as intended).
 * 3. Attempt invalid updates for each updatable field: a. Set 'status' to an
 *    invalid enum value (should throw an error). b. Set 'reason' to null
 *    (should throw an error if not accepted). c. Set 'ends_at' to an invalid
 *    format (should throw an error if not ISO date/time or null-allowed).
 * 4. Each invalid update must throw an error.
 * 5. Confirm after failed updates that the (successful) prior update remains, and
 *    immutable fields are unchanged (where visible).
 *
 * Note: Because the SDK/typescript prevents updating immutable fields (such as
 * the actor and subject fields), this is inherently type-safe and cannot be
 * bypassed within E2E code. The test confirms that only allowed updates are
 * accepted, as per the update DTO definition and business rules.
 */
export async function test_api_discussionBoard_admin_suspensions_test_update_suspension_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid suspension record
  const createInput: IDiscussionBoardSuspension.ICreate = {
    // randomly choose a subject type and actor for variety (e.g., suspended_member_id & admin_id only)
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    suspended_admin_id: null,
    suspended_moderator_id: null,
    suspended_guest_id: null,
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    moderator_id: null,
    related_report_id: null,
    related_action_id: null,
    suspended_at: new Date().toISOString(),
    ends_at: null,
    reason: "Initial suspension reason.",
    status: "active",
  };
  const suspension =
    await api.functional.discussionBoard.admin.suspensions.create(connection, {
      body: createInput,
    });
  typia.assert(suspension);

  // 2. Valid update: update reason and status
  const updatedReason = "Updated for audit/compliance.";
  const updatedStatus = "revoked";
  const validUpdateInput: IDiscussionBoardSuspension.IUpdate = {
    reason: updatedReason,
    status: updatedStatus,
    ends_at: null,
  };
  const updated = await api.functional.discussionBoard.admin.suspensions.update(
    connection,
    {
      suspensionId: suspension.id,
      body: validUpdateInput,
    },
  );
  typia.assert(updated);
  // Success assertion
  TestValidator.equals("reason updated")(updated.reason)(updatedReason);
  TestValidator.equals("status updated")(updated.status)(updatedStatus);
  TestValidator.equals("id unchanged")(updated.id)(suspension.id);
  TestValidator.equals("member id unchanged")(updated.suspended_member_id)(
    suspension.suspended_member_id,
  );
  TestValidator.equals("admin id unchanged")(updated.admin_id)(
    suspension.admin_id,
  );

  // 3a. Invalid update: status set to an invalid enum value (should error)
  await TestValidator.error("status invalid value throws error")(() =>
    api.functional.discussionBoard.admin.suspensions.update(connection, {
      suspensionId: suspension.id,
      body: {
        status: "terminated" as any, // not in allowed enum
        reason: "Test invalid status",
      } as IDiscussionBoardSuspension.IUpdate,
    }),
  );

  // 3b. Invalid update: reason as null (nullable in type, but check business logic enforcement)
  await TestValidator.error("reason as null should throw if forbidden")(() =>
    api.functional.discussionBoard.admin.suspensions.update(connection, {
      suspensionId: suspension.id,
      body: {
        reason: null,
        status: "active",
      },
    }),
  );

  // 3c. Invalid update: ends_at badly formatted (not an ISO date/time or null)
  await TestValidator.error("ends_at invalid format should throw")(() =>
    api.functional.discussionBoard.admin.suspensions.update(connection, {
      suspensionId: suspension.id,
      body: {
        ends_at: "not-a-date",
        reason: "Valid reason",
        status: "active",
      },
    }),
  );

  // 4. Confirm suspension unchanged for immutable fields (id, subject, actor)
  const after = await api.functional.discussionBoard.admin.suspensions.update(
    connection,
    {
      suspensionId: suspension.id,
      body: {
        reason: "Final valid change.",
        status: "expired",
      },
    },
  );
  typia.assert(after);
  TestValidator.equals("id unchanged")(after.id)(suspension.id);
  TestValidator.equals("member id immutable")(after.suspended_member_id)(
    suspension.suspended_member_id,
  );
  TestValidator.equals("admin id immutable")(after.admin_id)(
    suspension.admin_id,
  );
}

