 *
 * The end-to-end scenario for testing this is as follows:
 *
 * 1. Register a standard member (user).
 * 2. The member creates a new post.
 * 3. The member adds a comment to their own post.
 * 4. Register a moderator (distinct from the member).
 * 5. As the moderator, perform an update operation on the member's comment,
 *    changing its body text.
 * 6. Validate that the comment's body has been updated (reflecting the new value),
 *    that the updated_at timestamp is changed, and that no
 *    validation/permission error occurs.
 * 7. Confirm that update did not affect other core IDs or reference attributes
 *    (author, post ID).
 */
export async function test_api_discussionBoard_test_moderator_can_update_any_comment_in_post(
  connection: api.IConnection,
) {
