import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Validate that a moderator cannot soft-delete a comment that is already
 * soft-deleted, and the system returns an appropriate error without changing
 * the comment's state.
 *
 * Business context: Only moderators (or the owning user/admin) may erase
 * comments, and the erase operation is a soft-delete (sets deleted_at). If the
 * comment is already soft-deleted (deleted_at is set), a subsequent soft-delete
 * attempt should result in an error—typically not found or already deleted—with
 * no side effects on the comment.
 *
 * Test process:
 *
 * 1. Register a new member who will author posts/comments
 * 2. As that member, create a discussion board post
 * 3. As that member, create a comment on the post
 * 4. Register a moderator account that has permission to erase comments
 * 5. As the moderator, soft-delete the comment
 * 6. Immediately attempt to soft-delete the same comment again (should error)
 * 7. (Optionally) Confirm that the comment's deleted_at timestamp has not been
 *    altered or reset by the second delete attempt if such an API is
 *    available.
 *
 * - The second delete attempt must result in an error (TestValidator.error), not
 *   success.
 * - The error should be Not Found or Already Deleted (though we cannot check
 *   exact message/type per guidelines).
 */
export async function test_api_discussionBoard_test_moderator_delete_already_deleted_comment_returns_error(
  connection: api.IConnection,
) {
  // 1. Register member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash: string = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.alphaNumeric(8),
        email: memberEmail,
        password_hash: memberPasswordHash,
      },
    },
  );
  typia.assert(member);

  // 2. Create a post as the member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 3. Create a comment as the member
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: RandomGenerator.paragraph()(1),
        },
      },
    );
  typia.assert(comment);

  // 4. Register a moderator (by admin)
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: moderatorEmail,
        password_hash: RandomGenerator.alphaNumeric(32),
        is_active: true,
      },
    });
  typia.assert(moderator);
  // Role switch to moderator is not possible; assume correct context by invocation

  // 5. First soft-delete: moderator erases the comment
  await api.functional.discussionBoard.moderator.posts.comments.erase(
    connection,
    {
      postId: post.id,
      commentId: comment.id,
    },
  );

  // 6. Second soft-delete attempt: expect error
  await TestValidator.error("Cannot erase already-soft-deleted comment")(
    async () => {
      await api.functional.discussionBoard.moderator.posts.comments.erase(
        connection,
        {
          postId: post.id,
          commentId: comment.id,
        },
      );
    },
  );
  // 7. No comment read API available, cannot re-validate deleted_at
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Validates that an authenticated member can cast both upvote and downvote on a
 * discussion board post, adheres to the one-vote-per-post-per-member (upsert)
 * policy, and that the vote is properly associated to the post and member.
 *
 * Business context: The discussion board voting system allows authenticated
 * members to vote on posts (one per post). Voting twice should update the prior
 * vote (upsert behavior).
 *
 * Test steps:
 *
 * 1. Register a new discussion board member account (using valid display name,
 *    unique email, and a password hash).
 * 2. (Assume member is now authenticated / session established for the following
 *    steps.)
 * 3. Member creates a new post (title and body required).
 * 4. Member casts an upvote (upvote: true) on the created post. Verify response:
 *    upvote==true, member & post association correct, and correct
 *    types/formats.
 * 5. Member then casts a downvote (upvote: false) on the same post. Verify that
 *    the response has upvote==false and the returned vote record is for the
 *    same (post, member) as before. This proves upsert logic: casting a new
 *    vote changes the prior.
 * 6. Optionally, verify by casting the same upvote again: should update again and
 *    not error. (Demonstrate idempotent upsert behavior.)
 */
export async function test_api_discussionBoard_test_create_post_vote_as_member_success(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const email: string = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. (Authentication assumed / session established; proceed as the member for all steps)

  // 3. Member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. Upvote the post
  const upvote =
    await api.functional.discussionBoard.member.posts.postVotes.create(
      connection,
      {
        postId: post.id,
        body: { upvote: true } satisfies IDiscussionBoardPostVote.ICreate,
      },
    );
  typia.assert(upvote);
  TestValidator.equals("upvote record points to post")(
    upvote.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("upvote record points to member")(
    upvote.discussion_board_member_id,
  )(member.id);
  TestValidator.equals("vote is upvote")(upvote.upvote)(true);

  // 5. Downvote the same post and verify upsert/update effect
  const downvote =
    await api.functional.discussionBoard.member.posts.postVotes.create(
      connection,
      {
        postId: post.id,
        body: { upvote: false } satisfies IDiscussionBoardPostVote.ICreate,
      },
    );
  typia.assert(downvote);
  TestValidator.equals("downvote record points to post")(
    downvote.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("downvote record points to member")(
    downvote.discussion_board_member_id,
  )(member.id);
  TestValidator.equals("vote is downvote")(downvote.upvote)(false);
  TestValidator.equals("upsert: same vote id reused or replaced")(downvote.id)(
    upvote.id,
  );

  // 6. Optionally, cast upvote again to reconfirm upsert/idempotent update
  const upvote2 =
    await api.functional.discussionBoard.member.posts.postVotes.create(
      connection,
      {
        postId: post.id,
        body: { upvote: true } satisfies IDiscussionBoardPostVote.ICreate,
      },
    );
  typia.assert(upvote2);
  TestValidator.equals("upvote idempotent: record points to post")(
    upvote2.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("upvote idempotent: record points to member")(
    upvote2.discussion_board_member_id,
  )(member.id);
  TestValidator.equals("upvote idempotent: upvote true")(upvote2.upvote)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Validate enforcement of authentication (RBAC) for voting on discussion board
 * posts.
 *
 * This test ensures that a guest or unauthenticated client is properly denied
 * when attempting to add an upvote or downvote to an existing discussion post,
 * enforcing that only authenticated members can vote.
 *
 * Step-by-step process:
 *
 * 1. Create a discussion board post as an authenticated member, and capture its
 *    ID.
 * 2. Simulate a guest/unauthenticated client by removing the Authorization header
 *    from the API connection object.
 * 3. Attempt to vote on the post (upvote) as a guest using the vote creation
 *    endpoint.
 * 4. Assert that the request is rejected due to a lack of authentication (throws
 *    authorization error), confirming RBAC enforcement.
 */
export async function test_api_discussionBoard_test_create_post_vote_unauthenticated_fail(
  connection: api.IConnection,
) {
  // 1. Create a discussion board post as an authenticated member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Prepare a guest connection by stripping the Authorization header
  const guestConnection: api.IConnection = {
    ...connection,
    headers:
      connection.headers && typeof connection.headers === "object"
        ? Object.fromEntries(
            Object.entries(connection.headers).filter(
              ([key]) => key.toLowerCase() !== "authorization",
            ),
          )
        : undefined,
  };

  // 3. Attempt to vote on the post as a guest
  await TestValidator.error("unauthenticated guest cannot vote on post")(
    async () => {
      await api.functional.discussionBoard.member.posts.postVotes.create(
        guestConnection,
        {
          postId: post.id,
          body: {
            upvote: true,
          } satisfies IDiscussionBoardPostVote.ICreate,
        },
      );
    },
  );
}

