import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Test that a member can update their own post vote (upvote/downvote) on a
 * specific post.
 *
 * This test covers the workflow where a discussion board member creates an
 * account, posts a new discussion, casts an initial vote (e.g., upvote) on that
 * post, then updates that vote to the opposite value (e.g., downvote). The test
 * ensures the update is successful and the vote record reflects the changed
 * value, while all audit and ownership constraints are preserved.
 *
 * Steps:
 *
 * 1. Register a new member (to own the vote).
 * 2. Create a post by that member.
 * 3. The member casts an initial upvote.
 * 4. The member updates that vote to a downvote.
 * 5. Validate that the vote record was updated, vote type has changed,
 *    associations remain valid, and audit fields comply.
 */
export async function test_api_discussionBoard_test_update_own_post_vote_success(
  connection: api.IConnection,
) {
  // 1. Register a new member for the test
  const memberCreate: IDiscussionBoardMember.ICreate = {
    display_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
  };
  const member = await api.functional.discussionBoard.members.create(
    connection,
    { body: memberCreate },
  );
  typia.assert(member);

  // 2. Create a post as that member
  // (Assumption: Auth context for post creation is managed externally or implied by connection)
  const postCreate: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    parent_id: null,
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    { body: postCreate },
  );
  typia.assert(post);

  // 3. Cast an initial upvote as the member
  const initialVoteInput: IDiscussionBoardPostVote.ICreate = { upvote: true };
  const initialVote =
    await api.functional.discussionBoard.member.posts.postVotes.create(
      connection,
      {
        postId: post.id,
        body: initialVoteInput,
      },
    );
  typia.assert(initialVote);

  // 4. Update that vote to the opposite (downvote)
  const updateVoteInput: IDiscussionBoardPostVote.IUpdate = { upvote: false };
  const updatedVote =
    await api.functional.discussionBoard.member.posts.postVotes.update(
      connection,
      {
        postId: post.id,
        postVoteId: initialVote.id,
        body: updateVoteInput,
      },
    );
  typia.assert(updatedVote);

  // 5. Validate updated vote record
  // a. ID remains the same
  TestValidator.equals("vote id")(updatedVote.id)(initialVote.id);
  // b. Vote type changed
  TestValidator.equals("vote changed to downvote")(updatedVote.upvote)(false);
  TestValidator.notEquals("vote value should differ after update")(
    updatedVote.upvote,
  )(initialVote.upvote);
  // c. Association remains (post & member)
  TestValidator.equals("post id remains")(updatedVote.discussion_board_post_id)(
    post.id,
  );
  TestValidator.equals("member id remains")(
    updatedVote.discussion_board_member_id,
  )(member.id);
  // d. Audit: created_at is present and unchanged (since updating does not always alter creation time for votes)
  TestValidator.equals("created_at unchanged")(updatedVote.created_at)(
    initialVote.created_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
