/**
 * Test denying unauthorized post vote updates by non-owners.
 *
 * This test ensures that a discussion board member cannot update another
 * member's vote. It does so by:
 *
 * 1. Registering two members: voterA (who will cast a vote) and voterB (who will
 *    attempt unauthorized update)
 * 2. Create a post with voterA
 * 3. VoterA casts a vote
 * 4. Switch to voterB (simulated by new registration)
 * 5. VoterB attempts to update voterA's vote (expecting authorization error)
 * 6. Assert the update is denied and the vote is not changed
 */
export async function test_api_discussionBoard_test_update_post_vote_unauthorized_fail(
  connection: api.IConnection,
) {
  // 1. Register two members: voterA (owner of vote) and voterB (unauthorized)
  const voterAEmail = typia.random<string & tags.Format<"email">>();
  const voterAPassword = RandomGenerator.alphaNumeric(12);
  const voterA = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: voterAEmail,
        password_hash: voterAPassword,
      },
    },
  );
  typia.assert(voterA);

  const voterBEmail = typia.random<string & tags.Format<"email">>();
  const voterBPassword = RandomGenerator.alphaNumeric(12);
  const voterB = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: voterBEmail,
        password_hash: voterBPassword,
      },
    },
  );
  typia.assert(voterB);

  // 2. (Assume voterA is "logged in" upon registration.)
  //    Create a new post as voterA
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(6),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 3. voterA casts a vote
  const vote =
    await api.functional.discussionBoard.member.posts.postVotes.create(
      connection,
      {
        postId: post.id,
        body: { upvote: true },
      },
    );
  typia.assert(vote);

  // 4. Switch to voterB context (simulated as separate member, connection is managed)
  //    No separate auth API, so member registration implies authentication context
  //    Continue as voterB (connection is authenticated as voterB now)

  // 5. Attempt unauthorized vote update as voterB. This should be rejected by the API.
  await TestValidator.error("unauthorized vote update must fail")(() =>
    api.functional.discussionBoard.member.posts.postVotes.update(connection, {
      postId: post.id,
      postVoteId: vote.id,
      body: { upvote: false },
    }),
  );
}

