/**
 * Test creation of a new moderator with valid, unique input data through the
 * admin endpoint.
 *
 * This test ensures that an admin can create a new moderator account by
 * supplying all required fields: username, password_hash, email, is_active, and
 * (optionally) promoted_by_admin_id. The provided data must be unique (no
 * clashes with existing moderators), and the email format must be valid.
 *
 * The function will:
 *
 * 1. Prepare unique moderator credentials (username, email, password hash).
 * 2. Send a POST request to create the moderator (as the admin).
 * 3. Confirm the response is successful and that the moderator was created.
 * 4. Check that all response fields (except for password_hash) match the input,
 *    and response omits sensitive data.
 * 5. Optionally verify that audit-related fields (created_at, updated_at,
 *    promoted_by_admin_id) are present and correct.
 * 6. (If supported) validate that audit logs have correctly recorded this action.
 *
 * Edge cases (like duplicate email or username) are covered in separate tests.
 * Here we focus strictly on the happy path for properly formed, unique input
 * values.
 */
export async function test_api_discussionBoard_admin_moderators_test_create_moderator_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare moderator creation input (all required fields, unique values)
  const moderatorInput = {
    username: RandomGenerator.alphaNumeric(12),
    password_hash: RandomGenerator.alphaNumeric(60), // simulate 60-char hash
    email: typia.random<string & tags.Format<"email">>(),
    is_active: true,
    // Optionally add promoter ID, but for minimal case can omit
  } satisfies IDiscussionBoardModerator.ICreate;

