  const createdModerator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: moderatorInput,
    });
  typia.assert(createdModerator);

  // 3. Validate core response fields
  TestValidator.equals("username matches")(createdModerator.username)(
    moderatorInput.username,
  );
  TestValidator.equals("email matches")(createdModerator.email)(
    moderatorInput.email,
  );
  TestValidator.equals("is_active matches")(createdModerator.is_active)(
    moderatorInput.is_active,
  );
  // 4. Confirm password_hash is not present on output
  if ((createdModerator as any).password_hash !== undefined)
    throw new Error("Response contains sensitive password_hash field");
  // 5. Validate audit fields present & correctly formatted
  TestValidator.predicate("Has valid id")(
    typeof createdModerator.id === "string" && createdModerator.id.length > 0,
  );
  TestValidator.predicate("Valid created_at")(
    typeof createdModerator.created_at === "string" &&
      !isNaN(Date.parse(createdModerator.created_at)),
  );
  TestValidator.predicate("Valid updated_at")(
    typeof createdModerator.updated_at === "string" &&
      !isNaN(Date.parse(createdModerator.updated_at)),
  );
  // 6. (Optional) Promoted_by_admin_id may be undefined or a uuid
  if (
    createdModerator.promoted_by_admin_id !== undefined &&
    createdModerator.promoted_by_admin_id !== null
  ) {
    TestValidator.predicate("promoted_by_admin_id is uuid")(
      typeof createdModerator.promoted_by_admin_id === "string" &&
        createdModerator.promoted_by_admin_id.length > 0,
    );
  }
  // 7. (Optional) Audit log validation would be possible with a secondary API; not covered here.
}

