 *
 * This E2E test validates that an admin can successfully update a moderator
 * account via the admin API. It covers:
 *
 * 1. Creating a new moderator (so we have a known moderatorId to update).
 * 2. Updating mutable fields (email, is_active, promoted_by_admin_id) via the
 *    "update" endpoint.
 * 3. Verifying those fields are reflected in the returned moderator object.
 * 4. Ensuring unmodified fields (id, username) remain unchanged.
 *
 * Steps:
 *
 * 1. Create a moderator using
 *    api.functional.discussionBoard.admin.moderators.create.
 * 2. Prepare valid updated values for mutable fields.
 * 3. Update that moderator by UUID with those fields using
 *    api.functional.discussionBoard.admin.moderators.update.
 * 4. Assert that all changed fields reflect the correct new values.
 * 5. Assert that non-updated fields (id, username) match the original values.
 *
 * Note: Audit/compliance logging could be checked if such endpoint existed; not
 * possible in this scenario.
 */
export async function test_api_discussionBoard_admin_moderators_test_update_moderator_details_success(
  connection: api.IConnection,
) {
  // 1. Create a moderator to update
  const createInput: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    password_hash: RandomGenerator.alphaNumeric(30),
    email: typia.random<string & tags.Format<"email">>(),
    is_active: true,
    // promoted_by_admin_id can be omitted if not used
  };
  const created: IDiscussionBoardModerator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Prepare updated values for mutable fields
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newActive = false;
  const newPromotedId = typia.random<string & tags.Format<"uuid">>();

  // 3. Update the moderator using new values
  const updateInput: IDiscussionBoardModerator.IUpdate = {
    email: newEmail,
    is_active: newActive,
    promoted_by_admin_id: newPromotedId,
  };
  const updated: IDiscussionBoardModerator =
    await api.functional.discussionBoard.admin.moderators.update(connection, {
      moderatorId: created.id,
      body: updateInput,
    });
  typia.assert(updated);

  // 4. Verify updated fields reflect the change
  TestValidator.equals("email is updated")(updated.email)(newEmail);
  TestValidator.equals("is_active is updated")(updated.is_active)(newActive);
  TestValidator.equals("promoted_by_admin_id is updated")(
    updated.promoted_by_admin_id,
  )(newPromotedId);

  // 5. Non-updated fields remain stable
  TestValidator.equals("id remains unchanged")(updated.id)(created.id);
  TestValidator.equals("username remains unchanged")(updated.username)(
    created.username,
  );
  // Do not verify created_at/updated_at since updated_at may update
}

