    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(12),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(adminB);

  // 2. List admins before deletion, ensure both A and B are found
  const adminListBefore =
    await api.functional.discussionBoard.admin.admins.index(connection);
  typia.assert(adminListBefore);
  TestValidator.predicate("admin A found before deletion")(
    adminListBefore.data.some((a) => a.id === adminA.id),
  );
  TestValidator.predicate("admin B found before deletion")(
    adminListBefore.data.some((a) => a.id === adminB.id),
  );

  // 3. Delete admin A (simulated context: always-privileged)
  await api.functional.discussionBoard.admin.admins.erase(connection, {
    adminId: adminA.id,
  });

  // 4. List admins after deletion and check status
  const adminListAfter =
    await api.functional.discussionBoard.admin.admins.index(connection);
