  const adminAafter = adminListAfter.data.find((a) => a.id === adminA.id);
  TestValidator.predicate(
    "admin A should be deleted or inactive after deletion",
  )(adminAafter === undefined || adminAafter.is_active === false);

  // 5. Prevent self-delete: try to delete self (admin B), expect error
  await TestValidator.error("admin cannot delete self")(() =>
    api.functional.discussionBoard.admin.admins.erase(connection, {
      adminId: adminB.id,
    }),
  );
}

