/**
 * Test deletion attempt on a non-existent adminId.
 *
 * This test ensures that when attempting to delete an administrator using an
 * adminId (UUID) that does not exist in the system, the API responds with a not
 * found error, and that the admin list remains unchanged. It does not (and
 * cannot) check audit logs, as no API is provided for this.
 *
 * Steps:
 *
 * 1. Retrieve the list of all current admins and collect their UUIDs.
 * 2. Generate a random UUID that does not exist in the system.
 * 3. Attempt to delete that adminId and confirm that an error is thrown.
 * 4. Fetch the admin list again and verify that it is unchanged.
 */
export async function test_api_discussionBoard_admin_admins_test_delete_admin_not_found(
  connection: api.IConnection,
) {
  // 1. Retrieve and hold the current admin list
  const firstAdminPage =
    await api.functional.discussionBoard.admin.admins.index(connection);
  typia.assert(firstAdminPage);
  const existingAdminIds = new Set(
    firstAdminPage.data.map((admin) => admin.id),
  );

  // 2. Generate a UUID not found in the current admin list
  let fakeAdminId: string & tags.Format<"uuid">;
  do {
    fakeAdminId = typia.random<string & tags.Format<"uuid">>();
  } while (existingAdminIds.has(fakeAdminId));

  // 3. Attempt to delete the non-existent admin and expect an error
  await TestValidator.error("delete should fail for nonexistent adminId")(
