  const postAttemptAdminPage =
    await api.functional.discussionBoard.admin.admins.index(connection);
  typia.assert(postAttemptAdminPage);
  TestValidator.equals("admin list unchanged after failed delete")(
    postAttemptAdminPage,
  )(firstAdminPage);
