/**
 * Test that deleting an admin without proper authorization fails and no
 * deletion occurs.
 *
 * This test verifies the following business rules:
 *
 * 1. Unauthenticated users (not logged in) cannot delete an admin.
 * 2. Non-admin members, even when authenticated, cannot delete an admin.
 *
 * The test covers these steps:
 *
 * 1. Create a non-admin member (for permission testing).
 * 2. Create an admin (target for deletion). 3a. Attempt to delete the admin as an
 *    unauthenticated (guest) user and expect an authorization error. 3b.
 *    Attempt to delete the admin as a non-admin member and expect an
 *    authorization error. For each attempt, assert that an authorization error
 *    is thrown (TestValidator.error), and that the admin record remains present
 *    (no real deletion occurs).
 *
 * NOTE: Self-deletion as admin is not tested as no admin authentication/login
 * API is provided in the SDK. Only test what is implementable.
 */
export async function test_api_discussionBoard_test_delete_admin_without_authorization(
  connection: api.IConnection,
) {
  // 1. Create a non-admin member
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(15),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create an admin (target)
  const admin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(20),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(admin);

  // 3a. Attempt deletion as unauthenticated (guest) user
  const guestConnection = {
    ...connection,
    headers: { ...connection.headers },
  } as api.IConnection;
  delete guestConnection.headers?.Authorization; // Remove auth to simulate guest
  TestValidator.error("unauthenticated users cannot delete admins")(
    async () => {
      await api.functional.discussionBoard.admin.admins.erase(guestConnection, {
        adminId: admin.id,
      });
    },
  );

  // 3b. Attempt deletion as plain member (should not have admin privileges)
  // (In the absence of a login API, we cannot switch context -- connection remains a non-admin session)
  TestValidator.error("non-admin members cannot delete admins")(async () => {
    await api.functional.discussionBoard.admin.admins.erase(connection, {
      adminId: admin.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";
import type { IPageIDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuthToken";
import type { IDiscussionBoardAuthToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuthToken";

/**
 * Test admin deletion: verify session/token revocation and audit logging.
 *
 * This test ensures that when an admin is deleted via the admin deletion
 * endpoint, all of their sessions/auth tokens are revoked, and the event is
 * properly logged for compliance.
 *
 * Steps:
 *
 * 1. Create a target admin who will be deleted.
 * 2. Create a separate acting admin who performs the deletion.
 * 3. Issue an authentication token/session for the target admin.
 * 4. (Simulate) Use the target admin's active token to attempt to access a
 *    protected API after deletion, expecting access to be denied (simulate by
 *    checking revoked tokens, since there is no login API).
 * 5. Acting admin deletes the target admin by UUID.
 * 6. List all tokens and verify the deleted admin's tokens are revoked (revoked ==
 *    true).
 * 7. List audit log entries and verify a record exists documenting the admin
 *    deletion, with correct action_type and actor_admin_id of the acting
 *    admin.
 */
export async function test_api_discussionBoard_admin_admins_test_delete_admin_audit_and_session_revoke(
  connection: api.IConnection,
) {
  // 1. Create the target admin to be deleted
  const adminToDelete =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        username: `target_${RandomGenerator.alphaNumeric(8)}`,
        email: `${RandomGenerator.alphaNumeric(8)}@company.com`,
        password_hash: RandomGenerator.alphaNumeric(32),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(adminToDelete);

  // 2. Create the acting admin who will perform the deletion
  const actingAdmin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: `actor_${RandomGenerator.alphaNumeric(8)}`,
        email: `${RandomGenerator.alphaNumeric(8)}@company.com`,
        password_hash: RandomGenerator.alphaNumeric(32),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(actingAdmin);

  // 3. Issue an active authentication token for the target admin
  const now = new Date().toISOString();
  const tokenExpiration = new Date(Date.now() + 60 * 60 * 1000).toISOString();
  const issuedToken =
    await api.functional.discussionBoard.admin.authTokens.create(connection, {
      body: {
        admin_id: adminToDelete.id,
        actor_type: "admin",
        token: RandomGenerator.alphaNumeric(64),
        issued_at: now,
        expires_at: tokenExpiration,
      } satisfies IDiscussionBoardAuthToken.ICreate,
    });
  typia.assert(issuedToken);

  // 4. (Simulated) Ensure token is active before deletion by listing all tokens and confirming its presence
  const tokensBefore =
    await api.functional.discussionBoard.admin.authTokens.index(connection);
  typia.assert(tokensBefore);
  const targetTokensBefore = tokensBefore.data.filter(
    (tok) => tok.admin_id === adminToDelete.id && !tok.revoked,
  );
  TestValidator.predicate(
    "target admin's token must be active before deletion",
  )(targetTokensBefore.length > 0);

  // 5. Acting admin deletes the target admin
  await api.functional.discussionBoard.admin.admins.erase(connection, {
    adminId: adminToDelete.id,
  });

  // 6. Ensure after deletion, all of admin's tokens are revoked
  const tokensAfter =
    await api.functional.discussionBoard.admin.authTokens.index(connection);
  typia.assert(tokensAfter);
  const targetTokensAfter = tokensAfter.data.filter(
    (tok) => tok.admin_id === adminToDelete.id,
  );
  TestValidator.predicate("all tokens for deleted admin are revoked")(
    targetTokensAfter.every((tok) => tok.revoked),
  );
  TestValidator.predicate("admin no longer has active tokens")(
    targetTokensAfter.length > 0,
  );

  // 7. Ensure audit log entry documents the deletion event
  const auditLogs =
    await api.functional.discussionBoard.admin.auditLogs.index(connection);
  typia.assert(auditLogs);
  const deletionLog = auditLogs.data.find(
    (log) =>
      log.action_type.includes("delete") &&
      log.actor_admin_id === actingAdmin.id &&
      log.context &&
      log.context.includes(adminToDelete.id),
  );
  TestValidator.predicate("audit log entry is present and correct")(
    !!deletionLog,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
