import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Validate the successful retrieval of all moderator accounts by an admin user.
 *
 * Business Context: Only an admin should be able to list all moderators. The
 * response must not contain any sensitive fields for any moderator. All
 * expected fields—id, username, email, is_active, created_at, updated_at, and
 * promoted_by_admin_id—must be present and correctly populated. Pagination
 * (current, limit, records, pages) must have valid values. All moderator
 * entries returned must have their promoted_by_admin_id reflecting the admin
 * who created them (when applicable).
 *
 * Step-by-step process:
 *
 * 1. Create two distinct moderator accounts using the admin endpoint. Store their
 *    returned data.
 * 2. Issue a GET request to list all moderator accounts as an admin.
 * 3. Assert that the response conforms to IPageIDiscussionBoardModerator and
 *    contains no sensitive fields (i.e., password is NOT present).
 * 4. For each newly created moderator, confirm they appear in the returned data
 *    with correct id, username, email, is_active, and promoted_by_admin_id
 *    fields.
 * 5. Assert that pagination fields have expected types and reasonable values (page
 *    1, limit >= 1, records >= 2, pages >= 1).
 */
export async function test_api_discussionBoard_test_list_moderators_success_for_admin(
  connection: api.IConnection,
) {
  // 1. Create two moderator accounts using the admin create endpoint
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const moderator1Input: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.alphabets(10),
    password_hash: RandomGenerator.alphaNumeric(32),
    email: typia.random<string & tags.Format<"email">>(),
    is_active: true,
    promoted_by_admin_id: adminId,
  };
  const moderator1 =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: moderator1Input,
    });
  typia.assert(moderator1);

  const moderator2Input: IDiscussionBoardModerator.ICreate = {
    username: RandomGenerator.alphabets(10),
    password_hash: RandomGenerator.alphaNumeric(32),
    email: typia.random<string & tags.Format<"email">>(),
    is_active: false,
    promoted_by_admin_id: adminId,
  };
  const moderator2 =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: moderator2Input,
    });
  typia.assert(moderator2);

  // 2. GET all moderators
  const page =
    await api.functional.discussionBoard.admin.moderators.index(connection);
  typia.assert(page);

  // 3. Assert pagination fields are correct
  const { current, limit, records, pages } = page.pagination;
  TestValidator.predicate("valid pagination: current page > 0")(current > 0);
  TestValidator.predicate("valid pagination: limit >=1")(limit >= 1);
  TestValidator.predicate("record count: at least 2 moderators")(records >= 2);
  TestValidator.predicate("page count >= 1")(pages >= 1);

  // 4. Check required fields for each moderator in data array
  for (const mod of page.data) {
    // Sensitive fields (like password_hash) must NOT be present
    TestValidator.predicate("no password_hash field")(
      typeof (mod as any).password_hash === "undefined",
    );
    // Must have all public fields present
    typia.assert<{
      id: string;
      username: string;
      email: string;
      is_active: boolean;
      created_at: string;
      updated_at: string;
      promoted_by_admin_id?: string;
    }>(mod);
  }

  // 5. Check both created moderators are present and their promoter id is correct
  const modsById = new Map(page.data.map((x) => [x.id, x]));
  const found1 = modsById.get(moderator1.id);
  const found2 = modsById.get(moderator2.id);

  TestValidator.predicate("moderator1 appears in GET results")(!!found1);
  TestValidator.equals("moderator1.username")(found1!.username)(
    moderator1Input.username,
  );
  TestValidator.equals("moderator1.email")(found1!.email)(
    moderator1Input.email,
  );
  TestValidator.equals("moderator1.is_active")(found1!.is_active)(
    moderator1Input.is_active,
  );
  TestValidator.equals("moderator1.promoted_by_admin_id")(
    found1!.promoted_by_admin_id,
  )(adminId);

  TestValidator.predicate("moderator2 appears in GET results")(!!found2);
  TestValidator.equals("moderator2.username")(found2!.username)(
    moderator2Input.username,
  );
  TestValidator.equals("moderator2.email")(found2!.email)(
    moderator2Input.email,
  );
  TestValidator.equals("moderator2.is_active")(found2!.is_active)(
    moderator2Input.is_active,
  );
  TestValidator.equals("moderator2.promoted_by_admin_id")(
    found2!.promoted_by_admin_id,
  )(adminId);
}

