 *
 * Business context: Admins may view the list of current moderators. If no
 * moderators have been created yet (fresh install or all deleted), the endpoint
 * must still respond successfully, returning a valid pagination object and an
 * empty moderator array. This prevents UI or logic errors in downstream admin
 * systems and confirms no accidental leakage of deleted/inactive rows unless
 * policy allows exposure.
 *
 * Steps:
 *
 * 1. (Assumed) State: the database contains no moderator records (either fresh
 *    install or pre-cleaned test fixture).
 * 2. Call GET /discussionBoard/admin/moderators as admin.
 * 3. Validate API responds with HTTP 200 and strict IPageIDiscussionBoardModerator
 *    typing.
 * 4. Validate pagination info: current page/limit >= 1, records/pages === 0.
 * 5. Confirm data is an empty array.
 * 6. (Implicit) No exposure of deleted/inactive moderators, since none exist.
 */
export async function test_api_discussionBoard_test_list_moderators_with_no_records(
  connection: api.IConnection,
) {
  // 1. Query the moderators list
  const result =
    await api.functional.discussionBoard.admin.moderators.index(connection);
  typia.assert(result);

  // 2. Validate pagination block present and sensible for empty list
  TestValidator.predicate("current page is valid")(
    typeof result.pagination.current === "number" &&
      result.pagination.current >= 1,
  );
  TestValidator.predicate("limit is valid")(
    typeof result.pagination.limit === "number" && result.pagination.limit >= 1,
  );
  TestValidator.predicate("records is zero for no moderators")(
    result.pagination.records === 0,
  );
  TestValidator.predicate("pages is zero for no moderators")(
    result.pagination.pages === 0,
  );

