  const moderators = await Promise.all([
    api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: `alpha_${RandomGenerator.alphaNumeric(5)}`,
        password_hash: RandomGenerator.alphaNumeric(24),
