import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Validate listing all moderator accounts as a logged-in moderator.
 *
 * Business context: Moderators or admins need to retrieve the list of all
 * moderator accounts for management, audit, or collaboration purposes. This
 * list must include key information (id, username, email, is_active,
 * created_at, updated_at, promoted_by_admin_id), but must not expose sensitive
 * fields like password_hash. Only users with appropriate privileges ('admin' or
 * 'moderator') are permitted to access this endpoint.
 *
 * Workflow:
 *
 * 1. As an admin, create moderator #1 using the admin creation API.
 * 2. As admin, create moderator #2 with a different identity and promote link.
 * 3. (Simulated) Switch to moderator context – continue as-is since no
 *    authentication switch is available.
 * 4. Call the moderator listing API.
 * 5. Validate that the returned data contains both created moderators, each record
 *    includes public fields only, and no password_hash is ever returned.
 * 6. Assert that the audit linkage (promoted_by_admin_id) and pagination fields
 *    are correct.
 */
export async function test_api_discussionBoard_test_list_moderators_success_for_moderator(
  connection: api.IConnection,
) {
  // 1. Create moderator #1 as admin
  const moderator1: IDiscussionBoardModerator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        password_hash: RandomGenerator.alphabets(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator1);

  // 2. Create moderator #2 as admin (simulate promotion linkage)
  const moderator2: IDiscussionBoardModerator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        password_hash: RandomGenerator.alphabets(32),
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
        promoted_by_admin_id: moderator1.promoted_by_admin_id ?? moderator1.id,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator2);

  // 3. Simulate moderator context (continue as-is, as login is not available)

  // 4. Get the list of moderators as a moderator
  const moderatorsResp: IPageIDiscussionBoardModerator =
    await api.functional.discussionBoard.moderator.moderators.index(connection);
  typia.assert(moderatorsResp);

  // 5. Validate both moderators are present
  const moderatorIds = moderatorsResp.data.map((m) => m.id);
  TestValidator.predicate("moderator 1 present")(
    moderatorIds.includes(moderator1.id),
  );
  TestValidator.predicate("moderator 2 present")(
    moderatorIds.includes(moderator2.id),
  );

  // 6. Check all public fields (and absence of password_hash) for every moderator entity
  for (const mod of moderatorsResp.data) {
    TestValidator.predicate("has id")(typeof mod.id === "string" && !!mod.id);
    TestValidator.predicate("has username")(
      typeof mod.username === "string" && !!mod.username,
    );
    TestValidator.predicate("has email")(
      typeof mod.email === "string" && !!mod.email,
    );
    TestValidator.predicate("is_active set")(
      typeof mod.is_active === "boolean",
    );
    TestValidator.predicate("created_at present")(
      typeof mod.created_at === "string" && !!mod.created_at,
    );
    TestValidator.predicate("updated_at present")(
      typeof mod.updated_at === "string" && !!mod.updated_at,
    );
    if (Object.prototype.hasOwnProperty.call(mod, "password_hash"))
      throw new Error("Moderator entity returned password_hash");
  }

  // 7. Validate pagination metadata
  TestValidator.predicate("pagination present")(!!moderatorsResp.pagination);
  TestValidator.predicate("pagination.current positive")(
    moderatorsResp.pagination.current > 0,
  );
  TestValidator.predicate("pagination.limit positive")(
    moderatorsResp.pagination.limit > 0,
  );
  TestValidator.predicate("pagination.records nonnegative")(
    moderatorsResp.pagination.records >= 0,
  );
  TestValidator.predicate("pagination.pages positive")(
    moderatorsResp.pagination.pages > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that non-admin and non-moderator roles are denied access to
 * moderator listing endpoint.
 *
 * This test ensures that users who are not admins or moderators (including
 * regular members and unauthenticated users) cannot retrieve the list of
 * discussion board moderators. The endpoint should return permission denied or
 * unauthorized errors to all such users.
 *
 * Step-by-step process:
 *
 * 1. Register a new regular member (non-moderator, non-admin).
 * 2. Attempt to access the moderator list as this member and expect a permission
 *    error.
 * 3. Simulate an unauthenticated request and attempt access, expecting
 *    unauthorized error.
 */
export async function test_api_discussionBoard_test_list_moderators_permission_denied_to_non_moderator_roles(
  connection: api.IConnection,
) {
  // 1. Register a new member who does not have moderator/admin role
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberDisplayName: string = RandomGenerator.name();
  const memberPassword: string = RandomGenerator.alphaNumeric(16);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPassword,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Attempt to access moderator list as the registered member (should fail)
  await TestValidator.error("member access denied to moderator list")(
    async () => {
      await api.functional.discussionBoard.moderator.moderators.index(
        connection,
      );
    },
  );

  // 3. Simulate unauthenticated request (should also be denied)
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {}, // Remove all headers for anon request
  };
  await TestValidator.error("unauthenticated access denied to moderator list")(
    async () => {
      await api.functional.discussionBoard.moderator.moderators.index(
        unauthenticatedConnection,
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";

/**
 * Validate searching moderators by full or partial username as an admin.
 *
 * This test ensures the following admin workflow:
 *
 * 1. Three moderators are created with unique, programmatically related usernames.
 * 2. The admin searches for moderators by exact username: only the precise match
 *    should be returned.
 * 3. The admin searches by a partial username string: all matching (created)
 *    moderators are returned.
 * 4. The admin searches with a non-matching string: no records are returned.
 *
 * All returned moderator records are validated for full DTO schema compliance
 * and correct business data.
 *
 * Step-by-step process:
 *
 * 1. Create three moderators using
 *    api.functional.discussionBoard.admin.moderators.create.
 * 2. Search by the first moderator's full username and check for a single match.
 * 3. Search by the common username prefix and check for all three matches.
 * 4. Search with a string not matching any moderator; expect no results in the
 *    response.
 * 5. Validate each response and moderator data structure using typia.assert and
 *    TestValidator.
 */
export async function test_api_discussionBoard_test_search_moderators_by_username(
  connection: api.IConnection,
) {
  // 1. Create moderators with unique, related usernames
  const baseUsername = `mod_${RandomGenerator.alphabets(8)}`;

  const moderatorAlice =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: `${baseUsername}_alice`,
        password_hash: RandomGenerator.alphaNumeric(32),
        email: `${baseUsername}_alice@example.com`,
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorAlice);

  const moderatorBob =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: `${baseUsername}_bob`,
        password_hash: RandomGenerator.alphaNumeric(32),
        email: `${baseUsername}_bob@example.com`,
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorBob);

  const moderatorCharlie =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: `${baseUsername}_charlie`,
        password_hash: RandomGenerator.alphaNumeric(32),
        email: `${baseUsername}_charlie@example.com`,
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorCharlie);

  // 2. Search by exact username (moderatorAlice)
  const searchExact =
    await api.functional.discussionBoard.admin.moderators.search(connection, {
      body: {
        username: moderatorAlice.username,
      },
    });
  typia.assert(searchExact);
  TestValidator.equals("only the exact moderator is returned")(
    searchExact.data.length,
  )(1);
  TestValidator.equals("username matches")(searchExact.data[0].username)(
    moderatorAlice.username,
  );
  typia.assert(searchExact.data[0]);

  // 3. Search by a common partial username prefix
  const partialPrefix = `${baseUsername}_`;
  const searchPartial =
    await api.functional.discussionBoard.admin.moderators.search(connection, {
      body: {
        username: partialPrefix,
      },
    });
  typia.assert(searchPartial);
  const usernamesReturned = searchPartial.data.map((m) => m.username);
  for (const user of [moderatorAlice, moderatorBob, moderatorCharlie]) {
    TestValidator.predicate(`partial search returns ${user.username}`)(
      usernamesReturned.includes(user.username),
    );
  }
  for (const m of searchPartial.data) {
    TestValidator.predicate("search matches prefix")(
      m.username.startsWith(partialPrefix),
    );
    typia.assert(m);
  }

  // 4. Search for non-existent username string
  const nonMatching = "unfindable_username_string";
  const searchNone =
    await api.functional.discussionBoard.admin.moderators.search(connection, {
      body: {
        username: nonMatching,
      },
    });
  typia.assert(searchNone);
  TestValidator.equals("search for non-existent username yields no records")(
    searchNone.data.length,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";

/**
 * Validate advanced search and filtering for discussion board moderators by
 * email and activity status.
 *
 * This test creates multiple moderators with unique combinations of email
 * addresses and active/inactive states, and then performs filtered searches
 * using the PATCH endpoint to verify that search results match the expected
 * moderators per filter criteria.
 *
 * Steps:
 *
 * 1. Create four moderators with distinct emails and a mix of active/inactive
 *    statuses.
 * 2. Perform a search filtering by an email substring and is_active=true, expect
 *    only the active moderator(s) with email matching to be returned.
 * 3. Perform another search for is_active=false, expect only the inactive
 *    moderators, regardless of email.
 * 4. Perform a search filtering by an exact email and is_active=false to test
 *    combined filters.
 * 5. Validate that results returned by each search are exactly as expected (all
 *    records returned match requested filters, and no unexpected records are
 *    present).
 */
export async function test_api_discussionBoard_test_search_moderators_by_email_and_status(
  connection: api.IConnection,
) {
  // 1. Create four moderators with varied emails and active statuses
  const moderators = [
    {
      username: RandomGenerator.alphaNumeric(10),
      password_hash: RandomGenerator.alphaNumeric(32),
      email: `alpha_${typia.random<string & tags.Format<"email">>()}`,
      is_active: true,
    },
    {
      username: RandomGenerator.alphaNumeric(10),
      password_hash: RandomGenerator.alphaNumeric(32),
      email: `beta_${typia.random<string & tags.Format<"email">>()}`,
      is_active: true,
    },
    {
      username: RandomGenerator.alphaNumeric(10),
      password_hash: RandomGenerator.alphaNumeric(32),
      email: `gamma_${typia.random<string & tags.Format<"email">>()}`,
      is_active: false,
    },
    {
      username: RandomGenerator.alphaNumeric(10),
      password_hash: RandomGenerator.alphaNumeric(32),
      email: `delta_${typia.random<string & tags.Format<"email">>()}`,
      is_active: false,
    },
  ].map(
    (m) =>
      ({
        ...m,
        // Optionally assign promoted_by_admin_id: omitted for realism
      }) satisfies IDiscussionBoardModerator.ICreate,
  );

  // Create the moderators through the API and store reference
  const created: IDiscussionBoardModerator[] = [];
  for (const mod of moderators) {
    const output = await api.functional.discussionBoard.admin.moderators.create(
      connection,
      { body: mod },
    );
    typia.assert(output);
    created.push(output);
  }

  // 2. Search for all active moderators whose email contains 'alpha_' and verify result
  const searchByAlphaActive =
    await api.functional.discussionBoard.admin.moderators.search(connection, {
      body: { email: "alpha_", is_active: true },
    });
  typia.assert(searchByAlphaActive);
  // Only 1 expected (the alpha_ moderator who is active)
  TestValidator.equals("alpha active moderators count")(
    searchByAlphaActive.data.length,
  )(1);
  TestValidator.predicate("alpha active moderator correct")(
    searchByAlphaActive.data.every(
      (m) => m.email.startsWith("alpha_") && m.is_active === true,
    ),
  );

  // 3. Search for all inactive moderators (regardless of email)
  const searchInactive =
    await api.functional.discussionBoard.admin.moderators.search(connection, {
      body: { is_active: false },
    });
  typia.assert(searchInactive);
  // Should be two (gamma_ and delta_)
  TestValidator.equals("inactive moderators count")(searchInactive.data.length)(
    2,
  );
  TestValidator.predicate("all moderators inactive")(
    searchInactive.data.every((m) => m.is_active === false),
  );

  // 4. Search for an exact email and is_active=false (gamma_)
  const searchGammaInactive =
    await api.functional.discussionBoard.admin.moderators.search(connection, {
      body: { email: created[2].email, is_active: false },
    });
  typia.assert(searchGammaInactive);
  TestValidator.equals("exact moderator gamma_")(
    searchGammaInactive.data.length,
  )(1);
  TestValidator.equals("gamma inactive")(searchGammaInactive.data[0].email)(
    created[2].email,
  );
  TestValidator.equals("gamma inactive status")(
    searchGammaInactive.data[0].is_active,
  )(false);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";

/**
 * Validates that searching for a moderator using criteria that will yield no
 * results (such as a non-existent username or email) returns a valid, empty
 * paginated response.
 *
 * This test ensures that the admin moderator search endpoint correctly
 * processes queries with no matching records, returning an empty data set in
 * the paginated response (not an error).
 *
 * 1. Send a search PATCH request to /discussionBoard/admin/moderators using a
 *    deliberately non-existent username and/or email (strings unlikely to exist
 *    in any real dataset).
 * 2. Assert that the API returns a success response with an empty moderators data
 *    array in the response, and valid pagination metadata with zero
 *    records/pages.
 * 3. Confirm there is no thrown error or exception.
 */
export async function test_api_discussionBoard_admin_moderators_test_search_moderators_with_no_results(
  connection: api.IConnection,
) {
  // 1. Search with non-existent username/email
  const query = {
    username: "_e2e_NOUSER_" + typia.random<string>(), // Improbable to exist
    email: "nope_" + typia.random<string>() + "@notarealdomain.example.invalid",
  } satisfies IDiscussionBoardModerator.IRequest;

  const output = await api.functional.discussionBoard.admin.moderators.search(
    connection,
    { body: query },
  );
  typia.assert(output);

  // 2. Pagination/data validation
  TestValidator.equals("empty moderator data")(output.data)([]);
  TestValidator.equals("zero records")(output.pagination.records)(0);
  TestValidator.equals("zero pages")(output.pagination.pages)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
