import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Validate retrieving a paginated list of all admin accounts as an authorized
 * admin user, and confirm access control and data/data correctness.
 *
 * This test verifies that:
 *
 * - Newly created admins appear in the admin list results
 * - Only users with proper admin privileges can access this endpoint (negative
 *   test omitted due to context)
 * - No sensitive fields (such as password hashes) are present in the admin
 *   objects
 * - All required public fields (id, username, email, is_active, created_at,
 *   updated_at) are present
 * - Pagination metadata (current, limit, records, pages) is valid
 *
 * Business context: Only admin-privileged users should manage or view the admin
 * account list. The result must reflect the most current admin table, including
 * newly added admins, and must never expose secret information. Unauthorized
 * calls should be rejected by the system, but this is not checked here as only
 * admin context is available.
 *
 * Steps:
 *
 * 1. As an authorized admin user, create a new admin account using the API.
 * 2. Immediately retrieve the paginated admin list to ensure the newly created
 *    admin is present.
 * 3. Validate each admin object to confirm all required fields exist (id,
 *    username, email, is_active, created_at, updated_at) and no
 *    sensitive/authentication field (like password_hash) is exposed.
 * 4. Confirm pagination metadata shape and types.
 * 5. (Negative/unauthorized-access test omitted due to lack of a non-admin
 *    authentication scenario.)
 */
export async function test_api_discussionBoard_admin_admins_test_list_admins_with_pagination_and_access_control(
  connection: api.IConnection,
) {
  // 1. Create a new admin account
  const adminCreateBody: IDiscussionBoardAdmin.ICreate = {
    username: `admin_${RandomGenerator.alphaNumeric(8)}`,
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
    is_active: true,
  };
  const newAdmin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    { body: adminCreateBody },
  );
  typia.assert(newAdmin);
  TestValidator.equals("admin created with correct username")(
    newAdmin.username,
  )(adminCreateBody.username);
  TestValidator.equals("admin created with correct email")(newAdmin.email)(
    adminCreateBody.email,
  );
  TestValidator.equals("admin is active after creation")(newAdmin.is_active)(
    true,
  );
  TestValidator.predicate("no password_hash field in response")(
    !("password_hash" in newAdmin),
  );

  // 2. Retrieve the admin list
  const adminList =
    await api.functional.discussionBoard.admin.admins.index(connection);
  typia.assert(adminList);
  TestValidator.predicate("admin list contains created admin")(
    adminList.data.some((a) => a.id === newAdmin.id),
  );

  // 3. Validate each admin's required fields and no sensitive data
  for (const admin of adminList.data) {
    TestValidator.predicate("no password_hash exposed")(
      !("password_hash" in admin),
    );
    TestValidator.predicate("has id")(
      typeof admin.id === "string" && admin.id.length > 0,
    );
    TestValidator.predicate("has username")(
      typeof admin.username === "string" && admin.username.length > 0,
    );
    TestValidator.predicate("has email")(
      typeof admin.email === "string" && admin.email.length > 0,
    );
    TestValidator.predicate("has is_active")(
      typeof admin.is_active === "boolean",
    );
    TestValidator.predicate("has created_at")(
      typeof admin.created_at === "string" && admin.created_at.length > 0,
    );
    TestValidator.predicate("has updated_at")(
      typeof admin.updated_at === "string" && admin.updated_at.length > 0,
    );
  }

  // 4. Validate pagination metadata
  TestValidator.predicate("pagination object valid")(
    typeof adminList.pagination === "object" &&
      adminList.pagination !== null &&
      typeof adminList.pagination.current === "number" &&
      typeof adminList.pagination.limit === "number" &&
      typeof adminList.pagination.records === "number" &&
      typeof adminList.pagination.pages === "number",
  );

  // 5. (Negative/unauthorized-access test omitted due to privileged context only)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test advanced admin search and filtering functionality for admin accounts.
 *
 * This test validates that as a super-admin:
 *
 * - Admin accounts can be located by filtering on partial username and is_active
 *   status
 * - Only matching records are included in results
 * - Pagination/limit parameters are respected (i.e., no data leakage from
 *   adjacent pages)
 * - Off-by-one and edge boundary checks for paging
 * - Only authorized users (admins) have access to search; unauthorized calls are
 *   rejected
 *
 * Step-by-step process:
 *
 * 1. Create 5 admin accounts with distinct usernames and is_active statuses (e.g.,
 *    3 active, 2 inactive, both with variety in username substrings)
 * 2. As an admin user, search for all admins with username containing a unique
 *    substring present in one account only and is_active=true; check that only
 *    the correct admin is returned
 * 3. Search for all inactive admins (is_active=false); check only the 2 inactive
 *    ones are returned
 * 4. Search with no filters, but limit=2 and page=2; verify the correct offset
 *    (pagination) is respected with no records from previous or following pages
 *    leaking in
 * 5. Attempt to search for admins as a non-admin/non-privileged connection; verify
 *    access is denied (e.g., error is thrown)
 */
export async function test_api_discussionBoard_admin_admins_test_search_admins_by_username_and_status(
  connection: api.IConnection,
) {
  // 1. Create 5 admin accounts with varying usernames and statuses
  const admins: IDiscussionBoardAdmin[] = [];
  for (let i = 0; i < 5; ++i) {
    const is_active = i % 2 === 0;
    const username = `e2e_admin_user_${i}_${RandomGenerator.alphabets(4)}`;
    const admin = await api.functional.discussionBoard.admin.admins.create(
      connection,
      {
        body: {
          username,
          email: `e2e_admin${i}_${typia.random<string & tags.Format<"email">>()}`,
          password_hash: RandomGenerator.alphaNumeric(8),
          is_active,
        } satisfies IDiscussionBoardAdmin.ICreate,
      },
    );
    typia.assert(admin);
    admins.push(admin);
  }

  // 2. Search for an account with a unique username substring, is_active=true
  const target = admins.find((a) => a.is_active)!;
  const unique_user_sub = target.username.slice(0, 12); // unique prefix
  const search1 = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        username: unique_user_sub,
        is_active: true,
        page: 1,
        limit: 10,
        email: null,
        created_at_from: null,
        created_at_to: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(search1);
  TestValidator.equals("matched data only")(search1.data.length)(1);
  TestValidator.equals("matched admin id")(search1.data[0].id)(target.id);

  // 3. Search for all inactive admins
  const search2 = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        is_active: false,
        page: 1,
        limit: 10,
        username: null,
        email: null,
        created_at_from: null,
        created_at_to: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(search2);
  const expectedInactive = admins
    .filter((a) => !a.is_active)
    .map((a) => a.id)
    .sort();
  const actualInactive = search2.data.map((a) => a.id).sort();
  TestValidator.equals("inactive admins correct")(actualInactive)(
    expectedInactive,
  );

  // 4. Pagination/offset test: no filter, page=2, limit=2
  const search3 = await api.functional.discussionBoard.admin.admins.search(
    connection,
    {
      body: {
        page: 2,
        limit: 2,
        username: null,
        is_active: null,
        email: null,
        created_at_from: null,
        created_at_to: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    },
  );
  typia.assert(search3);
  TestValidator.equals("pagination respects limit")(search3.data.length)(2);
  // IDs for second page match source
  const expectedPage2 = admins.slice(2, 4).map((a) => a.id);
  const actualPage2 = search3.data.map((a) => a.id);
  TestValidator.equals("pagination 2nd page IDs")(actualPage2)(expectedPage2);

  // 5. Negative case: try calling search as guest/invalid (simulate unauthorized user)
  const guestConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized search fails")(async () => {
    await api.functional.discussionBoard.admin.admins.search(guestConnection, {
      body: {
        page: 1,
        limit: 10,
        username: null,
        is_active: null,
        email: null,
        created_at_from: null,
        created_at_to: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate error handling and security for searching admin accounts with
 * invalid criteria.
 *
 * This test ensures that searching for admin accounts with a variety of invalid
 * or malformed arguments triggers proper validation errors, that no sensitive
 * fields (passwords, tokens, etc.) are ever included in error responses, and
 * that error structures are descriptive but never expose implementation
 * internals.
 *
 * Steps:
 *
 * 1. Attempt to search admins with a malformed email address, expecting a
 *    validation error with no private data.
 * 2. Attempt to search admins using an out-of-range page number (e.g., zero or
 *    negative), expecting a validation error.
 * 3. Attempt to search admins with a negative limit value, expecting a validation
 *    error.
 * 4. Attempt to search admins using non-boolean (number) for is_active (runtime
 *    validation, not compile-time).
 * 5. Optionally, large numbers for page/limit (e.g., greater than max safe int)
 *    for robustness.
 * 6. For each error returned, validate that the error does NOT expose sensitive
 *    information and only provides clear, bounded details.
 */
export async function test_api_discussionBoard_test_search_admins_with_invalid_criteria(
  connection: api.IConnection,
) {
  // 1. Invalid email format
  await TestValidator.error("invalid email validation error")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        email: "not-an-email",
        page: 1,
        limit: 5,
      } satisfies IDiscussionBoardAdmin.IRequest,
    }),
  );

  // 2. Out-of-range pagination: page = 0
  await TestValidator.error("page number min boundary error")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        page: 0,
        limit: 10,
        email: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    }),
  );

  // 3. Negative limit
  await TestValidator.error("negative limit error")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        limit: -1,
        page: 1,
        email: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    }),
  );

  // 4. Non-boolean is_active (number instead of boolean/null)
  await TestValidator.error("non-boolean is_active error")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      // Intentionally send a wrong type to catch backend validation
      body: {
        is_active: 1,
        page: 1,
        limit: 3,
        email: null,
      } as any,
    }),
  );

  // 5. Excessive/large pagination values
  await TestValidator.error("excessively large page/limit")(() =>
    api.functional.discussionBoard.admin.admins.search(connection, {
      body: {
        page: Number.MAX_SAFE_INTEGER,
        limit: Number.MAX_SAFE_INTEGER,
        email: null,
      } satisfies IDiscussionBoardAdmin.IRequest,
    }),
  );

  // 6. Defensive check: all errors must be bounded; real error structure check requires API-level agreement
  // DO NOT attempt to extract details from error surface unless SDK surfaces error data
  // Defensive comment: API never exposes password/token information in any response (enforced contract)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
