/**
 * Validate admin detail retrieval by ID and proper field/security exposure.
 *
 * This test ensures that:
 *
 * - An admin can create a fellow admin account (unique username/email, strong
 *   password hash, is_active=true).
 * - The admin's details can be retrieved by ID, all key audit fields are present
 *   and correct, and sensitive credentials (like password_hash) are never
 *   exposed.
 * - Business rules are respected: missing/nonexistent IDs fail with error, and
 *   (if possible) restricted/non-admin access would also fail (skipped due to
 *   no non-admin login API).
 *
 * Workflow:
 *
 * 1. Create a new admin (unique username, email, password hash, is_active=true)
 *    using the admin-create API.
 * 2. Fetch this admin's detail record by its id. Validate field integrity and
 *    absence of sensitive data.
 * 3. Attempt to fetch with a random non-existent UUID as id; confirm error is
 *    thrown.
 * 4. Steps for soft-deletion and non-admin permission checks are omitted as not
 *    implementable with available APIs (no delete/login) - clearly skipped in
 *    documentation.
 */
export async function test_api_discussionBoard_admin_admins_at(
  connection: api.IConnection,
) {
  // 1. Create a new admin record with unique credentials
  const adminToCreate: IDiscussionBoardAdmin.ICreate = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(30),
    is_active: true,
  };
  const admin: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: adminToCreate,
    });
  typia.assert(admin);
  TestValidator.equals("admin.username matches input")(admin.username)(
    adminToCreate.username,
  );
  TestValidator.equals("admin.email matches input")(admin.email)(
    adminToCreate.email,
  );
  TestValidator.equals("admin.is_active matches input")(admin.is_active)(
    adminToCreate.is_active,
  );

  // 2. Retrieve admin details by id and verify correctness
  const fetched: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: admin.id,
    });
  typia.assert(fetched);
  TestValidator.equals("fetched.id matches")(fetched.id)(admin.id);
  TestValidator.equals("fetched.username matches")(fetched.username)(
    admin.username,
  );
  TestValidator.equals("fetched.email matches")(fetched.email)(admin.email);
  TestValidator.equals("fetched.is_active matches")(fetched.is_active)(
    admin.is_active,
  );
  // Ensure response contains no sensitive fields (password_hash)
  if ((fetched as any)["password_hash"] !== undefined)
    throw new Error(
      "password_hash should not be present in detail fetch response",
    );

  // 3. Error case: Fetch with non-existent adminId
  await TestValidator.error("fetching non-existent adminId throws error")(
    async () => {
      await api.functional.discussionBoard.admin.admins.at(connection, {
        adminId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 4. Omitted: Soft-delete/deactivate adminId test as deletion API unavailable.
  // 5. Omitted: Non-admin permission test due to lack of non-admin login API.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
