/**
 * Test admin detail retrieval security and validation.
 *
 * This test verifies two major risk vectors for the `GET
 * /discussionBoard/admin/admins/{adminId}` endpoint:
 *
 * 1. Supplying an invalid UUID as the adminId path parameter, which should result
 *    in a clear error indicating the input is invalid (not a valid UUID
 *    format). The response must NOT leak any unexpected information or data
 *    structure.
 * 2. Attempting access as a non-admin user (or unauthenticated/insufficient role)
 *    using a valid UUID. Should result in an explicit authorization failure
 *    with no details about the admin resource itself.
 *
 * The goal is to ensure robust input validation and strict access controls for
 * potentially sensitive admin operations. Both cases are negative/security
 * tests.
 *
 * Steps:
 *
 * 1. Call the endpoint with an obviously invalid UUID string ('not-a-uuid').
 *    Validate that a suitable error is returned (not a successful object, and
 *    not a null, and no data leakage/structure should be as per error spec).
 * 2. Attempt to access a valid admin account's details using a properly formatted
 *    UUID, but as an unauthenticated or non-admin connection. Ensure that
 *    access is strictly denied and no admin data is returned/displayed (access
 *    control).
 */
export async function test_api_discussionBoard_test_get_admin_details_with_invalid_id_or_permission(
  connection: api.IConnection,
) {
  // 1. Invalid UUID - Input validation error test
  await TestValidator.error("should reject invalid UUID format")(async () => {
    await api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: "not-a-uuid" as any, // purposely invalid format to force error
    });
  });

  // 2. Unauthorized/non-admin access - no explicit login methods in materials, so assume connection is not admin
  const randomUuid = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "should reject unauthorized access with valid uuid",
  )(async () => {
    await api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: randomUuid,
    });
  });
}

