/**
 * Test updating an existing administrator's profile with valid new data.
 *
 * This test validates:
 *
 * - Successful profile update for username, email, password_hash (as a hash
 *   only), and is_active.
 * - Persistence: updated fields must remain in effect in subsequent API
 *   responses.
 * - That password_hash is never leaked in any response.
 * - Audit logging: updated_at is advanced, created_at remains unchanged.
 * - Enforcement of business rules: username/email uniqueness, password is
 *   submitted as a hash not plaintext.
 * - Updates that would conflict by username/email result in API errors.
 *
 * Step-by-step process:
 *
 * 1. Create an admin as the update target.
 * 2. Create a second admin to test uniqueness rules.
 * 3. Update all permitted fields for the first admin.
 * 4. Verify updated fields via API response.
 * 5. Confirm password_hash is never returned from update/read response.
 * 6. Confirm audit logging via timestamp comparison.
 * 7. Assert persistence by comparing IDs and fields after update.
 * 8. Attempt to set duplicate username; expect error.
 * 9. Attempt to set duplicate email; expect error.
 */
export async function test_api_discussionBoard_admin_admins_test_update_admin_information_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create the admin to be updated
  const admin: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(20),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Create a second admin for uniqueness constraint testing
  const conflictAdmin: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(20),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(conflictAdmin);

  // 3. Prepare new update fields
  const updatedUsername = RandomGenerator.alphabets(10);
  const updatedEmail = typia.random<string & tags.Format<"email">>();
  const updatedPasswordHash = RandomGenerator.alphaNumeric(32);
  const updatedIsActive = false;

  // Store old audit timestamps for comparison
  const prevCreatedAt = admin.created_at;
  const prevUpdatedAt = admin.updated_at;

  // 4. Perform the update
  const updated: IDiscussionBoardAdmin =
    await api.functional.discussionBoard.admin.admins.update(connection, {
      adminId: admin.id,
      body: {
        username: updatedUsername,
        email: updatedEmail,
        password_hash: updatedPasswordHash,
        is_active: updatedIsActive,
      } satisfies IDiscussionBoardAdmin.IUpdate,
    });
  typia.assert(updated);

  // 5. Check updates reflected in API response
  TestValidator.equals("username updated")(updated.username)(updatedUsername);
  TestValidator.equals("email updated")(updated.email)(updatedEmail);
  TestValidator.equals("is_active updated")(updated.is_active)(updatedIsActive);

  // 6. Confirm password_hash is never returned
  if ((updated as any).password_hash !== undefined)
    throw new Error("password_hash should never be returned in responses");

  // 7. Check audit timestamps
  TestValidator.equals("created_at unchanged")(updated.created_at)(
    prevCreatedAt,
  );
  TestValidator.predicate("updated_at advanced")(
    new Date(updated.updated_at).getTime() > new Date(prevUpdatedAt).getTime(),
  );

  // 8. ID persists, values persist
  TestValidator.equals("id unchanged")(updated.id)(admin.id);
  TestValidator.equals("fields persisted")(updated.username)(updatedUsername);
  TestValidator.equals("fields persisted")(updated.email)(updatedEmail);
  TestValidator.equals("fields persisted")(updated.is_active)(updatedIsActive);

  // 9. Attempt update to duplicate username
  await TestValidator.error("update to duplicate username fails")(async () => {
    await api.functional.discussionBoard.admin.admins.update(connection, {
      adminId: admin.id,
      body: {
        username: conflictAdmin.username,
      } satisfies IDiscussionBoardAdmin.IUpdate,
    });
  });

  // 10. Attempt update to duplicate email
  await TestValidator.error("update to duplicate email fails")(async () => {
    await api.functional.discussionBoard.admin.admins.update(connection, {
      adminId: admin.id,
      body: {
        email: conflictAdmin.email,
      } satisfies IDiscussionBoardAdmin.IUpdate,
    });
  });
}

