    TestValidator.equals("action matches")(a.action_id)(actionId1);

  // 4. Filter by actor type (member)
  const result_member =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { appellant_member_id: memberId },
    });
  typia.assert(result_member);
  for (const a of result_member.data)
    TestValidator.equals("appellant_member_id matches")(a.appellant_member_id)(
      memberId,
    );

  // 4b. Filter by actor type (admin)
  const result_admin =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { appellant_admin_id: adminId },
    });
  typia.assert(result_admin);
  for (const a of result_admin.data)
    TestValidator.equals("appellant_admin_id matches")(a.appellant_admin_id)(
      adminId,
    );

  // 4c. Filter by actor type (moderator)
  const result_mod = await api.functional.discussionBoard.admin.appeals.search(
    connection,
    { body: { appellant_moderator_id: moderatorId } },
  );
  typia.assert(result_mod);
  for (const a of result_mod.data)
    TestValidator.equals("appellant_moderator_id matches")(
      a.appellant_moderator_id,
    )(moderatorId);

  // 4d. Filter by actor type (guest)
  const result_guest =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { appellant_guest_id: guestId },
    });
  typia.assert(result_guest);
  for (const a of result_guest.data)
    TestValidator.equals("appellant_guest_id matches")(a.appellant_guest_id)(
      guestId,
    );

  // 5. Combine date range filter
  // (use min and max submitted_at in created appeals)
  const minDate = appeals.reduce(
    (min, cur) => (cur.submitted_at < min ? cur.submitted_at : min),
    appeals[0].submitted_at,
  );
  const maxDate = appeals.reduce(
    (max, cur) => (cur.submitted_at > max ? cur.submitted_at : max),
    appeals[0].submitted_at,
  );
  const result_daterange =
    await api.functional.discussionBoard.admin.appeals.search(connection, {
      body: { submitted_from: minDate, submitted_to: maxDate },
    });
  typia.assert(result_daterange);
  // all returned appeals must be within minDate/maxDate inclusively
  for (const a of result_daterange.data) {
    TestValidator.predicate("submitted_at >= minDate")(
      a.submitted_at >= minDate,
    );
    TestValidator.predicate("submitted_at <= maxDate")(
      a.submitted_at <= maxDate,
    );
  }

  // 6. Paginate: set limit=2, page=1
  const result_page = await api.functional.discussionBoard.admin.appeals.search(
    connection,
    { body: { limit: 2, page: 1 } },
  );
  typia.assert(result_page);
  TestValidator.equals("limit")(result_page.pagination.limit)(2);
  TestValidator.equals("page")(result_page.pagination.current)(1);

  // 7. Error: invalid status value
  await TestValidator.error("invalid status enum")(() =>
    api.functional.discussionBoard.admin.appeals.search(connection, {
      // using 'foo' as an invalid status, must cast to correct type for runtime failure
      body: { status: "foo" as unknown as "pending" },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAppeal";
import type { IPageIDiscussionBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAppeal";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for advanced search of moderation action appeals by a moderator
 * using filters and robust pagination.
 *
 * This test covers moderator capability to perform advanced search and paging
 * on appeals, using combinations of supported actor filters, status, action
 * IDs, date range, and thorough pagination handling.
 *
 * Test Scope and Steps:
 *
 * 1. Data Setup: Create 6 appeals via admin API covering all actor roles (admin,
 *    moderator, member, guest), two action_ids, all statuses, and unique
 *    reasons for diversity.
 * 2. As moderator, execute advanced search queries using combinations of:
 *
 *    - Actor type-specific filters (each actor field supported in schema)
 *    - Status
 *    - Action ID
 *    - Submission date range
 *    - Pagination: `limit`, `page`
 *    - Local (post-fetch) filter: rationale/"reason" field keyword matching since
 *         not directly supported by API
 *    - Edge: zero result (filter chain yields no data)
 *    - Edge: request out-of-bounds page (page > total pages, expect 0 data & page
 *         meta)
 * 3. Validation:
 *
 *    - All data/fields conform to DTO and expected (no leaks)
 *    - Filtering, paging, and edge handling all behave as expected
 *    - Data-level predicate tests on results
 *
 * Note: API schema does NOT support a `reason` filter on search; for keyword
 * tests, filter result locally.
 */
export async function test_api_discussionBoard_test_search_appeals_with_varied_filters_as_moderator(
  connection: api.IConnection,
) {
  // 1. Data setup: diverse new appeals (admin, moderator, member, guest, statuses, two action ids, unique reasons)
  const actionIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const createdAppeals: IDiscussionBoardAppeal[] = [];
  const uniqueReasons = [
    "Violated guideline A",
    "Unfair ban",
    "Rule misapplied",
    "Harassment",
    "Spam warning unjust",
    "Moderator mistake",
  ];
  const statuses: ("pending" | "approved" | "denied")[] = [
    "pending",
    "approved",
    "denied",
    "pending",
    "approved",
    "denied",
  ];
  const actorTemplates = [
    { key: "appellant_admin_id" },
    { key: "appellant_moderator_id" },
    { key: "appellant_member_id" },
    { key: "appellant_guest_id" },
  ];
  for (let i = 0; i < 6; ++i) {
    const actor = actorTemplates[i % actorTemplates.length];
    const appealBody: IDiscussionBoardAppeal.ICreate = {
      action_id: actionIds[i % 2],
      reason: uniqueReasons[i],
      status: statuses[i],
      appellant_admin_id:
        actor.key === "appellant_admin_id"
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
      appellant_moderator_id:
        actor.key === "appellant_moderator_id"
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
      appellant_member_id:
        actor.key === "appellant_member_id"
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
      appellant_guest_id:
        actor.key === "appellant_guest_id"
          ? typia.random<string & tags.Format<"uuid">>()
          : null,
    };
    const appeal = await api.functional.discussionBoard.admin.appeals.create(
      connection,
      { body: appealBody },
    );
    typia.assert(appeal);
    createdAppeals.push(appeal);
  }
  // 2a. Filter by actor: moderator
  const modAppeal = createdAppeals.find(
    (a) => a.appellant_moderator_id !== null,
  )!;
  const byMod = await api.functional.discussionBoard.moderator.appeals.search(
    connection,
    {
      body: {
        appellant_moderator_id: modAppeal.appellant_moderator_id,
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(byMod);
  TestValidator.predicate("only moderator appeals")(
    byMod.data.every(
      (a) => a.appellant_moderator_id === modAppeal.appellant_moderator_id,
    ),
  );
  // 2b. Filter by actor: admin
  const adminAppeal = createdAppeals.find(
    (a) => a.appellant_admin_id !== null,
  )!;
  const byAdmin = await api.functional.discussionBoard.moderator.appeals.search(
    connection,
    {
      body: {
        appellant_admin_id: adminAppeal.appellant_admin_id,
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(byAdmin);
  TestValidator.predicate("only admin appeals")(
    byAdmin.data.every(
      (a) => a.appellant_admin_id === adminAppeal.appellant_admin_id,
    ),
  );
  // 2c. Filter by status
  const byStatusPending =
    await api.functional.discussionBoard.moderator.appeals.search(connection, {
      body: {
        status: "pending",
        page: 1,
        limit: 10,
      },
    });
  typia.assert(byStatusPending);
  TestValidator.predicate("only pending appeals")(
    byStatusPending.data.every((a) => a.status === "pending"),
  );
  // 2d. Local rationale keyword filter (API does NOT filter by reason in schema)
  // Find a keyword present in one or more reasons
  const keyword = "Rule";
  const searchResult =
    await api.functional.discussionBoard.moderator.appeals.search(connection, {
      body: { limit: 10 },
    });
  typia.assert(searchResult);
  TestValidator.predicate("at least one result contains keyword in reason")(
    searchResult.data.some((a) => a.reason.includes(keyword)),
  );
  // 2e. Filter by action_id
  const actId = actionIds[0];
  const byAction =
    await api.functional.discussionBoard.moderator.appeals.search(connection, {
      body: { action_id: actId, limit: 10 },
    });
  typia.assert(byAction);
  TestValidator.predicate("all have action id")(
    byAction.data.every((a) => a.action_id === actId),
  );
  // 2f. Filter by date range
  const dt = createdAppeals[0].submitted_at;
  const byDate = await api.functional.discussionBoard.moderator.appeals.search(
    connection,
    {
      body: {
        submitted_from: dt,
        submitted_to: dt,
        limit: 10,
      },
    },
  );
  typia.assert(byDate);
  TestValidator.predicate("date in range")(
    byDate.data.every((a) => a.submitted_at >= dt && a.submitted_at <= dt),
  );
  // 2g. Pagination
  const paged = await api.functional.discussionBoard.moderator.appeals.search(
    connection,
    {
      body: { page: 1, limit: 2 },
    },
  );
  typia.assert(paged);
  TestValidator.equals("limit in page meta")(paged.pagination.limit)(2);
  TestValidator.predicate("max 2 on page")(paged.data.length <= 2);
  // 2h. Edge: Zero results
  // Use a UUID that will not match any actor
  const byUnmatch =
    await api.functional.discussionBoard.moderator.appeals.search(connection, {
      body: {
        appellant_admin_id: typia.random<string & tags.Format<"uuid">>(),
        limit: 10,
      },
    });
  typia.assert(byUnmatch);
  TestValidator.equals("no results for unmatched actor")(byUnmatch.data.length)(
    0,
  );
  // 2i. Edge: request page > pages
  const maxPage = paged.pagination.pages + 1;
  const pagedOOB =
    await api.functional.discussionBoard.moderator.appeals.search(connection, {
      body: { page: maxPage, limit: 2 },
    });
  typia.assert(pagedOOB);
  TestValidator.equals("empty data when page out-of-bounds")(
    pagedOOB.data.length,
  )(0);
  TestValidator.equals("meta page matches")(pagedOOB.pagination.current)(
    maxPage,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
