/**
 * Validate admin ability to retrieve a specific moderation appeal by its ID.
 *
 * This test confirms regulatory and due process compliance by ensuring that,
 * after creating an appeal record as admin, the record is retrievable in full
 * detail using its unique ID. It checks that all returned fields (action
 * reference, appellant, rationale, status, audit trail) exactly match those
 * submitted, and that timestamps are in proper format. Additionally, it
 * verifies the system correctly returns a 404 error for requests with invalid
 * or nonexistent IDs, ensuring access control and workflow consistency.
 *
 * Steps:
 *
 * 1. Create an appeal via POST /discussionBoard/admin/appeals (fill only admin
 *    appellant; others as null).
 * 2. Retrieve the same appeal with GET /discussionBoard/admin/appeals/{appealId}.
 * 3. Assert all fields (including id) match between creation input and fetched
 *    record.
 * 4. Confirm submitted_at is a valid ISO8601 datetime string.
 * 5. Perform lookup using random, non-existent ID and assert a 404 error occurs.
 */
export async function test_api_discussionBoard_admin_appeals_test_get_single_appeal_by_id_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a new moderation action appeal as admin
  const input: IDiscussionBoardAppeal.ICreate = {
    action_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Test appeal reason for E2E validation",
    status: "pending",
    appellant_admin_id: typia.random<string & tags.Format<"uuid">>(),
    appellant_moderator_id: null,
    appellant_member_id: null,
    appellant_guest_id: null,
  };
  const created: IDiscussionBoardAppeal =
    await api.functional.discussionBoard.admin.appeals.create(connection, {
      body: input,
    });
  typia.assert(created);
  // 2. Retrieve appeal by its id
  const fetched: IDiscussionBoardAppeal =
    await api.functional.discussionBoard.admin.appeals.at(connection, {
      appealId: created.id,
    });
  typia.assert(fetched);
  // 3. Assert all relevant fields match between creation and fetched record
  TestValidator.equals("appeal id")(fetched.id)(created.id);
  TestValidator.equals("action ID")(fetched.action_id)(input.action_id);
  TestValidator.equals("reason")(fetched.reason)(input.reason);
  TestValidator.equals("status")(fetched.status)(input.status);
  TestValidator.equals("appellant_admin_id")(fetched.appellant_admin_id)(
    input.appellant_admin_id,
  );
  TestValidator.equals("appellant_moderator_id")(
    fetched.appellant_moderator_id,
  )(input.appellant_moderator_id);
  TestValidator.equals("appellant_member_id")(fetched.appellant_member_id)(
    input.appellant_member_id,
  );
  TestValidator.equals("appellant_guest_id")(fetched.appellant_guest_id)(
    input.appellant_guest_id,
  );
  TestValidator.predicate("submitted_at is ISO8601 string")(
    !!Date.parse(fetched.submitted_at),
  );
  // 4. Error scenario: attempt to fetch appeal by a missing/invalid id
  TestValidator.error("not found appeal returns 404")(async () => {
    await api.functional.discussionBoard.admin.appeals.at(connection, {
      appealId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

