/**
 * Test the appeal creation workflow as an admin, covering both valid and
 * invalid inputs.
 *
 * This test ensures:
 *
 * 1. Successful appeal creation as an admin with all valid/required fields.
 * 2. Proper validation errors for missing/invalid fields and actor references.
 * 3. Duplicate submission rejections when applicable.
 *
 * Step-by-step process:
 *
 * 1. Create a valid appeal (as admin, pending status, correct actor & action IDs).
 * 2. Attempt creation with various invalid/missing fields (action_id, reason,
 *    mutually exclusive actors, enum status).
 * 3. Attempt to create a duplicate appeal for same action-admin.
 */
export async function test_api_discussionBoard_admin_appeals_create(
  connection: api.IConnection,
) {
  // 1. ---- Valid appeal creation by admin ----
  const valid_action_id = typia.random<string & tags.Format<"uuid">>();
  const valid_admin_id = typia.random<string & tags.Format<"uuid">>();
  const valid_input: IDiscussionBoardAppeal.ICreate = {
    action_id: valid_action_id,
    reason: "Valid appeal submitted by admin user.",
    status: "pending",
    appellant_admin_id: valid_admin_id,
    appellant_moderator_id: null,
    appellant_member_id: null,
    appellant_guest_id: null,
