    connection,
    { body: valid_input },
  );
  typia.assert(result);
  TestValidator.equals("action_id matches")(result.action_id)(
    valid_input.action_id,
  );
  TestValidator.equals("reason matches")(result.reason)(valid_input.reason);
  TestValidator.equals("status is pending")(result.status)("pending");
  TestValidator.equals("admin id matches")(result.appellant_admin_id)(
    valid_input.appellant_admin_id,
  );
  TestValidator.equals("moderator id null")(result.appellant_moderator_id)(
    null,
  );
  TestValidator.equals("member id null")(result.appellant_member_id)(null);
  TestValidator.equals("guest id null")(result.appellant_guest_id)(null);

  // 2a. ---- Missing action_id ----
  await TestValidator.error("missing action_id should fail")(() =>
    api.functional.discussionBoard.admin.appeals.create(connection, {
      body: {
        // action_id intentionally omitted
        reason: "Missing action_id",
        status: "pending",
        appellant_admin_id: valid_admin_id,
        appellant_moderator_id: null,
        appellant_member_id: null,
        appellant_guest_id: null,
      } as any,
    }),
  );

  // 2a. ---- Invalid format action_id ----
  await TestValidator.error("invalid action_id format should fail")(() =>
    api.functional.discussionBoard.admin.appeals.create(connection, {
      body: {
        action_id: "not-a-uuid",
        reason: "Appeal with invalid action_id format",
        status: "pending",
        appellant_admin_id: valid_admin_id,
        appellant_moderator_id: null,
        appellant_member_id: null,
        appellant_guest_id: null,
      } as any,
    }),
  );

  // 2b. ---- Missing reason ----
  await TestValidator.error("missing reason should fail")(() =>
    api.functional.discussionBoard.admin.appeals.create(connection, {
      body: {
        action_id: valid_action_id,
        // reason intentionally omitted
        status: "pending",
        appellant_admin_id: valid_admin_id,
        appellant_moderator_id: null,
        appellant_member_id: null,
        appellant_guest_id: null,
      } as any,
    }),
  );

  // 2b. ---- Empty reason string ----
  await TestValidator.error("empty reason string should fail")(() =>
    api.functional.discussionBoard.admin.appeals.create(connection, {
      body: {
        action_id: valid_action_id,
        reason: "",
        status: "pending",
        appellant_admin_id: valid_admin_id,
        appellant_moderator_id: null,
        appellant_member_id: null,
        appellant_guest_id: null,
      },
    }),
  );

  // 2c. ---- Invalid: Two actor ids set (admin+member) ----
  await TestValidator.error(
    "multiple actor role fields (admin and member) should fail",
  )(() =>
    api.functional.discussionBoard.admin.appeals.create(connection, {
      body: {
        action_id: valid_action_id,
        reason: "Appeal by admin and member (should be exclusive)",
        status: "pending",
        appellant_admin_id: valid_admin_id,
        appellant_moderator_id: null,
        appellant_member_id: typia.random<string & tags.Format<"uuid">>(),
        appellant_guest_id: null,
      },
    }),
  );

  // 2d. ---- Invalid status field ----
  await TestValidator.error(
    "invalid status (not allowed enum value) should fail",
  )(() =>
    api.functional.discussionBoard.admin.appeals.create(connection, {
      body: {
        action_id: valid_action_id,
        reason: "Appeal with bad enum status",
        status: "wait" as any,
        appellant_admin_id: valid_admin_id,
        appellant_moderator_id: null,
        appellant_member_id: null,
        appellant_guest_id: null,
      } as any,
    }),
  );

  // 3. ---- Duplicate appeal submission (should fail if unique) ----
  await TestValidator.error(
    "duplicate appeal for same action-admin should fail",
  )(() =>
    api.functional.discussionBoard.admin.appeals.create(connection, {
      body: valid_input,
    }),
  );
}

