import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates that an authenticated member can retrieve a paginated list of all
 * non-deleted discussion board comments.
 *
 * This test ensures that only non-soft-deleted comments are returned in the
 * member comment list, and that each returned record contains the required
 * fields for summary display, correct linkage to member and post, and complies
 * with the business logic that deleted comments must be filtered out.
 *
 * Steps:
 *
 * 1. Register a new member account and authenticate as that member.
 * 2. Create two distinct posts as this authenticated member.
 * 3. Under each post, create two comments (total four comments, all by the same
 *    member and spread across two posts).
 * 4. Soft-delete one comment on each post (thus, two comments out of four are soft
 *    deleted).
 * 5. Retrieve the paginated list of all comments as the authenticated member using
 *    the comment listing API.
 * 6. Confirm that only the two non-deleted comments appear in the result, and each
 *    contains all required summary fields, correct member reference, and
 *    correct post linkage.
 */
export async function test_api_discussionBoard_test_list_all_comments_as_member(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);

  // 2. Create two posts as the member
  const post1: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(6),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post1);

  const post2: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(6),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post2);

  // 3. Add two comments on each post
  const comment1_1: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post1.id,
        body: {
          discussion_board_post_id: post1.id,
          body: "Comment 1 on Post 1" + RandomGenerator.alphaNumeric(5),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment1_1);
  const comment1_2: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post1.id,
        body: {
          discussion_board_post_id: post1.id,
          body: "Comment 2 on Post 1" + RandomGenerator.alphaNumeric(5),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment1_2);
  const comment2_1: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post2.id,
        body: {
          discussion_board_post_id: post2.id,
          body: "Comment 1 on Post 2" + RandomGenerator.alphaNumeric(5),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment2_1);
  const comment2_2: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post2.id,
        body: {
          discussion_board_post_id: post2.id,
          body: "Comment 2 on Post 2" + RandomGenerator.alphaNumeric(5),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment2_2);

  // 4. Soft-delete one comment per post
  await api.functional.discussionBoard.member.comments.erase(connection, {
    commentId: comment1_1.id,
  });
  await api.functional.discussionBoard.member.comments.erase(connection, {
    commentId: comment2_1.id,
  });

  // 5. Retrieve all comments (should only retrieve two active comments)
  const result =
    await api.functional.discussionBoard.member.comments.index(connection);
  typia.assert(result);
  TestValidator.predicate("Only two active comments returned")(
    result.data.length === 2,
  );

  // 6. Validate returned comments are correct and contain required fields
  const activeComments = [comment1_2, comment2_2];
  for (const returned of result.data) {
    TestValidator.predicate("Returned comment is one of active test comments")(
      activeComments.some((c) => c.id === returned.id),
    );
    TestValidator.predicate("Returned comment has correct member id")(
      returned.discussion_board_member_id === member.id,
    );
    TestValidator.predicate("Returned comment has correct post id")(
      activeComments.some(
        (c) => c.discussion_board_post_id === returned.discussion_board_post_id,
      ),
    );
    TestValidator.equals("Comment is not soft deleted")(returned.deleted_at)(
      null,
    );
    TestValidator.predicate("Has non-empty body")(
      typeof returned.body === "string" && returned.body.length > 0,
    );
    TestValidator.predicate("Returned comment has valid id")(
      typeof returned.id === "string" && returned.id.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator full comment listing, including soft-deleted comments.
 *
 * This test ensures a moderator can retrieve the full set of comments,
 * including those that have been soft-deleted (for moderation/audit purposes).
 * The test confirms deleted comments are present and flagged accordingly,
 * verifying moderation workflows operate as intended.
 *
 * Business context: Moderators require visibility into all community discussion
 * comments, even those removed from public view by soft-deletion for compliance
 * and dispute resolution. This is core for effective community management,
 * enabling restoration or further review if needed.
 *
 * Test procedure:
 *
 * 1. Create a regular member (for authorship)
 * 2. Register a moderator account
 * 3. As the member, create a new post
 * 4. Add several comments (e.g., 3) to the post as the member
 * 5. As the moderator, soft-delete one or more comments via moderator API
 * 6. As the moderator, retrieve the list of all comments
 * 7. Confirm the previously soft-deleted comments are included, and their
 *    `deleted_at` timestamp is present (non-null), while active comments have
 *    `deleted_at: null`
 * 8. Confirm all original comments and their properties (incl. content/post
 *    linkage) are present in the list for audit visibility
 */
export async function test_api_discussionBoard_test_list_all_comments_as_moderator_including_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create a regular member
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Register a moderator (simulate as if privileged by an admin)
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(32),
        is_active: true,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 3. As the member, create a new post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. Add several comments as the member
  const comments = [];
  for (let i = 0; i < 3; ++i) {
    const comment =
      await api.functional.discussionBoard.member.posts.comments.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            body: `Comment #${i + 1} - ${RandomGenerator.paragraph()()}`,
          } satisfies IDiscussionBoardComment.ICreate,
        },
      );
    typia.assert(comment);
    comments.push(comment);
  }

  // 5. Soft-delete one comment as the moderator (~simulate moderator priv)
  const commentToDelete = comments[1];
  await api.functional.discussionBoard.moderator.posts.comments.erase(
    connection,
    {
      postId: post.id,
      commentId: commentToDelete.id,
    },
  );

  // 6. As the moderator, fetch all comments
  const page =
    await api.functional.discussionBoard.moderator.comments.index(connection);
  typia.assert(page);

  // 7. Confirm soft-deleted and active comments
  let foundSoftDeleted = false,
    foundActive = false;
  for (const createdComment of comments) {
    const found = page.data.find((c) => c.id === createdComment.id);
    TestValidator.predicate("Comment must exist in moderator's list")(!!found);
    if (createdComment.id === commentToDelete.id) {
      TestValidator.predicate(
        "Soft-deleted comment must have deleted_at != null",
      )(!!found && found.deleted_at !== null && found.deleted_at !== undefined);
      foundSoftDeleted = true;
    } else {
      TestValidator.equals("Active comment deleted_at is null")(
        found?.deleted_at,
      )(null);
      foundActive = true;
    }
  }
  TestValidator.predicate("Found at least one soft-deleted comment")(
    foundSoftDeleted,
  );
  TestValidator.predicate("Found at least one active comment")(foundActive);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that an administrator can retrieve all comments (active and
 * soft-deleted) for audit and compliance purposes.
 *
 * This test verifies that:
 *
 * - Admin can fetch all comments, both active and soft-deleted (deleted_at not
 *   null)
 * - Audit metadata (discussion_board_post_id, discussion_board_member_id,
 *   deleted_at) is always present for each comment
 * - As admin, all comments across posts are visible regardless of soft-delete
 *   status
 *
 * Steps:
 *
 * 1. Register a system admin (for privilege operations)
 * 2. Register a standard member (who authors content)
 * 3. Create a post as the member
 * 4. Create multiple comments under the post as the member
 * 5. As admin, soft-delete a subset of the comments
 * 6. As admin, list all comments via the admin comments index endpoint
 * 7. Assert that both normal and deleted comments are present with correct state
 *    metadata
 * 8. Confirm that all linkage fields (post, member) are present and valid
 */
export async function test_api_discussionBoard_test_list_all_comments_as_admin_audit_deleted_and_active(
  connection: api.IConnection,
) {
  // 1. Register an admin account
  const adminUsername = RandomGenerator.alphaNumeric(10);
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPasswordHash = RandomGenerator.alphaNumeric(12); // Simulate hash - not plaintext
  const admin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: adminUsername,
        email: adminEmail,
        password_hash: adminPasswordHash,
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(admin);

  // 2. Register a member account
  const memberDisplayName = RandomGenerator.name();
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(13);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Create a post as the member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        parent_id: null,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. Create multiple comments under the post as the member
  const numComments = 4;
  const comments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < numComments; ++i) {
    const comment =
      await api.functional.discussionBoard.member.posts.comments.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            body: `Test comment #${i + 1} - ` + RandomGenerator.paragraph()(12),
            parent_id: null,
          } satisfies IDiscussionBoardComment.ICreate,
        },
      );
    typia.assert(comment);
    comments.push(comment);
  }

  // 5. As admin, soft-delete a subset (half) of the comments
  // We'll delete the first two, and leave the others active
  for (let idx = 0; idx < Math.floor(numComments / 2); ++idx) {
    await api.functional.discussionBoard.admin.posts.comments.erase(
      connection,
      {
        postId: post.id,
        commentId: comments[idx].id,
      },
    );
    // No output/typia.assert needed for void
  }

  // 6. As admin, list all comments
  const allCommentsPage =
    await api.functional.discussionBoard.admin.comments.index(connection);
  typia.assert(allCommentsPage);
  const found = allCommentsPage.data.filter((c) =>
    comments.some((tc) => tc.id === c.id),
  );
  TestValidator.equals("All test comments must be present as admin")(
    found.length,
  )(numComments);

  // 7. Assert deleted/active state reflected correctly
  for (let idx = 0; idx < numComments; ++idx) {
    const stored = allCommentsPage.data.find((c) => c.id === comments[idx].id);
    if (!stored) throw new Error("Comment not found in admin listing");
    // Check linkage
    TestValidator.equals("Link: post ID")(stored.discussion_board_post_id)(
      post.id,
    );
    TestValidator.equals("Link: member ID")(stored.discussion_board_member_id)(
      member.id,
    );
    // Check state
    if (idx < Math.floor(numComments / 2)) {
      // Should be soft-deleted (has deleted_at)
      TestValidator.predicate("Soft-deleted comment has deleted_at > 0")(
        !!stored.deleted_at,
      );
    } else {
      // Should be active (no deleted_at or null)
      TestValidator.equals("Active comment deleted_at is null or missing")(
        stored.deleted_at ?? null,
      )(null);
    }
  }
}

