import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced comment search by post and date range for a discussion
 * board member.
 *
 * This test ensures that members can search for comments attached to a specific
 * post, using the advanced search endpoint with filters for postId and date
 * range. It simulates the workflow by:
 *
 * 1. Registering a new discussion board member.
 * 2. Creating a post via that member.
 * 3. Adding multiple comments to that post, each with a manually set, distinct
 *    created_at date spanning a window.
 * 4. Performing search/paginate queries: a. For a window that includes only some
 *    comments (by manipulating created_from/created_to). b. For the full window
 *    (should get all comments). c. For an empty/outlier range (should yield
 *    empty data).
 * 5. Verifying:
 *
 *    - All returned comments belong to the specified post and fall within the
 *         requested date range.
 *    - Pagination metadata (current, limit, records, pages) is present and accurate.
 *    - No comments outside the date window are returned.
 */
export async function test_api_discussionBoard_test_advanced_search_comments_by_post_id_and_date_range(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const displayName = RandomGenerator.alphaNumeric(10);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: displayName,
        email: memberEmail,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. The member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Add multiple comments to the post, each with a distinct created_at date.
  // We'll use the API, but assume they are inserted at different points in time.
  // For testing, search is based on real timestamps, so we'll get timestamps from created records.
  const now = new Date();
  const isoDates = [
    new Date(now.getTime() - 1000 * 60 * 60 * 24 * 4).toISOString(), // 4 days ago
    new Date(now.getTime() - 1000 * 60 * 60 * 24 * 2).toISOString(), // 2 days ago
    now.toISOString(), // today
  ];
  const comments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 3; ++i) {
    const comment =
      await api.functional.discussionBoard.member.posts.comments.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            body: `Test comment #${i + 1}`,
          } satisfies IDiscussionBoardComment.ICreate,
        },
      );
    typia.assert(comment);
    // Replace created_at with controlled isoDates array
    comment.created_at = isoDates[i];
    comments.push(comment);
  }
  // Sort comments by created_at ascending
  comments.sort((a, b) => a.created_at.localeCompare(b.created_at));

  // 4a. Search for comments from 3 days ago (should only include #2, #3)
  const fromDate = new Date(
    now.getTime() - 1000 * 60 * 60 * 24 * 3,
  ).toISOString();
  const search1 = await api.functional.discussionBoard.member.comments.search(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        created_from: fromDate,
        sort: "created_at_asc",
      } satisfies IDiscussionBoardComment.IRequest,
    },
  );
  typia.assert(search1);
  // Should include only comments 2 and 3
  const expected1 = comments.filter((c) => c.created_at >= fromDate);
  TestValidator.equals("filtered comments by date >= 3 days ago")(
    search1.data.map((x) => x.body).sort(), // actual
  )(
    expected1.map((x) => x.body).sort(), // expected
  );
  // Pagination meta must exist
  TestValidator.predicate("pagination present")(
    typeof search1.pagination.current === "number",
  );

  // 4b. Search for all comments (no from/to) - should get all 3
  const search2 = await api.functional.discussionBoard.member.comments.search(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        sort: "created_at_asc",
      } satisfies IDiscussionBoardComment.IRequest,
    },
  );
  typia.assert(search2);
  TestValidator.equals("all comments bodies")(
    search2.data.map((x) => x.body).sort(),
  )(comments.map((x) => x.body).sort());

  // 4c. Search for future window (should yield empty)
  const futureFrom = new Date(
    now.getTime() + 1000 * 60 * 60 * 24 * 1,
  ).toISOString();
  const search3 = await api.functional.discussionBoard.member.comments.search(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        created_from: futureFrom,
        sort: "created_at_asc",
      } satisfies IDiscussionBoardComment.IRequest,
    },
  );
  typia.assert(search3);
  TestValidator.equals("no comments in future window")(search3.data.length)(0);
}

