import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";

/**
 * Validate that a logged-in member can view the latest edit event for their
 * comment, including after multiple revisions.
 *
 * This test verifies that the comment edit audit trail mechanism works for
 * members:
 *
 * - Register a member and authenticate.
 * - Create a post as this member.
 * - Comment on the post.
 * - Edit the comment multiple times (different bodies, as if revising over time).
 * - Fetch the most recent comment edit event using the member's commentEdits API.
 * - Validate that the returned edit summary:
 *
 *   1. Has the correct editor display name,
 *   2. Refers to the correct comment,
 *   3. The timestamp is after the last edit (chronology).
 *
 * This ensures audit trail and version reference for the comment is
 * functioning.
 */
export async function test_api_discussionBoard_test_list_comment_edit_history_for_existing_comment(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member
  const display_name = RandomGenerator.name();
  const email = typia.random<string & tags.Format<"email">>();
  const password_hash = RandomGenerator.alphaNumeric(32);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name,
        email,
        password_hash,
      },
    },
  );
  typia.assert(member);

  // 2. Create a new post as this member
  const post_title = RandomGenerator.paragraph()();
  const post_body = RandomGenerator.content()()();
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: post_title,
        body: post_body,
      },
    },
  );
  typia.assert(post);

  // 3. Add an initial comment to the post
  const comment =
    await api.functional.discussionBoard.member.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          body: "Initial comment body",
        },
      },
    );
  typia.assert(comment);

  // 4. Edit the comment multiple times
  const edit_bodies = [
    "Edit version 1",
    "Edit version 2",
    "Edit version 3 - final revision!",
  ];
  let last_update_time = comment.updated_at;
  for (const body of edit_bodies) {
    const updated = await api.functional.discussionBoard.member.comments.update(
      connection,
      {
        commentId: comment.id,
        body: {
          body,
        },
      },
    );
    typia.assert(updated);
    TestValidator.equals("comment updated")(updated.body)(body);
    TestValidator.predicate("timestamp should advance")(
      new Date(updated.updated_at) > new Date(last_update_time),
    );
    last_update_time = updated.updated_at;
  }

  // 5. Fetch the latest comment edit summary
  const edit_summary =
    await api.functional.discussionBoard.member.comments.commentEdits.index(
      connection,
      {
        commentId: comment.id,
      },
    );
  typia.assert(edit_summary);

  // 6. Check the summary is for the right comment and editor
  TestValidator.equals("editor display name")(edit_summary.editor_display_name)(
    display_name,
  );
  TestValidator.equals("comment id")(edit_summary.discussion_board_comment_id)(
    comment.id,
  );
  TestValidator.predicate("edit time matches last edit")(
    new Date(edit_summary.edited_at) >= new Date(last_update_time),
  );
}

