 * email_enabled directly influence how and when notifications are delivered to
 * the admin.
 *
 * Steps:
 *
 * 1. Create initial notification settings for the admin using the create endpoint
 *    with all toggles on.
 * 2. Update a specific field (e.g., disable email notifications) via the update
 *    endpoint.
 * 3. Validate that the API returns the record with the updated field as expected
 *    and all unrelated fields unchanged.
 * 4. Assert self-ownership by checking admin_id matches the acting admin.
 */
export async function test_api_discussionBoard_admin_notificationSettings_test_update_notification_setting_as_admin_successfully(
  connection: api.IConnection,
) {
  // Step 1: Create initial notification settings for the admin
