/**
 * Test that an admin cannot update notification settings that belong to another
 * user (including another admin).
 *
 * Business context:
 *
 * - Ensures strict RBAC: admins can only update their own notification settings,
 *   not those of other users (admins, moderators, members, guests).
 * - This test ensures user privacy and prevents privilege escalation or
 *   cross-account tampering.
 *
 * Test workflow:
 *
 * 1. Create an admin account (Target Admin/User who owns the notification setting)
 * 2. As that admin, create a notification setting for themselves (or for another
 *    user). Capture the created notification setting's id.
 * 3. Create a second, unrelated admin account (Acting Admin)
 * 4. Switch to the context/authentication of the Acting Admin
 * 5. Attempt to update the previously created notification setting using the new
 *    admin's credentials.
 * 6. Verify that the update attempt fails with an authorization/forbidden
 *    response. No update should occur and error should be thrown.
 *
 * Edge cases considered:
 *
 * - RBAC/ownership applies to all user types, not just admins.
 * - Update is denied regardless of notification setting content or update
 *   parameters.
 *
 * Implementation note: Actual error message/format is not asserted – focus is
 * on error occurrence (as required by E2E guidelines).
 */
export async function test_api_discussionBoard_test_update_notification_setting_fails_with_unowned_setting(
  connection: api.IConnection,
) {
  // 1. Create the original admin (owner of the notification setting)
  const ownerAdmin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(12),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(ownerAdmin);

  // 2. (Owner admin) creates notification setting for themselves
  // (The notification setting will reference this admin's id)
  const ownerSetting =
    await api.functional.discussionBoard.admin.notificationSettings.create(
      connection,
      {
        body: {
          admin_id: ownerAdmin.id,
          moderator_id: null,
          member_id: null,
          guest_id: null,
          in_app_enabled: true,
          email_enabled: true,
          moderation_notification_enabled: true,
          reply_notification_enabled: false,
          vote_notification_enabled: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      },
    );
  typia.assert(ownerSetting);

  // 3. Create a second unrelated admin (the acting admin who will attempt the update)
  const unrelatedAdmin =
    await api.functional.discussionBoard.admin.admins.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(12),
        is_active: true,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  typia.assert(unrelatedAdmin);

  // 4. Attempt to update the existing notification setting as the unrelated admin
  await TestValidator.error(
    "Non-owner admin cannot update another admin's notification setting",
  )(async () => {
    await api.functional.discussionBoard.admin.notificationSettings.update(
      connection,
      {
        notificationSettingId: ownerSetting.id,
        body: {
          in_app_enabled: false,
        } satisfies IDiscussionBoardNotificationSetting.IUpdate,
      },
    );
  });
}

