/**
 * Test listing of suspension records as a moderator, including all visible
 * records for different subject types and statuses.
 *
 * This test simulates a moderator retrieving a paginated list of all suspension
 * or ban records via the moderation endpoint. It first prepares multiple
 * suspension records with differing subject types (member, guest) and workflow
 * statuses (active, expired, revoked) using the moderator's authority. Then it
 * calls the index endpoint to confirm that the created suspensions are all
 * visible to the moderator as per business rules, and that the returned records
 * contain the correct subject-role and status associations.
 *
 * Steps:
 *
 * 1. Create a suspension for a member with status 'active'
 * 2. Create a suspension for a guest with status 'expired'
 * 3. Create a suspension for a member with status 'revoked'
 * 4. Retrieve the complete list of suspension records as moderator
 * 5. Validate that all created suspensions appear in the list and their properties
 *    match expectations
 */
export async function test_api_discussionBoard_test_list_suspensions_as_moderator_includes_visible_records(
  connection: api.IConnection,
) {
  // 1. Create a suspension for a member (active)
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const suspensionMemberActive =
    await api.functional.discussionBoard.moderator.suspensions.create(
      connection,
      {
        body: {
          suspended_member_id: memberId,
          suspended_admin_id: null,
          suspended_moderator_id: null,
          suspended_guest_id: null,
          admin_id: null,
          moderator_id: typia.random<string & tags.Format<"uuid">>(),
          related_report_id: null,
          related_action_id: null,
          suspended_at: new Date().toISOString(),
          ends_at: null,
          reason: "Active ban for member test",
          status: "active",
        } satisfies IDiscussionBoardSuspension.ICreate,
      },
    );
  typia.assert(suspensionMemberActive);

  // 2. Create a suspension for a guest (expired)
  const guestId: string = typia.random<string & tags.Format<"uuid">>();
  const suspensionGuestExpired =
    await api.functional.discussionBoard.moderator.suspensions.create(
      connection,
      {
        body: {
          suspended_member_id: null,
          suspended_admin_id: null,
          suspended_moderator_id: null,
          suspended_guest_id: guestId,
          admin_id: null,
          moderator_id: typia.random<string & tags.Format<"uuid">>(),
          related_report_id: null,
          related_action_id: null,
          suspended_at: new Date(Date.now() - 86400000).toISOString(), // start 1 day ago
          ends_at: new Date(Date.now() - 3600000).toISOString(), // ended 1 hour ago
          reason: "Expired ban for guest test",
          status: "expired",
        } satisfies IDiscussionBoardSuspension.ICreate,
      },
    );
  typia.assert(suspensionGuestExpired);

  // 3. Create a suspension for a member (revoked)
  const memberIdRevoked: string = typia.random<string & tags.Format<"uuid">>();
  const suspensionMemberRevoked =
    await api.functional.discussionBoard.moderator.suspensions.create(
      connection,
      {
        body: {
          suspended_member_id: memberIdRevoked,
          suspended_admin_id: null,
          suspended_moderator_id: null,
          suspended_guest_id: null,
          admin_id: null,
          moderator_id: typia.random<string & tags.Format<"uuid">>(),
          related_report_id: null,
          related_action_id: null,
          suspended_at: new Date(Date.now() - 172800000).toISOString(), // started 2 days ago
          ends_at: new Date(Date.now() - 86400000).toISOString(), // ended 1 day ago
          reason: "Revoked ban for member test",
          status: "revoked",
        } satisfies IDiscussionBoardSuspension.ICreate,
      },
    );
  typia.assert(suspensionMemberRevoked);

  // 4. Retrieve list of all suspension records
  const page =
    await api.functional.discussionBoard.moderator.suspensions.index(
      connection,
    );
  typia.assert(page);

  // 5. Validate that each of the created suspensions appears in the returned list
  const foundActive = page.data.find((r) => r.id === suspensionMemberActive.id);
  TestValidator.predicate("active member suspension visible")(!!foundActive);
  TestValidator.equals("member id matches")(foundActive?.suspended_member_id)(
    memberId,
  );
  TestValidator.equals("status matches")(foundActive?.status)("active");
  TestValidator.equals("reason matches")(foundActive?.reason)(
    "Active ban for member test",
  );

  const foundExpired = page.data.find(
    (r) => r.id === suspensionGuestExpired.id,
  );
  TestValidator.predicate("expired guest suspension visible")(!!foundExpired);
  TestValidator.equals("guest id matches")(foundExpired?.suspended_guest_id)(
    guestId,
  );
  TestValidator.equals("status matches")(foundExpired?.status)("expired");
  TestValidator.equals("reason matches")(foundExpired?.reason)(
    "Expired ban for guest test",
  );

  const foundRevoked = page.data.find(
    (r) => r.id === suspensionMemberRevoked.id,
  );
  TestValidator.predicate("revoked member suspension visible")(!!foundRevoked);
  TestValidator.equals("member revoked id matches")(
    foundRevoked?.suspended_member_id,
  )(memberIdRevoked);
  TestValidator.equals("status matches")(foundRevoked?.status)("revoked");
  TestValidator.equals("reason matches")(foundRevoked?.reason)(
    "Revoked ban for member test",
  );
}

