 * - The negative test cases deliberately break expected types, enum values, and
 *   format constraints within the error assertion closures in order to simulate
 *   potential frontend or API consumer misuse.
 * - Validates that such bad input results in a 400 Bad Request or validation
 *   error, not a 500 server error, and that raw stack traces or system
 *   internals are NOT exposed.
 *
 * Steps:
 *
 * 1. Send a non-integer (string) as `page` parameter.
 * 2. Pass a random, invalid string for `status` (outside the allowed enum).
 * 3. Use a bogus string for a uuid field (`suspended_member_id`).
 * 4. Supply a clearly invalid date-time string for `suspended_from`.
 * 5. Send a negative integer for `limit` to test numeric range enforcement.
 */
export async function test_api_discussionBoard_test_search_suspensions_with_invalid_query_returns_error(
  connection: api.IConnection,
) {
  // 1. Non-integer page parameter
  await TestValidator.error("page as string triggers validation error")(
    async () => {
      await api.functional.discussionBoard.admin.suspensions.search(
        connection,
        {
          body: {
            page: "pageOne" as any, // invalid: should be int32
          } as any,
        },
      );
    },
  );

  // 2. Invalid status field
  await TestValidator.error("invalid status value triggers error")(async () => {
    await api.functional.discussionBoard.admin.suspensions.search(connection, {
      body: {
        status: "banned" as any, // not one of ['active', 'expired', 'revoked']
      } as any,
    });
