 *
 * This test validates the workflow where:
 *
 * 1. A new member registers
 * 2. The member creates a post
 * 3. The member updates that post (title and body)
 * 4. The returned post reflects the updates, and audit fields are preserved
 *    properly
 *
 * Steps:
 *
 * - Register a new member with valid data
 * - Create a post (top-level, not threaded)
 * - Update the post by id with a new title and body
 * - Validate: updated title/body, unchanged id/author/created_at, updated
 *   updated_at, post is not deleted
 */
export async function test_api_discussionBoard_test_update_own_post_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const passwordHash = RandomGenerator.alphaNumeric(32);

  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);
  TestValidator.equals("display name matches")(member.display_name)(
    memberDisplayName,
  );
  TestValidator.equals("email matches")(member.email)(memberEmail);
  TestValidator.predicate("not verified by default")(!member.is_verified);

  // 2. Create a post as this member
  const originalTitle = RandomGenerator.paragraph()(3, 7);
  const originalBody = RandomGenerator.content()()(2, 10);
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: originalTitle,
        body: originalBody,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);
  TestValidator.equals("author id matches")(post.discussion_board_member_id)(
    member.id,
  );
  TestValidator.equals("initial title matches")(post.title)(originalTitle);
  TestValidator.equals("initial body matches")(post.body)(originalBody);
  TestValidator.predicate("not deleted")(!post.deleted_at);

  // 3. Update the post with new title and body
  const newTitle = RandomGenerator.paragraph()(3, 7);
  const newBody = RandomGenerator.content()()(2, 12);
