  TestValidator.equals("post id unchanged")(updated.id)(post.id);
  TestValidator.equals("author unchanged")(updated.discussion_board_member_id)(
    member.id,
  );
  TestValidator.equals("title updated")(updated.title)(newTitle);
  TestValidator.equals("body updated")(updated.body)(newBody);
  TestValidator.predicate("updated_at increased")(
    updated.updated_at > post.updated_at,
  );
  TestValidator.equals("created_at stable")(updated.created_at)(
    post.created_at,
  );
  TestValidator.predicate("still not deleted")(!updated.deleted_at);
}

