 * regardless of authentication, except as allowed by business rules (such as
 * showing soft-deleted tags only to privileged roles).
 *
 * Steps:
 *
 * 1. As admin, create a discussion board tag — dependency fulfillment: make sure
 *    at least one tag exists.
 * 2. As guest (unauthenticated), call the tags index endpoint and record visible
 *    tags.
 * 3. As member (authenticated), call the tags index endpoint and record visible
 *    tags.
 * 4. Verify that both lists are equivalent, ignoring soft-deleted tags (deleted_at
 *    not set).
 */
export async function test_api_discussionBoard_test_member_can_list_all_tags(
  connection: api.IConnection,
) {
  // 1. Create a tag as admin
  const tagInput: IDiscussionBoardTag.ICreate = {
    label: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(),
    color: "#" + Math.floor(Math.random() * 16777215).toString(16),
