  // 2. Simulate a guest (unauthenticated) by removing Authorization header
  const guestConnection = { ...connection, headers: { ...connection.headers } };
  delete guestConnection.headers["Authorization"];

  const guestTags: IPageIDiscussionBoardTag =
    await api.functional.discussionBoard.tags.index(guestConnection);
