/**
 * Test the admin search functionality for including soft-deleted tags.
 *
 * This test verifies that an admin can retrieve both active and soft-deleted
 * tag records by using the `include_deleted` search filter. It covers the
 * following workflow:
 *
 * 1. Create multiple discussion board tags (at least two), each with a distinct
 *    label.
 * 2. Soft-delete one of the created tags (verify that the deleted_at timestamp is
 *    set).
 * 3. Search for tags with `include_deleted = true` and assert that both deleted
 *    and non-deleted tags are included in the results.
 * 4. Search with `include_deleted = false` (or omitted) and assert that only
 *    non-deleted tags appear in the results.
 * 5. Explicitly search for deleted tags using label match and `include_deleted =
 *    true`, and check that the soft-deleted tag is surfaced (and its deleted_at
 *    is non-null).
 *
 * This ensures proper functioning of tag admin inventory, and that the system
 * state of soft deletions is correctly reflected in search with appropriate
 * filters.
 */
export async function test_api_discussionBoard_admin_tags_test_admin_can_include_soft_deleted_tags_in_results(
  connection: api.IConnection,
) {
  // 1. Create two unique tags
  const labelA = RandomGenerator.alphabets(12);
  const tagA = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: labelA,
        description: RandomGenerator.paragraph()(),
        color: "#3399ff",
      },
    },
  );
  typia.assert(tagA);
  TestValidator.equals("tagA label round-trip")(tagA.label)(labelA);

  const labelB = RandomGenerator.alphabets(12);
  const tagB = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: labelB,
        description: RandomGenerator.paragraph()(),
        color: "#dd5522",
      },
    },
  );
  typia.assert(tagB);
  TestValidator.equals("tagB label round-trip")(tagB.label)(labelB);

  // 2. Soft-delete tagB
  await api.functional.discussionBoard.admin.tags.erase(connection, {
    tagId: tagB.id,
  });

  // 3. Search for tags with include_deleted = true (should include both tags)
  const searchWithDeleted =
    await api.functional.discussionBoard.admin.tags.search(connection, {
      body: {
        include_deleted: true,
        label: null,
        page: 1,
        limit: 100,
        created_from: null,
        created_to: null,
      },
    });
  typia.assert(searchWithDeleted);

  const tagIds = searchWithDeleted.data.map((t) => t.id);
  TestValidator.predicate("contains both created and deleted tags")(
    tagIds.includes(tagA.id) && tagIds.includes(tagB.id),
  );

  // Verify deleted state in result for tagB
  const softDeletedTag = searchWithDeleted.data.find((t) => t.id === tagB.id);
  TestValidator.predicate("deleted_at is set for soft-deleted tag")(
    !!softDeletedTag?.deleted_at,
  );

  const activeTag = searchWithDeleted.data.find((t) => t.id === tagA.id);
  TestValidator.equals("active tag is not soft-deleted")(activeTag?.deleted_at)(
    null,
  );

  // 4. Search for tags with include_deleted = false (should only include non-deleted tag)
  const searchWithoutDeleted =
    await api.functional.discussionBoard.admin.tags.search(connection, {
      body: {
        include_deleted: false,
        label: null,
        page: 1,
        limit: 100,
        created_from: null,
        created_to: null,
      },
    });
  typia.assert(searchWithoutDeleted);
  const nonDeletedIds = searchWithoutDeleted.data.map((t) => t.id);
  TestValidator.predicate("non-deleted tags only in result")(
    nonDeletedIds.includes(tagA.id) && !nonDeletedIds.includes(tagB.id),
  );

  // 5. Search by label for the soft-deleted tag and include_deleted: true
  const searchOnlyDeleted =
    await api.functional.discussionBoard.admin.tags.search(connection, {
      body: {
        include_deleted: true,
        label: tagB.label,
        page: 1,
        limit: 100,
        created_from: null,
        created_to: null,
      },
    });
  typia.assert(searchOnlyDeleted);
  const foundTag = searchOnlyDeleted.data.find((t) => t.id === tagB.id);
  TestValidator.predicate("found deleted tag by label")(!!foundTag);
  TestValidator.predicate("deleted tag has deleted_at set")(
    !!foundTag?.deleted_at,
  );
}

