/**
 * Validate that an admin (Admin B) who is not the original editor of a post
 * edit event CANNOT update that event, unless they have explicit
 * permissions/override roles.
 *
 * This test ensures such an update is forbidden, enforcing edit-ownership
 * restrictions.
 *
 * Step-by-step process:
 *
 * 1. Register a member (for post authorship).
 * 2. Register Admin A (the original post editor).
 * 3. Register Admin B (who will attempt the unauthorized update).
 * 4. Member creates a new post.
 * 5. Admin A creates a post edit event (on that post).
 * 6. Attempt to update _that_ post edit event as Admin B (who does not have
 *    moderator/override privileges).
 * 7. Confirm the update attempt is forbidden and returns an error.
 */
export async function test_api_discussionBoard_test_forbid_post_edit_update_by_non_editor_admin(
  connection: api.IConnection,
) {
  // 1. Register a member - for post authorship
  const memberEmail = typia.random<string & tags.Format<"email">>();
