      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPassword,
      },
    },
  );
  typia.assert(member);

  // 2. Register Admin A (original editor)
  const adminAEmail = typia.random<string & tags.Format<"email">>();
  const adminAUsername = RandomGenerator.alphabets(8);
  const adminAPassword = RandomGenerator.alphaNumeric(10);
  const adminA = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: adminAUsername,
        email: adminAEmail,
        password_hash: adminAPassword,
        is_active: true,
      },
    },
  );
  typia.assert(adminA);

  // 3. Register Admin B (not the original editor)
  const adminBEmail = typia.random<string & tags.Format<"email">>();
  const adminBUsername = RandomGenerator.alphabets(8);
  const adminBPassword = RandomGenerator.alphaNumeric(10);
  const adminB = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: adminBUsername,
        email: adminBEmail,
        password_hash: adminBPassword,
        is_active: true,
      },
    },
  );
  typia.assert(adminB);

  // 4. Member creates a new post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 5. Admin A creates a post edit event
  // NOTE: Business logic expects editor to be a member; we use the member id for test
  const editEvent =
    await api.functional.discussionBoard.admin.posts.postEdits.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_member_id: member.id,
          new_title: RandomGenerator.paragraph()(),
          new_body: RandomGenerator.content()()(),
          edited_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
          rationale: "Typo correction",
        },
      },
    );
