    api.functional.discussionBoard.admin.boardSettings.create(connection, {
      body: {
        title: "General Discussion",
        enabled: false,
        description: "Random conversations",
        logo_uri: null,
      },
    }),
    api.functional.discussionBoard.admin.boardSettings.create(connection, {
      body: {
        title: "Announcements",
        enabled: true,
        description: "Official news and announcements",
        logo_uri: null,
      },
    }),
  ]);
  records.forEach((record) => typia.assert(record));

  // Step 2. Title substring search (case-insensitive)
  {
    const output =
      await api.functional.discussionBoard.admin.boardSettings.search(
        connection,
        {
          body: {
            title: "support",
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("Title filter matches only records with substring")(
      output.data.every((row) => row.title.toLowerCase().includes("support")),
    );
  }

  // Step 3. Enabled status filtering
  {
    const output =
      await api.functional.discussionBoard.admin.boardSettings.search(
        connection,
        {
          body: {
            enabled: false,
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("Enabled filter matches only disabled records")(
      output.data.every((row) => row.enabled === false),
    );
  }

  // Step 4. Created_at date range filtering (using a known created_at)
  {
    // For real implementation: use specific dates; here, pick from created record
    const from = records[0].created_at;
    const output =
      await api.functional.discussionBoard.admin.boardSettings.search(
        connection,
        {
          body: {
            created_at_from: from,
            created_at_to: from,
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("Created_at exact match")(
      output.data.every(
        (row) => row.created_at >= from && row.created_at <= from,
      ),
    );
  }

  // Step 5. Combined criteria (title + enabled)
  {
    const output =
      await api.functional.discussionBoard.admin.boardSettings.search(
        connection,
        {
          body: {
            title: "announce",
            enabled: true,
          },
        },
      );
    typia.assert(output);
    TestValidator.predicate("Combined filter matches both title and enabled")(
      output.data.every(
        (row) =>
          row.title.toLowerCase().includes("announce") && row.enabled === true,
      ),
    );
  }

  // Step 6. Pagination logic (limit 1, page 2)
  {
    const output =
      await api.functional.discussionBoard.admin.boardSettings.search(
        connection,
        {
          body: {
            page: 2,
            limit: 1,
          },
        },
      );
    typia.assert(output);
    TestValidator.equals("Pagination page")(output.pagination.current)(2);
    TestValidator.equals("Pagination limit")(output.pagination.limit)(1);
    TestValidator.predicate("Only one record is returned")(
      output.data.length === 1,
    );
  }
}

