import type { IDiscussionBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostTag";

/**
 * Validate that a member who authored a post can remove a tag from their own
 * post.
 *
 * This test ensures permission and workflow correctness in tag removal logic
 * for post authors. It confirms that only the post author (who is a member) can
 * remove a tag from their post, and upon successful removal, the association
 * between the post and the tag is deleted—the tag will no longer appear in
 * queries for the post, and there is no lingering post-tag assignment.
 *
 * Test Workflow:
 *
 * 1. Register a discussion board member (author).
 * 2. Create a new post as this member (simulating logged-in context).
 * 3. As an admin, create a unique tag to assign to the post—admin rights required
 *    for tag creation.
 * 4. Log in as the member again (if needed), assign the newly created tag to the
 *    new post.
 * 5. Attempt to delete the post-tag association as the author.
 * 6. (For verification) Check that the tag is no longer associated with the post
 *    (by successfully re-adding it, confirming the new association differs from
 *    the erased one).
 *
 * Note: Sequence switches from member (for registration/posting) to admin (for
 * tag creation) and back to member for tag assignment and removal actions. If
 * separate authentication or connection objects were provided for admin/member,
 * those would be used at the relevant steps.
 */
export async function test_api_discussionBoard_test_remove_post_tag_as_post_author_with_valid_permissions(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member (author)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = RandomGenerator.alphaNumeric(32); // Simulate hashed password
  const displayName = RandomGenerator.name();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: displayName,
        email: memberEmail,
        password_hash: passwordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new post as this member (simulate logged-in context)
  // (Assume connection impersonates the member)
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. As admin, create a tag (simulate admin context; in real test infra you would switch connection)
  const adminTag = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
        color: "#" + Math.floor(Math.random() * 16777215).toString(16),
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(adminTag);

  // 4. (Switch back to member connection if needed) Assign the tag to the post as author
  const postTag =
    await api.functional.discussionBoard.member.posts.postTags.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_tag_id: adminTag.id,
        } satisfies IDiscussionBoardPostTag.ICreate,
      },
    );
  typia.assert(postTag);

  // 5. Attempt to erase the post-tag association as post author
  await api.functional.discussionBoard.member.posts.postTags.erase(connection, {
    postId: post.id,
    postTagId: postTag.id,
  });

  // 6. Attempt to re-assign the same tag to ensure it's no longer associated (should not get dupe error)
  const postTagAgain =
    await api.functional.discussionBoard.member.posts.postTags.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_tag_id: adminTag.id,
        } satisfies IDiscussionBoardPostTag.ICreate,
      },
    );
  typia.assert(postTagAgain);
  // Validate the newly created association is different from the erased one
  TestValidator.notEquals("new post-tag assignment after removal")(
    postTagAgain.id,
  )(postTag.id);
}

