import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate that deleting a non-existent post-tag association (postTagId) for an
 * existing post returns an error.
 *
 * Business context: Proper authorization and error feedback must be
 * maintained—if a user attempts to delete a tag assignment that does not exist
 * for a particular post (postTagId is invalid for the post), the system must
 * respond with a not-found or business error rather than falsely indicating
 * success. This ensures data integrity and accurate audit trails.
 *
 * Steps:
 *
 * 1. Create a discussion board member (register user).
 * 2. As the created member, create a post (acquire postId).
 * 3. Attempt to delete a post-tag association on the post using a
 *    random/non-existent postTagId.
 * 4. Assert that an error is thrown (e.g., not-found) during tag association
 *    deletion.
 * 5. No further resource cleanup or verification is needed since this is an
 *    error-path scenario.
 */
export async function test_api_discussionBoard_test_remove_nonexistent_post_tag_returns_not_found(
  connection: api.IConnection,
) {
  // 1. Create a member to act as post author
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a post as the new member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        parent_id: null,
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Attempt deletion with random/non-existent postTagId
  const bogusPostTagId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Erase with nonexistent postTagId should fail")(
    () =>
      api.functional.discussionBoard.member.posts.postTags.erase(connection, {
        postId: post.id,
        postTagId: bogusPostTagId,
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostTag";

/**
 * Test removal of a tag from a post fails if the post has been soft deleted.
 *
 * This test verifies that the API prohibits removing a tag association from a
 * discussion board post if that post has already been soft deleted. The test
 * ensures that business rules regarding restrictions on operations on
 * soft-deleted content are enforced.
 *
 * Workflow:
 *
 * 1. Register a new member (for posting)
 * 2. Create a new post as the member
 * 3. Create a tag as admin (for assignment)
 * 4. As member, assign the tag to their post
 * 5. As member, soft-delete the post
 * 6. Attempt removal of the post-tag association (should fail)
 *
 * The expected outcome is that the tag removal in step 6 returns an error due
 * to post deletion. The test asserts API error handling via
 * TestValidator.error.
 */
export async function test_api_discussionBoard_test_remove_post_tag_on_deleted_post_returns_error(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphabets(32);
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new post as the member (assume connection reflects member)
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Create a tag as admin (assume connection has admin privileges for this step)
  const tag = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph()(),
        color: null,
      } satisfies IDiscussionBoardTag.ICreate,
    },
  );
  typia.assert(tag);

  // 4. Assign the tag to the post as member
  const postTag =
    await api.functional.discussionBoard.member.posts.postTags.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_tag_id: tag.id,
        } satisfies IDiscussionBoardPostTag.ICreate,
      },
    );
  typia.assert(postTag);

  // 5. Soft-delete the post as member
  await api.functional.discussionBoard.member.posts.erase(connection, {
    postId: post.id,
  });

  // 6. Attempt to remove the tag association (expect error)
  await TestValidator.error("cannot remove tag from soft-deleted post")(() =>
    api.functional.discussionBoard.member.posts.postTags.erase(connection, {
      postId: post.id,
      postTagId: postTag.id,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
