/**
 * Test that a moderator can remove a tag from any post, regardless of
 * authorship.
 *
 * This test ensures that the tag removal permissions for moderators override
 * post authorship. The test simulates the following workflow:
 *
 * 1. Register a member (who will author the post)
 * 2. The member creates a post
 * 3. An admin creates a tag
 * 4. As the author, assign the tag to the post
 * 5. An admin creates a moderator account
 * 6. Remove the post-tag using moderator privileges
 *
 * Preconditions:
 *
 * - The system supports basic member and moderator creation flows
 * - Moderators can manage tag assignments for any post
 * - Only schema-documented API endpoints are to be used
 *
 * Steps:
 *
 * 1. Create a member using api.functional.discussionBoard.members.create
 * 2. Using member (assume authentication by member creation), create a post via
 *    api.functional.discussionBoard.member.posts.create
 * 3. As admin, create a tag using api.functional.discussionBoard.admin.tags.create
 * 4. As the member, assign the newly created tag to the post using
 *    api.functional.discussionBoard.member.posts.postTags.create
 * 5. As admin, create a moderator account using
 *    api.functional.discussionBoard.admin.moderators.create
 * 6. As moderator, call
 *    api.functional.discussionBoard.moderator.posts.postTags.erase to remove
 *    the post-tag association
 *
 * This test verifies that moderator roles are able to remove any post-tag link,
 * and that the permission boundary between normal members and moderators is
 * enforced appropriately.
 */
export async function test_api_discussionBoard_test_moderator_remove_post_tag_succeeds(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(24); // Simulate a password hash
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      },
    },
  );
  typia.assert(member);

  // 2. (Assume member is authenticated, as no explicit login endpoint) Create a post as the member
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 3. Create a tag as admin
  const tag = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
        color: "#FF7700",
      },
    },
  );
  typia.assert(tag);

  // 4. Assign the tag to the post as the author
  const postTag =
    await api.functional.discussionBoard.member.posts.postTags.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_tag_id: tag.id,
        },
      },
    );
  typia.assert(postTag);

  // 5. Create a moderator account as admin
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPasswordHash = RandomGenerator.alphaNumeric(28); // Simulate a password hash
  const moderatorUsername = RandomGenerator.alphaNumeric(10);
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        username: moderatorUsername,
        password_hash: moderatorPasswordHash,
        email: moderatorEmail,
        is_active: true,
      },
    });
  typia.assert(moderator);

  // 6. Remove the post-tag association as the moderator
  await api.functional.discussionBoard.moderator.posts.postTags.erase(
    connection,
    {
      postId: post.id,
      postTagId: postTag.id,
    },
  );
}

