import type { IDiscussionBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostTag";

/**
 * E2E test: Admin removes a tag association from a member's post
 *
 * Validates that an administrator, regardless of who authored the post or the
 * current status of the post (provided the post exists and is not
 * soft-deleted), can remove any tag association from any post. This covers
 * business requirements for admin-privileged management of board taxonomy.
 *
 * Step-by-step process:
 *
 * 1. Create a new admin (with unique username/email/hash).
 * 2. Create a new member (distinct from the admin).
 * 3. Member creates a post.
 * 4. Admin creates a tag (label, etc).
 * 5. Member assigns the tag to the post (creates the post-tag association).
 * 6. Admin deletes the post-tag association via the admin delete endpoint.
 * 7. Validate the deletion: confirm that the tag association is removed (by
 *    attempting double deletion expecting an error, as no get/list API is
 *    defined).
 */
export async function test_api_discussionBoard_test_admin_remove_post_tag_from_any_post(
  connection: api.IConnection,
) {
  // 1. Create a new admin
  const adminUsername = RandomGenerator.alphaNumeric(12);
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPasswordHash = RandomGenerator.alphaNumeric(24);
  const admin = await api.functional.discussionBoard.admin.admins.create(
    connection,
    {
      body: {
        username: adminUsername,
        email: adminEmail,
        password_hash: adminPasswordHash,
        is_active: true,
      },
    },
  );
  typia.assert(admin);

  // 2. Create a member
  const memberDisplayName = RandomGenerator.alphaNumeric(10);
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphaNumeric(20);
  const member = await api.functional.discussionBoard.members.create(
    connection,
    {
      body: {
        display_name: memberDisplayName,
        email: memberEmail,
        password_hash: memberPasswordHash,
      },
    },
  );
  typia.assert(member);

  // 3. Member creates a post
  const postTitle = RandomGenerator.paragraph()(1);
  const postBody = RandomGenerator.content()(1)();
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: postTitle,
        body: postBody,
      },
    },
  );
  typia.assert(post);

  // 4. Admin creates a tag
  const tagLabel = RandomGenerator.alphaNumeric(8);
  const tagDescription = RandomGenerator.paragraph()(1);
  const tagColor = "#" + RandomGenerator.alphaNumeric(6);
  const tag = await api.functional.discussionBoard.admin.tags.create(
    connection,
    {
      body: {
        label: tagLabel,
        description: tagDescription,
        color: tagColor,
      },
    },
  );
  typia.assert(tag);

  // 5. Member assigns the tag to the post
  const postTag =
    await api.functional.discussionBoard.member.posts.postTags.create(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_post_id: post.id,
          discussion_board_tag_id: tag.id,
        },
      },
    );
  typia.assert(postTag);

  // 6. Admin deletes the tag association
  await api.functional.discussionBoard.admin.posts.postTags.erase(connection, {
    postId: post.id,
    postTagId: postTag.id,
  });

  // 7. Validate deletion by re-attempting delete, expecting error
  await TestValidator.error("Should be already deleted")(() =>
    api.functional.discussionBoard.admin.posts.postTags.erase(connection, {
      postId: post.id,
      postTagId: postTag.id,
    }),
  );
}

