import type { IDiscussionBoardPostCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostCategory";
import type { IPageIDiscussionBoardPostCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search, filtering, and pagination of post-category
 * assignments for a member's post.
 *
 * This test ensures that the API supports returning only category assignments
 * matching specific filters—such as filtering by assigned category or
 * paginating the assignments list.
 *
 * Steps:
 *
 * 1. Create a test member
 * 2. Register a new post as that member
 * 3. Create multiple categories as admin
 * 4. Assign all created categories to the member's post
 * 5. Use PATCH to search category assignments for that post using different
 *    filters: a. Filter by a specific category (discussion_board_category_id)
 *    b. Paginate using page/limit
 * 6. Verify that returned assignments match the filters and have correct
 *    pagination
 */
export async function test_api_discussionBoard_test_advanced_search_post_categories_by_member(
  connection: api.IConnection,
) {
  // 1. Create a test member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);

  // 2. Member creates a post
  const post: IDiscussionBoardPost =
    await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
      } satisfies IDiscussionBoardPost.ICreate,
    });
  typia.assert(post);

  // 3. Create multiple categories as admin
  const categoryNames = [
    RandomGenerator.alphabets(8),
    RandomGenerator.alphabets(7),
    RandomGenerator.alphabets(6),
  ];
  const categories = await Promise.all(
    categoryNames.map(async (name) => {
      const category =
        await api.functional.discussionBoard.admin.categories.create(
          connection,
          {
            body: {
              name,
              description: RandomGenerator.paragraph()(2),
            } satisfies IDiscussionBoardCategory.ICreate,
          },
        );
      typia.assert(category);
      return category;
    }),
  );

  // 4. Assign all categories to the post
  const assignments = await Promise.all(
    categories.map(async (cat) => {
      const assignment =
        await api.functional.discussionBoard.member.posts.postCategories.create(
          connection,
          {
            postId: post.id,
            body: {
              discussion_board_post_id: post.id,
              discussion_board_category_id: cat.id,
            } satisfies IDiscussionBoardPostCategory.ICreate,
          },
        );
      typia.assert(assignment);
      return assignment;
    }),
  );

  // 5a. Search assignments filtered by a specific category
  const filterCategory = categories[1];
  const filteredResponse =
    await api.functional.discussionBoard.member.posts.postCategories.search(
      connection,
      {
        postId: post.id,
        body: {
          discussion_board_category_id: filterCategory.id,
        } satisfies IDiscussionBoardPostCategory.IRequest,
      },
    );
  typia.assert(filteredResponse);
  TestValidator.predicate("Only matching category assignments returned")(
    filteredResponse.data.every(
      (a) => a.discussion_board_category_id === filterCategory.id,
    ),
  );
  TestValidator.predicate("All assignments are for the correct post")(
    filteredResponse.data.every((a) => a.discussion_board_post_id === post.id),
  );
  TestValidator.predicate("Pagination record count >= result length")(
    filteredResponse.pagination.records >= filteredResponse.data.length,
  );

  // 5b. Paginate assignments (limit = 2)
  const paginationResponse =
    await api.functional.discussionBoard.member.posts.postCategories.search(
      connection,
      {
        postId: post.id,
        body: {
          limit: 2,
          page: 1,
        } satisfies IDiscussionBoardPostCategory.IRequest,
      },
    );
  typia.assert(paginationResponse);
  TestValidator.equals("Returned page number is 1")(
    paginationResponse.pagination.current,
  )(1);
  TestValidator.equals("Pagination limit is 2")(
    paginationResponse.pagination.limit,
  )(2);
  TestValidator.predicate("Page contains max 2 items")(
    paginationResponse.data.length <= 2,
  );
  TestValidator.predicate("Assignments belong to the correct post")(
    paginationResponse.data.every(
      (a) => a.discussion_board_post_id === post.id,
    ),
  );
}

