import { ForbiddenException } from "@nestjs/common";

import { MyGlobal } from "../../MyGlobal";
import { jwtAuthorize } from "./jwtAuthorize";
import { MemberPayload } from "../../decorators/payload/MemberPayload";

/**
 * Authorize a member by verifying JWT token and ensuring the member exists and is active.
 * @param request Express-like request object containing the authorization header.
 * @returns MemberPayload of the authenticated member.
 * @throws ForbiddenException if JWT, type, or actor database validation fails.
 */
export async function memberAuthorize(request: {
  headers: {
    authorization?: string;
  };
}): Promise<MemberPayload> {
  const payload: MemberPayload = jwtAuthorize({ request }) as MemberPayload;

  if (payload.type !== "member") {
    throw new ForbiddenException(`You're not ${payload.type}`);
  }

  // Validate member existence and permission status (status must NOT be 'banned', 'suspended', or similar, and soft deletes)
  const member = await MyGlobal.prisma.discussion_board_members.findFirst({
    where: {
      id: payload.id,
      // Allow only accounts that are NOT banned (status is not 'banned'), not soft deleted (no deleted_at column), etc.
      // Here only status column is available and soft delete is not implemented via nullable timestamp on this model.
      // By spec, only status disables member.
      NOT: [
        { status: "banned" },
        { status: "suspended" }
      ]
    },
  });

  if (member === null) {
    throw new ForbiddenException("You're not enrolled or your account is disabled.");
  }

  return payload;
}

