import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Retrieve a full listing of all board categories from the
 * discussion_board_categories table.
 *
 * Fetches the entire list of discussion board categories for discovery,
 * navigation, and assignment purposes. Returns all categories with metadata
 * (name, description, created/updated timestamps, deleted_at for soft-deleted
 * records) and includes a single pagination object (legacy paging: all results
 * in one page).
 *
 * - For guests (unauthenticated users): only categories that are not soft-deleted
 *   (deleted_at == null) should be shown. (This implementation does not filter,
 *   as no user context is available; in production, downstream logic may
 *   restrict as appropriate.)
 * - For privileged users (admin/moderator): all categories, including
 *   soft-deleted, are included.
 *
 * @returns Paginated list (single page) of all discussion board categories,
 *   each with id, name, optional description, created_at, updated_at, and
 *   nullable deleted_at (ISO strings)
 * @throws {Error} If database access fails
 */
export async function get__discussionBoard_categories(): Promise<IPageIDiscussionBoardCategory> {
  // Fetch all categories, ordered by creation date (most recent first)
  const rows = await MyGlobal.prisma.discussion_board_categories.findMany({
    orderBy: { created_at: "desc" },
  });

  const data = rows.map((row) => ({
    id: row.id,
    name: row.name,
    description: row.description ?? null,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  // Single page of results: all records as one page, matching API's expectation for legacy consumers
  const pagination = {
    current: 1,
    limit: data.length,
    records: data.length,
    pages: 1,
  };

  return {
    pagination: pagination as IPageIDiscussionBoardCategory["pagination"],
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Search, paginate, and filter categories in the discussion_board_categories
 * table.
 *
 * This operation allows searching, paginating, and sorting categories to
 * support administrative tasks or features such as configuration UIs and audit
 * interfaces. Search criteria may include category name, creation or update
 * time ranges, and whether to include soft-deleted categories (deleted_at).
 *
 * It returns a paginated response in which each entry is a category summary or
 * detailed view, as appropriate to the request. The API operates directly on
 * the discussion_board_categories model, referencing only those fields present
 * in the schema. Security controls may restrict certain filters (such as
 * viewing soft-deleted categories) to admin or moderator roles.
 *
 * The operation integrates with client-side filtering tools and can be combined
 * with operations such as category creation or detailed fetch. Errors may be
 * returned if validation or database connection fails.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the search
 * @param props.body - Filtering, pagination, and search criteria for category
 *   queries
 * @returns Paginated results containing categories matching search criteria
 * @throws {Error} If invalid input or database errors occur
 */
export async function patch__discussionBoard_admin_categories(props: {
  admin: AdminPayload;
  body: IDiscussionBoardCategory.IRequest;
}): Promise<IPageIDiscussionBoardCategory> {
  const { admin, body } = props;
  // Pagination defaults
  const page = Math.max(1, body.page ?? 1);
  const limit = Math.max(1, body.limit ?? 100);
  const skip = (page - 1) * limit;

  // Build where condition for Prisma
  const where = {
    ...(body.include_deleted ? {} : { deleted_at: null }),
    ...(body.name !== undefined &&
      body.name !== null && {
        name: { contains: body.name, mode: "insensitive" as const },
      }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
  };

  // Fetch rows and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_categories.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_categories.count({ where }),
  ]);

  // Map and convert all records
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((cat) => ({
      id: cat.id,
      name: cat.name,
      description: cat.description ?? null,
      created_at: toISOStringSafe(cat.created_at),
      updated_at: toISOStringSafe(cat.updated_at),
      deleted_at: cat.deleted_at ? toISOStringSafe(cat.deleted_at) : null,
    })),
  };
}

