/**
 * Update a discussion board tag by its ID (Admin-only).
 *
 * Allows an admin to update a tag's label, description, or color (only fields
 * supplied in body). Skips fields not present; fields set to null are cleared.
 * Only updates a tag that exists and is not soft-deleted. Always updates
 * updated_at; returns the complete updated tag record.
 *
 * @param props - Function parameters
 * @param props.admin - The authenticated admin issuing the request
 * @param props.tagId - The uuid of the tag to update
 * @param props.body - The tag fields to update (label, description, color).
 *   Null clears field, undefined skips.
 * @returns The updated tag
 * @throws {Error} Tag not found (if id not found or tag is soft-deleted)
 * @throws {Error} If updated label would conflict with another tag (label must
 *   be unique)
 */
export async function put__discussionBoard_admin_tags_$tagId(props: {
  admin: AdminPayload;
  tagId: string & tags.Format<"uuid">;
  body: IDiscussionBoardTag.IUpdate;
}): Promise<IDiscussionBoardTag> {
  const { tagId, body } = props;

  // Ensure tag exists and is not soft-deleted
  const tag = await MyGlobal.prisma.discussion_board_tags.findFirst({
    where: { id: tagId, deleted_at: null },
  });
  if (!tag) throw new Error("Tag not found");

  try {
    const updated = await MyGlobal.prisma.discussion_board_tags.update({
      where: { id: tagId },
      data: {
        label: body.label ?? undefined,
        description: body.description ?? undefined,
        color: body.color ?? undefined,
        updated_at: toISOStringSafe(new Date()),
      },
    });
    return {
      id: updated.id,
      label: updated.label,
      description: updated.description,
      color: updated.color,
      created_at: toISOStringSafe(updated.created_at),
      updated_at: toISOStringSafe(updated.updated_at),
      deleted_at: updated.deleted_at
        ? toISOStringSafe(updated.deleted_at)
        : null,
    };
  } catch (err) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002" &&
      Array.isArray(err.meta?.target) &&
      err.meta.target.includes("label")
    ) {
      throw new Error("A tag with this label already exists");
    }
    throw err;
  }
}

