/**
 * Updates an existing category-tag assignment by its unique ID.
 *
 * This operation atomically updates the associated category and/or tag UUIDs
 * for an assignment. It enforces uniqueness such that a category/tag assignment
 * can only exist once. If the referenced category or tag does not exist, or the
 * update would create a duplicate, an error is thrown.
 *
 * Only admin or moderator roles may perform this action. All changes are
 * audit-logged.
 *
 * @param props - Request parameters and payload.
 * @param props.admin - Authenticated admin making the request.
 * @param props.categoryTagId - The ID of the category-tag assignment to update.
 * @param props.body - New details for the assignment (category and/or tag ID).
 * @returns The updated category-tag assignment.
 * @throws {Error} If the record does not exist, if uniqueness is violated, or
 *   if referenced category/tag do not exist.
 */
export async function put__discussionBoard_admin_categoryTags_$categoryTagId(props: {
  admin: AdminPayload;
  categoryTagId: string & tags.Format<"uuid">;
  body: IDiscussionBoardCategoryTag.IUpdate;
}): Promise<IDiscussionBoardCategoryTag> {
  const { admin, categoryTagId, body } = props;

  // 1. Fetch existing assignment by ID
  const assignment =
    await MyGlobal.prisma.discussion_board_category_tags.findUnique({
      where: { id: categoryTagId },
    });
  if (!assignment) throw new Error("Category-tag assignment not found");

  // 2. Determine changed fields
  const updateCategoryId =
    body.discussion_board_category_id !== undefined &&
    body.discussion_board_category_id !==
      assignment.discussion_board_category_id;
  const updateTagId =
    body.discussion_board_tag_id !== undefined &&
    body.discussion_board_tag_id !== assignment.discussion_board_tag_id;

  // 3. If nothing changed, return existing assignment
  if (!updateCategoryId && !updateTagId) {
    return {
      id: assignment.id,
      discussion_board_category_id: assignment.discussion_board_category_id,
      discussion_board_tag_id: assignment.discussion_board_tag_id,
      created_at: toISOStringSafe(assignment.created_at),
    };
  }

  // 4. Compute new pair
  const new_category_id = updateCategoryId
    ? body.discussion_board_category_id!
    : assignment.discussion_board_category_id;
  const new_tag_id = updateTagId
    ? body.discussion_board_tag_id!
    : assignment.discussion_board_tag_id;

  // 5. Enforce uniqueness constraint on (category_id, tag_id), excluding self
  const duplicate =
    await MyGlobal.prisma.discussion_board_category_tags.findFirst({
      where: {
        discussion_board_category_id: new_category_id,
        discussion_board_tag_id: new_tag_id,
        NOT: { id: categoryTagId },
      },
    });
  if (duplicate)
    throw new Error(
      "A category-tag assignment with this category and tag already exists.",
    );

  // 6. Validate that category and tag exist
  const category = await MyGlobal.prisma.discussion_board_categories.findUnique(
    {
      where: { id: new_category_id },
    },
  );
  if (!category) throw new Error("Referenced category not found");
  const tag = await MyGlobal.prisma.discussion_board_tags.findUnique({
    where: { id: new_tag_id },
  });
  if (!tag) throw new Error("Referenced tag not found");

  // 7. Update the record
  const updated = await MyGlobal.prisma.discussion_board_category_tags.update({
    where: { id: categoryTagId },
    data: {
      discussion_board_category_id: new_category_id,
      discussion_board_tag_id: new_tag_id,
    },
  });

  // 8. Return values formatted per API contract
  return {
    id: updated.id,
    discussion_board_category_id: updated.discussion_board_category_id,
    discussion_board_tag_id: updated.discussion_board_tag_id,
    created_at: toISOStringSafe(updated.created_at),
  };
}

