 */
export async function patch__discussionBoard_admin_boardSettings(props: {
  admin: AdminPayload;
  body: IDiscussionBoardBoardSetting.IRequest;
}): Promise<IPageIDiscussionBoardBoardSetting> {
  const { admin, body } = props;

  // Pagination logic: use defaults if not provided
  const page = body.page ?? 1;
  const limit = body.limit ?? 100;

  const where = {
    ...(body.title !== undefined &&
      body.title !== null && {
        title: { contains: body.title, mode: "insensitive" as const },
      }),
    ...(body.enabled !== undefined &&
      body.enabled !== null && {
        enabled: body.enabled,
