import { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Creates a new administrator account for the discussion board.
 *
 * This endpoint allows only authenticated admins to create another admin
 * account. It accepts username, email, hashed password, and activation flag,
 * and ensures uniqueness of username/email. On success, returns the new admin
 * object (never includes password hash).
 *
 * @param props - Request parameters
 * @param props.admin - Authenticated admin performing the creation
 * @param props.body - Data for new admin: username, business email, password
 *   hash, and activation state
 * @returns Newly created administrator record excluding password hash
 * @throws {Error} When username or email is already used by another admin
 */
export async function post__discussionBoard_admin_admins(props: {
  admin: AdminPayload;
  body: IDiscussionBoardAdmin.ICreate;
}): Promise<IDiscussionBoardAdmin> {
  const { admin, body } = props;
  try {
    // Prepare ISO string timestamp for creation and update
    const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

    // Create the admin account
    const created = await MyGlobal.prisma.discussion_board_admins.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        username: body.username,
        password_hash: body.password_hash,
        email: body.email,
        is_active: body.is_active,
        created_at: now,
        updated_at: now,
      },
    });
    // Return the admin object, excluding password hash
    return {
      id: created.id,
      username: created.username,
      email: created.email,
      is_active: created.is_active,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
    };
  } catch (err) {
    // Prisma unique constraint violation (username or email)
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002"
    ) {
      throw new Error("Username or email already in use");
    }
    throw err;
  }
}

