export async function patch__discussionBoard_posts_$postId_comments(props: {
  postId: string & tags.Format<"uuid">;
  body: IDiscussionBoardComment.IRequest;
}): Promise<IPageIDiscussionBoardComment.ISummary> {
  const { postId, body } = props;

  // 1. Ensure the post exists
  const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
    where: { id: postId },
    select: { id: true },
  });
  if (!post) throw new Error("Post not found");

  // 2. Pagination values
  const page =
    body.page !== undefined && body.page !== null && body.page > 0
      ? Number(body.page)
      : 1;
  const limit =
    body.limit !== undefined && body.limit !== null && body.limit > 0
      ? Number(body.limit)
      : 20;
  const skip = (page - 1) * limit;

  // 3. Sorting by client selection or default
  const orderBy =
    body.sort === "created_at_asc"
      ? { created_at: "asc" as const }
      : body.sort === "updated_at_asc"
        ? { updated_at: "asc" as const }
        : body.sort === "updated_at_desc"
          ? { updated_at: "desc" as const }
          : { created_at: "desc" as const };

  // 4. Filtering logic
  const where = {
    discussion_board_post_id: postId,
    ...(body.discussion_board_member_id !== undefined &&
      body.discussion_board_member_id !== null && {
