  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_comments.findMany({
      where,
      orderBy,
      skip,
      take: limit,
      select: {
        id: true,
        discussion_board_member_id: true,
        discussion_board_post_id: true,
        parent_id: true,
        body: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.discussion_board_comments.count({ where }),
  ]);

  // 6. Map to API contract (all dates to string)
  return {
    pagination: typia.assert<IPage.IPagination>({
      current: page,
      limit,
      records: total,
      pages: Math.max(1, Math.ceil(total / limit)),
    }),
    data: rows.map((row) => ({
      id: row.id,
