import { MemberPayload } from "../decorators/payload/MemberPayload";

/**
 * Create a new comment in the discussion board (discussion_board_comments).
 *
 * Allows a member to create a new comment within a discussion board post or as
 * a reply to another comment. Validates all references, enforces non-empty
 * body, and ensures the comment is attributed to the logged-in member. The
 * creation and update timestamps are set on creation, and the returned object
 * is fully typed.
 *
 * - The target post must exist and not be soft-deleted.
 * - If a parent_id is provided, verifies the parent exists, is not deleted, and
 *   matches the post.
 * - The body must be non-empty/non-whitespace.
 *
 * @param props - Request properties
 * @param props.member - Authenticated member creating the comment
 *   (authorization checked upstream)
 * @param props.body - Comment creation data (includes post ID, optional parent
 *   ID, and comment body)
 * @returns The newly created comment with all associated metadata
 * @throws {Error} If the body is empty or whitespace
 * @throws {Error} If the post does not exist or is deleted
 * @throws {Error} If the parent comment (if provided) does not exist, is
 *   deleted, or is not part of the target post
 */
export async function post__discussionBoard_member_comments(props: {
  member: MemberPayload;
  body: IDiscussionBoardComment.ICreate;
}): Promise<IDiscussionBoardComment> {
  const { member, body } = props;

  // Validate non-empty, non-whitespace comment body
  if (!body.body || body.body.trim().length === 0) {
    throw new Error("Comment body cannot be empty or whitespace.");
  }

  // Validate the post exists and isn't soft-deleted
  const post = await MyGlobal.prisma.discussion_board_posts.findFirst({
    where: {
      id: body.discussion_board_post_id,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!post) {
    throw new Error("Post does not exist or has been deleted.");
  }

  // If parent_id is present, validate comment exists, isn't deleted, and matches the post
  if (body.parent_id !== undefined && body.parent_id !== null) {
    const parent = await MyGlobal.prisma.discussion_board_comments.findFirst({
      where: {
        id: body.parent_id,
        discussion_board_post_id: body.discussion_board_post_id,
        deleted_at: null,
      },
      select: { id: true },
    });
    if (!parent) {
      throw new Error(
        "Parent comment does not exist, is deleted, or does not belong to the same post.",
      );
    }
  }

  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.discussion_board_comments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      discussion_board_member_id: member.id,
      discussion_board_post_id: body.discussion_board_post_id,
      parent_id: body.parent_id ?? null,
      body: body.body,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  return {
    id: created.id,
    discussion_board_member_id: created.discussion_board_member_id,
    discussion_board_post_id: created.discussion_board_post_id,
    parent_id: created.parent_id ?? null,
    body: created.body,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at:
      created.deleted_at !== undefined && created.deleted_at !== null
        ? toISOStringSafe(created.deleted_at)
        : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
