import { MemberPayload } from "../decorators/payload/MemberPayload";

/**
 * Update an existing comment (discussion_board_comments) by ID.
 *
 * Updates the body or parent thread reference of an existing comment, enforcing
 * RBAC so only the comment's author can update their comment. Applies strict
 * validation for the body (must be non-null, non-empty, and non-whitespace),
 * and always updates the audit timestamp.
 *
 * @param props - Request object containing the authenticated member, commentId
 *   to update, and fields to be updated (body, parent_id).
 * @param props.member - Authenticated member performing the update (must be the
 *   comment's author).
 * @param props.commentId - The UUID of the comment to update.
 * @param props.body - Object specifying new body, parent_id values for the
 *   update.
 * @returns The updated comment object, with all fields and date values
 *   normalized to consistent formats.
 * @throws {Error} If the comment does not exist, if the member is not
 *   authorized, or if validation fails.
 */
export async function put__discussionBoard_member_comments_$commentId(props: {
  member: MemberPayload;
  commentId: string & tags.Format<"uuid">;
  body: IDiscussionBoardComment.IUpdate;
}): Promise<IDiscussionBoardComment> {
  const { member, commentId, body } = props;
  // 1. Fetch the comment by id
  const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
    where: { id: commentId },
  });
  if (!comment) throw new Error("Comment not found");

  // 2. Ensure current member is the author
  if (member.id !== comment.discussion_board_member_id) {
    throw new Error("Unauthorized: Only the author can edit this comment");
  }

  // 3. Validate body (if provided): must not be null, empty, or whitespace
  if (body.body !== undefined && (body.body === null || !body.body.trim())) {
    throw new Error(
      "Validation failed: 'body' must not be null, empty, or whitespace",
    );
  }

  // 4. Update allowed fields (body, parent_id if supplied), always updated_at
  const updated = await MyGlobal.prisma.discussion_board_comments.update({
    where: { id: commentId },
    data: {
      body: body.body !== undefined ? body.body : undefined,
      parent_id: body.parent_id !== undefined ? body.parent_id : undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // 5. Return normalized comment object, date fields as strings
  return {
    id: updated.id,
    discussion_board_member_id: updated.discussion_board_member_id,
    discussion_board_post_id: updated.discussion_board_post_id,
    parent_id: updated.parent_id ?? null,
    body: updated.body,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
