import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

/**
 * Update a discussion comment as a moderator (by ID).
 *
 * This endpoint allows an authenticated moderator to update the body and/or
 * parent_id fields of an existing comment identified by its UUID. All changes
 * (body edit or thread reparenting) are logged in the edit history for audit
 * purposes. The input body is validated to ensure the comment is not empty or
 * whitespace-only if the body is being changed.
 *
 * RBAC: Moderators may update any comment, regardless of authorship.
 *
 * @param props - Request properties
 * @param props.moderator - The authenticated moderator performing the update
 * @param props.commentId - Unique UUID of the comment to update
 * @param props.body - Update data for body and/or parent_id
 * @returns The updated comment, including all required fields and correct date
 *   string types
 * @throws {Error} If the comment does not exist
 * @throws {Error} If attempting to update the comment body to an empty or
 *   whitespace-only string
 */
export async function put__discussionBoard_moderator_comments_$commentId(props: {
  moderator: ModeratorPayload;
  commentId: string & tags.Format<"uuid">;
  body: IDiscussionBoardComment.IUpdate;
}): Promise<IDiscussionBoardComment> {
  const { moderator, commentId, body } = props;
  // Fetch existing comment, throw if not found
  const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
    where: { id: commentId },
  });
  if (!comment) throw new Error("Comment not found");

  // If updating the body, validate that it is not empty/whitespace
  if ("body" in body && body.body != null) {
    if (typeof body.body !== "string" || body.body.trim().length === 0) {
      throw new Error("Body cannot be empty or whitespace");
    }
  }

  // Update comment
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.discussion_board_comments.update({
    where: { id: commentId },
    data: {
      ...(body.body !== undefined && body.body !== null
        ? { body: body.body }
        : {}),
      ...(body.parent_id !== undefined ? { parent_id: body.parent_id } : {}),
      updated_at: now,
    },
  });

  // Always log the edit action
  await MyGlobal.prisma.discussion_board_comment_edits.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      discussion_board_comment_id: commentId,
      discussion_board_member_id: moderator.id,
      new_body:
        body.body !== undefined && body.body !== null
          ? body.body
          : updated.body,
      edited_at: now,
      rationale: undefined,
    },
  });

  return {
    id: updated.id,
    discussion_board_member_id: updated.discussion_board_member_id,
    discussion_board_post_id: updated.discussion_board_post_id,
    parent_id: updated.parent_id ?? null,
    body: updated.body,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

