import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { MemberPayload } from "../decorators/payload/MemberPayload";

/**
 * Soft-delete a comment (discussion_board_comments) by UUID.
 *
 * Implements a soft delete for a comment in the 'discussion_board_comments'
 * table by setting the 'deleted_at' timestamp to mark the comment as deleted.
 * Only the comment's author (member) may perform this operation. Attempts by
 * other users will be denied with an authorization error. If the comment is
 * already deleted, an error is thrown.
 *
 * Children comments are unaffected and remain intact for audit trail purposes.
 *
 * @param props - Request properties
 * @param props.member - Authenticated member performing the operation
 * @param props.commentId - UUID of the comment to soft-delete
 * @returns Void
 * @throws {Error} If comment is not found, already deleted, or if user is
 *   unauthorized.
 */
export async function delete__discussionBoard_member_comments_$commentId(props: {
  member: MemberPayload;
  commentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { member, commentId } = props;
  // Fetch the comment for verification
  const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
    where: { id: commentId },
    select: { id: true, discussion_board_member_id: true, deleted_at: true },
  });
  if (!comment) throw new Error("Comment not found");
  if (comment.deleted_at !== null && comment.deleted_at !== undefined) {
    throw new Error("Comment is already deleted");
  }
  if (comment.discussion_board_member_id !== member.id) {
    throw new Error("Unauthorized: Only the author can delete this comment");
  }
  // Soft-delete: set deleted_at to current ISO date string
  await MyGlobal.prisma.discussion_board_comments.update({
    where: { id: commentId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
}

