/**
 * Soft-delete a comment by UUID (admin operation).
 *
 * This operation sets the 'deleted_at' timestamp on the specified comment in
 * the 'discussion_board_comments' table, marking it as soft-deleted for
 * compliance and moderation auditing. Soft-deletion retains history and
 * preserves the comment for audit logging, but prevents standard visibility to
 * users. Only administrators may perform this operation. If the comment is
 * already deleted, an error is thrown.
 *
 * @param props - The deletion parameters
 * @param props.admin - The authenticated administrator performing the
 *   soft-delete operation
 * @param props.commentId - The UUID of the comment to soft-delete
 * @returns Void
 * @throws {Error} When the comment does not exist or has already been
 *   soft-deleted
 */
export async function delete__discussionBoard_admin_comments_$commentId(props: {
  admin: AdminPayload;
  commentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { commentId } = props;

  // Find the comment by id; throw if not found
  const comment =
    await MyGlobal.prisma.discussion_board_comments.findUniqueOrThrow({
      where: { id: commentId },
      select: { id: true, deleted_at: true },
    });

  // Check if already deleted
  if (comment.deleted_at !== null) {
    throw new Error(
      "Comment has already been deleted and cannot be deleted again.",
    );
  }

  // Prepare ISO string exactly once for the soft-delete timestamp
  const deletedAt: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(),
  );

  // Directly update the comment's deleted_at value (no intermediate variable)
  await MyGlobal.prisma.discussion_board_comments.update({
    where: { id: commentId },
    data: { deleted_at: deletedAt },
  });
