/**
 * Retrieve a list of all votes cast for a specific post, referenced by post
 * UUID. Returns whether each vote is an upvote or downvote, the voter member's
 * id, timestamps, and related audit parameters.
 *
 * - Only authenticated members may access full vote lists (enforced by MemberAuth
 *   decorator).
 * - Vote records returned for visible posts only (not soft-deleted).
 * - If the post does not exist or was deleted, throws a 404 error.
 * - Pagination parameters are static (returns all records), as no API input for
 *   page/limit exists.
 *
 * @param props - Request properties
 * @param props.member - The authenticated member making the request
 *   (MemberPayload)
 * @param props.postId - The UUID for which to list related votes
 * @returns Paginated set of all votes (IPageIDiscussionBoardPostVote) for the
 *   specified post
 * @throws {Error} When post does not exist or has been deleted
 */
export async function get__discussionBoard_member_posts_$postId_postVotes(props: {
  member: MemberPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<IPageIDiscussionBoardPostVote> {
  const { member, postId } = props;

  // 1. Verify post exists and is not soft-deleted
  const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
    where: { id: postId },
    select: { id: true, deleted_at: true },
  });
  if (!post || post.deleted_at !== null) {
    throw new Error("Not Found");
  }

  // 2. Query all votes for the post
  const votes = await MyGlobal.prisma.discussion_board_post_votes.findMany({
    where: { discussion_board_post_id: postId },
    orderBy: { created_at: "asc" },
  });

  // 3. Map to DTO and convert date/tags
  const data: IDiscussionBoardPostVote[] = votes.map((vote) => ({
    id: vote.id,
    discussion_board_post_id: vote.discussion_board_post_id,
    discussion_board_member_id: vote.discussion_board_member_id,
    upvote: vote.upvote,
    created_at: toISOStringSafe(vote.created_at),
  }));

  // 4. Construct pagination metadata (no real paging)
  const total = data.length;
  const pagination: IPage.IPagination = {
    current: 1 as number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
    limit: total as number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
    records: total as number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
    pages: 1 as number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
  };

  return {
    pagination,
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IPageIDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostVote";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

/**
 * Retrieve paginated list of all votes cast for a specific post.
 *
 * This endpoint allows a moderator to view every vote event (upvote/downvote)
 * for a post (by UUID) as recorded in 'discussion_board_post_votes'. Moderators
 * can access all audit fields, including voter id and timestamp.
 *
 * Typically used for engagement analytics, audit, or moderation dashboard
 * review. Handles scenarios such as soft-deleted posts or posts with no votes.
 *
 * @param props - Request properties
 * @param props.moderator - Authenticated moderator (RBAC verified)
 * @param props.postId - Target post UUID
 * @returns Paginated list of all votes for the target post (with audit info)
 * @throws {Error} Never thrown unless underlying DB/network error occurs.
 */
export async function get__discussionBoard_moderator_posts_$postId_postVotes(props: {
  moderator: ModeratorPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<IPageIDiscussionBoardPostVote> {
  const { postId } = props;
  // Defaults: 1st page, 100 per page
  const page = 1;
  const limit = 100;
  const skip = (page - 1) * limit;

  // 1. Query paginated vote records and total count in parallel
  const [records, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_post_votes.findMany({
      where: { discussion_board_post_id: postId },
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_post_votes.count({
      where: { discussion_board_post_id: postId },
    }),
  ]);

  // 2. Format rows to IDiscussionBoardPostVote shape (convert dates)
  const data = records.map((vote) => ({
    id: vote.id,
    discussion_board_post_id: vote.discussion_board_post_id,
    discussion_board_member_id: vote.discussion_board_member_id,
    upvote: vote.upvote,
    created_at: toISOStringSafe(vote.created_at),
  }));

  // 3. Compose pagination meta
  const pagination = {
    current: page,
    limit: limit,
    records: total,
    pages: Math.ceil(total / limit),
  };

  return {
    pagination,
    data,
  };
}

