  member: MemberPayload;
  commentId: string & tags.Format<"uuid">;
}): Promise<IPageIDiscussionBoardCommentVote> {
  const { commentId } = props;
  // Using default pagination: current=1, limit=100 (per IPageIDiscussionBoardCommentVote and test expectation)
  const current = 1;
  const limit = 100;

  // Step 1: Ensure the target comment exists
  const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
    where: { id: commentId },
  });
  if (!comment) throw new Error("Comment not found");

  // Step 2: Count total votes for the comment (for pagination)
  const totalRecords =
