 * Allows an authenticated member to submit a vote (upvote or downvote) for a
 * specific comment.
 *
 * This operation creates a new comment vote (discussion_board_comment_votes) as
 * a member. It strictly enforces the business rule: one vote per member per
 * comment (unique index), and will reject duplicate attempts. Vote metadata is
 * recorded for audit and analytics, including member, comment, type
 * (upvote/downvote), and timestamp.
 *
 * Security: Only members may vote. Attempts to vote again (update) should use
 * PUT on the vote itself. This strictly logs the member's engagement,
 * timestamp, and upvote/downvote polarity for moderation review.
 *
 * @param props - Request parameter object
 * @param props.member - The authenticated member making the vote (authorization
 *   enforced)
 * @param props.commentId - Unique identifier of the comment being voted on
 * @param props.body - Object containing the upvote/downvote indication
 * @returns The newly created comment vote (ID, comment, member, type,
 *   timestamp)
 * @throws {Error} If the target comment does not exist
 * @throws {Error} If the member has already voted on this comment
 */
export async function post__discussionBoard_member_comments_$commentId_commentVotes(props: {
  member: MemberPayload;
  commentId: string & tags.Format<"uuid">;
  body: IDiscussionBoardCommentVote.ICreate;
}): Promise<IDiscussionBoardCommentVote> {
  const { member, commentId, body } = props;

  // 1. Validate target comment exists
  const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
    where: { id: commentId },
    select: { id: true },
  });
  if (!comment) throw new Error("Comment not found");

  // 2. Attempt to insert the vote (one per member per comment enforced by unique index)
  try {
    const created = await MyGlobal.prisma.discussion_board_comment_votes.create(
      {
        data: {
          id: v4() as string & tags.Format<"uuid">,
          discussion_board_comment_id: commentId,
          discussion_board_member_id: member.id,
          upvote: body.upvote,
          created_at: toISOStringSafe(new Date()),
        },
      },
    );
    return {
      id: created.id,
      discussion_board_comment_id: created.discussion_board_comment_id,
      discussion_board_member_id: created.discussion_board_member_id,
      upvote: created.upvote,
      created_at: toISOStringSafe(created.created_at),
    };
  } catch (err) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002"
    ) {
      throw new Error(
        "You have already voted on this comment. One vote per member per comment is allowed.",
      );
    }
    throw err;
  }
}

