/**
 * Fetch all tag assignments (post-tag associations) for a post by its unique
 * identifier.
 *
 * Fetches all tag assignments for a post by its ID using the normalized
 * 'discussion_board_post_tags' junction table. Returns results in
 * IPageIDiscussionBoardPostTag format with default pagination.
 *
 * @param props - Request properties
 * @param props.member - The authenticated discussion board member
 * @param props.postId - UUID of the post whose tags are to be listed
 * @returns Paginated list of post-tag assignment records for the post
 * @throws {Error} When the post does not exist
 */
export async function get__discussionBoard_member_posts_$postId_postTags(props: {
  member: MemberPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<IPageIDiscussionBoardPostTag> {
  const { postId } = props;
  const page = 1;
  const limit = 100;

  // 1. Ensure post exists for the given ID
  const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
    where: { id: postId },
    select: { id: true },
  });
  if (!post) {
    throw new Error("Post not found");
  }

  // 2. Get tag assignments (normalized association)
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_post_tags.findMany({
      where: { discussion_board_post_id: postId },
      select: {
        id: true,
        discussion_board_post_id: true,
        discussion_board_tag_id: true,
      },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_post_tags.count({
      where: { discussion_board_post_id: postId },
    }),
  ]);

  // 3. Return paginated result according to DTO contract
  return {
    pagination: {
      current: page as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      limit: limit as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: total as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(total / limit) as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data: rows.map((r) => ({
      id: r.id as string & tags.Format<"uuid">,
      discussion_board_post_id: r.discussion_board_post_id as string &
        tags.Format<"uuid">,
      discussion_board_tag_id: r.discussion_board_tag_id as string &
        tags.Format<"uuid">,
    })),
  };
}

