 * @param props.member - The authenticated member payload, enforced by
 *   MemberAuth decorator.
 * @param props.postId - Unique identifier of the post whose tag associations
 *   will be searched (UUID).
 * @param props.body - Search and pagination options
 *   (IDiscussionBoardPostTag.IRequest).
 * @returns Paginated list of IDiscussionBoardPostTag plus pagination metadata.
 * @throws {Error} When not authenticated as a member, or when postId is not
 *   provided.
 */
export async function patch__discussionBoard_member_posts_$postId_postTags(props: {
  member: import("../decorators/payload/MemberPayload").MemberPayload;

  postId: string & import("typia").tags.Format<"uuid">;

  body: import("../api/structures/IDiscussionBoardPostTag").IDiscussionBoardPostTag.IRequest;
}): Promise<
  import("../api/structures/IPageIDiscussionBoardPostTag").IPageIDiscussionBoardPostTag
> {
  const { member, postId, body } = props;
  if (!member) {
    throw new Error("Unauthorized: member authentication required");
  }
  if (!postId) {
    throw new Error("postId must be provided");
  }
  const page =
    body.page && body.page > 0
      ? (body.page as number &
          import("typia").tags.Type<"int32"> &
          import("typia").tags.JsonSchemaPlugin<{ format: "uint32" }>)
      : (1 as number &
          import("typia").tags.Type<"int32"> &
          import("typia").tags.JsonSchemaPlugin<{ format: "uint32" }>);

  const limit =
    body.limit && body.limit > 0
      ? (body.limit as number &
