    ...(body.discussion_board_tag_id !== undefined &&
      body.discussion_board_tag_id !== null && {
        discussion_board_tag_id: body.discussion_board_tag_id,
      }),
  };
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_post_tags.findMany({
      where,
      skip,
      take: limit,
      orderBy: { id: "asc" },
      select: {
        id: true,
        discussion_board_post_id: true,
        discussion_board_tag_id: true,
      },
    }),
    MyGlobal.prisma.discussion_board_post_tags.count({ where }),
  ]);
