    (
      row,
    ): import("../api/structures/IDiscussionBoardPostTag").IDiscussionBoardPostTag => ({
      id: row.id,
      discussion_board_post_id: row.discussion_board_post_id,
      discussion_board_tag_id: row.discussion_board_tag_id,
    }),
  );
  return {
    data,
    pagination: {
      current: page,
      limit,
      records: total as number &
        import("typia").tags.Type<"int32"> &
        import("typia").tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(total / limit) as number &
        import("typia").tags.Type<"int32"> &
        import("typia").tags.JsonSchemaPlugin<{ format: "uint32" }>,
