import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostTag";
import { MemberPayload } from "../decorators/payload/MemberPayload";

/**
 * Assign a new tag to a post (attach tag via post-tag junction entity).
 *
 * Only post authors may add tags to their posts (enforced by ownership check).
 * Moderators/admins may have this authority via higher-level policies, but this
 * function enforces at least author-only at service-level.
 *
 * Duplicate assignments are prevented via schema-level unique constraint;
 * friendly error is returned on violation. All referenced post and tag IDs are
 * validated for existence.
 *
 * @param props - Function properties object
 * @param props.member - Payload for the authenticated member
 * @param props.postId - UUID of the post to which the tag is being assigned
 * @param props.body - Tag assignment input (must specify post, tag)
 * @returns IDiscussionBoardPostTag row object containing ID, post, and tag IDs
 * @throws {Error} When post/tag does not exist, or member does not own the
 *   post, or tag is already assigned
 */
export async function post__discussionBoard_member_posts_$postId_postTags(props: {
  member: MemberPayload;
  postId: string & tags.Format<"uuid">;
  body: IDiscussionBoardPostTag.ICreate;
}): Promise<IDiscussionBoardPostTag> {
  const { member, postId, body } = props;

  // 1. Verify the post exists and belongs to the requesting member
  const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
    where: { id: postId },
  });
  if (!post) throw new Error("Post does not exist");
  if (post.discussion_board_member_id !== member.id)
    throw new Error("Forbidden: Only the author may tag their post");

  // 2. Verify the tag exists
  const tag = await MyGlobal.prisma.discussion_board_tags.findUnique({
    where: { id: body.discussion_board_tag_id },
  });
  if (!tag) throw new Error("Tag does not exist");

  // 3. Try to create the association (unique constraint protects against duplicate)
  try {
    const created = await MyGlobal.prisma.discussion_board_post_tags.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        discussion_board_post_id: postId,
        discussion_board_tag_id: body.discussion_board_tag_id,
      },
    });
    return {
      id: created.id,
      discussion_board_post_id: created.discussion_board_post_id,
      discussion_board_tag_id: created.discussion_board_tag_id,
    };
  } catch (err) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002"
    ) {
      throw new Error("This tag is already assigned to the post");
    }
    throw err;
  }
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IDiscussionBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostTag";
import { MemberPayload } from "../decorators/payload/MemberPayload";

/**
 * Update a post-tag association for a post.
 *
 * This endpoint allows the authenticated post author (member) to update a
 * specific post-tag assignment to either reassign it to another post or tag,
 * subject to uniqueness constraints.
 *
 * Errors:
 *
 * - Throws if the target post-tag record does not exist.
 * - Throws if the post does not exist.
 * - Throws if the authenticated member is not the author of the post.
 * - Throws if the operation would violate the unique post+tag assignment
 *   constraint.
 *
 * @param props - Request properties
 * @param props.member - Authenticated member (must be the post's author)
 * @param props.postId - The UUID of the post associated with this post-tag
 *   record
 * @param props.postTagId - The UUID of the post-tag junction record to update
 * @param props.body - Fields to update (either or both of post id and tag id)
 * @returns The updated post-tag association (id, post_id, tag_id)
 * @throws {Error} If the post-tag association or post is not found, or if
 *   unauthorized or uniqueness is violated
 */
export async function put__discussionBoard_member_posts_$postId_postTags_$postTagId(props: {
  member: MemberPayload;
  postId: string & tags.Format<"uuid">;
  postTagId: string & tags.Format<"uuid">;
  body: IDiscussionBoardPostTag.IUpdate;
}): Promise<IDiscussionBoardPostTag> {
  const { member, postId, postTagId, body } = props;

  // Fetch post-tag association
  const postTag = await MyGlobal.prisma.discussion_board_post_tags.findUnique({
    where: { id: postTagId },
  });
  if (!postTag) throw new Error("Post-tag association not found");

  // Decide effective post and tag ids for uniqueness and auth
  const effectivePostId =
    body.discussion_board_post_id ?? postTag.discussion_board_post_id;
  const effectiveTagId =
    body.discussion_board_tag_id ?? postTag.discussion_board_tag_id;

  // Fetch and authorize the post by new/old postId
  const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
    where: { id: effectivePostId },
    select: { id: true, discussion_board_member_id: true },
  });
  if (!post) throw new Error("Post not found");
  if (post.discussion_board_member_id !== member.id)
    throw new Error(
      "Unauthorized: only the post author may update tag assignments",
    );

  // Check uniqueness (no duplicate post+tag pair other than this one)
  if (
    effectivePostId !== postTag.discussion_board_post_id ||
    effectiveTagId !== postTag.discussion_board_tag_id
  ) {
    const collision =
      await MyGlobal.prisma.discussion_board_post_tags.findFirst({
        where: {
          discussion_board_post_id: effectivePostId,
          discussion_board_tag_id: effectiveTagId,
          id: { not: postTagId },
        },
      });
    if (collision)
      throw new Error("Duplicate post-tag assignment for this post and tag.");
  }

  // Execute the update
  const updated = await MyGlobal.prisma.discussion_board_post_tags.update({
    where: { id: postTagId },
    data: {
      discussion_board_post_id: body.discussion_board_post_id ?? undefined,
      discussion_board_tag_id: body.discussion_board_tag_id ?? undefined,
    },
  });

  return {
    id: updated.id,
    discussion_board_post_id: updated.discussion_board_post_id,
    discussion_board_tag_id: updated.discussion_board_tag_id,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { MemberPayload } from "../decorators/payload/MemberPayload";

/**
 * Removes an existing tag from a post by deleting the post-tag association.
 *
 * This operation deletes the post-tag association (discussion_board_post_tags)
 * for the given post. Only the author of the post may remove a tag, and only if
 * the post is not soft deleted (deleted_at is null). Deletion cannot be
 * reverted except by re-creation, as the schema does not support soft delete
 * for this association. All removals are logged for audit elsewhere in the
 * system.
 *
 * @param props - Request properties
 * @param props.member - The authenticated member performing the action
 * @param props.postId - The post from which to remove the tag
 * @param props.postTagId - The post-tag association to remove
 * @returns Void
 * @throws {Error} When the association does not exist for the post, post is not
 *   found, user is not owner, or post is deleted
 */
export async function delete__discussionBoard_member_posts_$postId_postTags_$postTagId(props: {
  member: MemberPayload;
  postId: string & tags.Format<"uuid">;
  postTagId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { member, postId, postTagId } = props;

  // 1. Find the post-tag association by id
  const postTag = await MyGlobal.prisma.discussion_board_post_tags.findUnique({
    where: { id: postTagId },
  });
  if (!postTag) {
    throw new Error("Post-tag association not found");
  }
  if (postTag.discussion_board_post_id !== postId) {
    throw new Error("Association does not belong to the given post");
  }

  // 2. Find the post and check ownership and soft delete
  const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
    where: { id: postId },
    select: { discussion_board_member_id: true, deleted_at: true },
  });
  if (!post) {
    throw new Error("Post not found");
  }
  if (post.discussion_board_member_id !== member.id) {
    throw new Error("Unauthorized: Only the post author may remove post tags");
  }
  if (post.deleted_at !== null) {
    throw new Error("Cannot modify post-tags on a deleted post");
  }

  // 3. Delete the association (hard delete)
  await MyGlobal.prisma.discussion_board_post_tags.delete({
    where: { id: postTagId },
  });
  // No return value
}

