    ...(body.status != null && { status: body.status }),
    ...(body.category != null && { category: body.category }),
    ...(body.reporter_member_id != null && {
      reporter_member_id: body.reporter_member_id,
    }),
    ...(body.discussion_board_post_id != null && {
      discussion_board_post_id: body.discussion_board_post_id,
    }),
    ...(body.discussion_board_comment_id != null && {
      discussion_board_comment_id: body.discussion_board_comment_id,
    }),
    ...(body.content_type != null && { content_type: body.content_type }),
    ...(body.date_from != null || body.date_to != null
      ? {
          reported_at: {
            ...(body.date_from != null && { gte: body.date_from }),
            ...(body.date_to != null && { lte: body.date_to }),
          },
        }
      : {}),
  };

  // Fetch reports and total count concurrently
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_content_reports.findMany({
      where,
      orderBy: { reported_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_content_reports.count({ where }),
  ]);

  // Transform to API DTOs, ensuring date/uuid branding and conversion
  const data = rows.map((row) => ({
    id: row.id,
    reporter_admin_id: row.reporter_admin_id ?? undefined,
    reporter_moderator_id: row.reporter_moderator_id ?? undefined,
    reporter_member_id: row.reporter_member_id ?? undefined,
    reporter_guest_id: row.reporter_guest_id ?? undefined,
    discussion_board_post_id: row.discussion_board_post_id ?? undefined,
    discussion_board_comment_id: row.discussion_board_comment_id ?? undefined,
    content_type: row.content_type,
    category: row.category,
    reason: row.reason,
    status: row.status,
    reported_at: toISOStringSafe(row.reported_at),
    resolved_at: row.resolved_at ? toISOStringSafe(row.resolved_at) : null,
  }));

  // Coerce pagination info to fully branded types
  const current = typia.assert<
    number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
  >(page);
  const brandedLimit = typia.assert<
    number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
  >(limit);
  const brandedRecords = typia.assert<
    number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
  >(total);
  const pages = typia.assert<
    number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
  >(Math.ceil(total / limit));

  return {
    pagination: {
      current,
      limit: brandedLimit,
      records: brandedRecords,
      pages,
    },
    data,
  };
}

