 * moderation or abuse report for a specific post or comment. Only one of
 * discussion_board_post_id or discussion_board_comment_id should be set (based
 * on the content_type). All referenced content is strictly validated for
 * existence, and duplicate reports by the same moderator for the same
 * content/category/reason are not allowed. On successful creation, the new
 * report is added in 'pending' status, and timestamps are managed in strict
 * ISO8601 format as required by audit/compliance.
 *
 * @param props - Request properties
 * @param props.moderator - The authenticated moderator submitting the report
 * @param props.body - Content report details including content target, reason,
 *   and category
 * @returns The newly created moderation content report
 * @throws {Error} If the referenced content does not exist
 * @throws {Error} If the moderator has already reported the same content for
 *   the same reason and category
 * @throws {Error} If the input does not specify a valid content type and object
 *   of interest
 */
export async function post__discussionBoard_moderator_contentReports(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardContentReport.ICreate;
}): Promise<IDiscussionBoardContentReport> {
  const { moderator, body } = props;

  typia.assert<IDiscussionBoardContentReport.ICreate>(body);

  // Enforce mutually exclusive content target
  const isPost =
    body.content_type === "post" && body.discussion_board_post_id != null;
  const isComment =
    body.content_type === "comment" && body.discussion_board_comment_id != null;
  if (!isPost && !isComment) {
    throw new Error(
      "You must provide a valid post or comment target, matching the content_type.",
    );
  }

  // Validate referenced content for existence
  if (isPost) {
    const post = await MyGlobal.prisma.discussion_board_posts.findUnique({
      where: { id: body.discussion_board_post_id! },
      select: { id: true },
    });
    if (!post) throw new Error("The referenced post does not exist.");
