  // Duplicate prevention: No prior report for same target, category, reason by this moderator
  const duplicate =
    await MyGlobal.prisma.discussion_board_content_reports.findFirst({
      where: {
        reporter_moderator_id: moderator.id,
        ...(isPost
          ? { discussion_board_post_id: body.discussion_board_post_id }
          : { discussion_board_comment_id: body.discussion_board_comment_id }),
        category: body.category,
        reason: body.reason,
      },
      select: { id: true },
    });
  if (duplicate) {
    throw new Error(
      "Duplicate report: You have already reported this content for this reason and category.",
    );
  }

  // Timestamp for report filing
  const reported_at: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(),
  );

  // Create new moderation report
  const created = await MyGlobal.prisma.discussion_board_content_reports.create(
    {
      data: {
        id: v4() as string & tags.Format<"uuid">,
        reporter_admin_id: null,
        reporter_moderator_id: moderator.id,
        reporter_member_id: null,
        reporter_guest_id: null,
        discussion_board_post_id: isPost ? body.discussion_board_post_id : null,
        discussion_board_comment_id: isComment
          ? body.discussion_board_comment_id
          : null,
        content_type: body.content_type,
        category: body.category,
        reason: body.reason,
        status: "pending",
        reported_at,
        resolved_at: null,
      },
      select: {
        id: true,
        reporter_admin_id: true,
        reporter_moderator_id: true,
        reporter_member_id: true,
        reporter_guest_id: true,
        discussion_board_post_id: true,
        discussion_board_comment_id: true,
        content_type: true,
        category: true,
        reason: true,
        status: true,
        reported_at: true,
        resolved_at: true,
      },
    },
  );

  return {
    id: created.id,
    reporter_admin_id: created.reporter_admin_id,
    reporter_moderator_id: created.reporter_moderator_id,
    reporter_member_id: created.reporter_member_id,
    reporter_guest_id: created.reporter_guest_id,
    discussion_board_post_id: created.discussion_board_post_id,
    discussion_board_comment_id: created.discussion_board_comment_id,
    content_type: created.content_type,
    category: created.category,
    reason: created.reason,
    status: created.status,
    reported_at: toISOStringSafe(created.reported_at),
    resolved_at: created.resolved_at
      ? toISOStringSafe(created.resolved_at)
