    records: count as number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
    pages: 1 as number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
  };

  const data = rows.map(
    (row): IDiscussionBoardSuspension => ({
