 * @returns Paginated list of IDiscussionBoardNotificationSetting objects for
 *   the authenticated admin only
 * @throws {Error} If a database error occurs
 */
export async function get__discussionBoard_admin_notificationSettings(props: {
  admin: AdminPayload;
}): Promise<IPageIDiscussionBoardNotificationSetting> {
  const { admin } = props;
  const current = 1;
  const limit = 100;

  const [settings, totalRecords] = await Promise.all([
    MyGlobal.prisma.discussion_board_notification_settings.findMany({
      where: { admin_id: admin.id },
      orderBy: { created_at: "desc" },
      skip: 0,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_notification_settings.count({
      where: { admin_id: admin.id },
    }),
  ]);

